"""Original authoring source; helpers assemble fields, never generate Spanish stories."""
from pathlib import Path
import json
OUT=Path(__file__).resolve().parents[2]/'www'
def core(model,translation,gap,wrong,why,dialogue,response,distractors,transfer,target,variants=[]):
 return dict(model=model,translation=translation,gap=gap,gapWrong=wrong,wrong=[model.replace(gap,x,1) for x in wrong],why=why,ask='Elige la frase que comunica: «'+translation+'».',help='Choose the response meaning: '+translation,dialogue=[dialogue,'Choose the appropriate response to this exchange.',response,distractors,why],transfer=[transfer,'Respond to the Spanish situation using the taught language.',target,variants,why])
def story(title,text,gloss,context,answer,wrong,cause,causeanswer,causevariants,inference,inferanswer,inferwrong,view,viewanswer,viewvariants,response,reply,replywrong,why):
 return dict(title=title,text=text,glossary=gloss,questions=[[context,'Read the situation and choose the supported interpretation.',answer,wrong,why],[cause,'Explain the reason using a short English or Spanish response.',causeanswer,causevariants,why],[inference,'Choose the implication supported by the passage.',inferanswer,inferwrong,why],[view,'Give a short response about the speaker’s viewpoint.',viewanswer,viewvariants,why],[response,'Choose the response appropriate to the passage.',reply,replywrong,why]])
def audio(clip,prompt,answer,wrong,why):return [clip,prompt,'Listen and choose the supported meaning.',answer,wrong,why]
def audio_text(clip,prompt,answer,variants,why):return [clip,prompt,'Listen and give a short answer in English or Spanish.',answer,variants,why]
def writing(es,en,model,mode='guided',requirements=[],why='Compare meaning, organisation and the taught language. This is one possible response, not the only valid formulation.',variants=[]):return dict(es=es,en=en,model=model,mode=mode,requirements=[dict(label=x,any=y) for x,y in requirements],why=why,variants=variants)
def unit(title,goal,grammar,cores,stories,audios,writings):return dict(title=title,goal=goal,grammar=grammar,core=cores,stories=stories,audio=audios,writing=writings)
def save(stage,units):
 code=stage.replace('.','').lower();name=code.upper()+'Data';data=dict(stage=stage,code=code,units=units)
 (OUT/(code+'-data.js')).write_text('(function(root){\n\'use strict\';\nconst data='+json.dumps(data,ensure_ascii=False,indent=1)+';\nroot.'+name+'=data;if(typeof module!==\'undefined\')module.exports=data;\n})(typeof window===\'undefined\'?globalThis:window);\n')
def episode(title,text,gloss,q1,a1,w1,q2,a2,v2,q3,a3,w3,q4,a4,v4,q5,a5,w5,why):return story(title,text,gloss,q1,a1,w1,q2,a2,v2,q3,a3,w3,q4,a4,v4,q5,a5,w5,why)
def prod(topic,controlled,models,requirements):
 # Five deliberately distinct tasks: retrieval, directed message, transformation,
 # independent scenario, and integrated outcome. Models are authored per unit.
 return [writing(controlled[0],controlled[1],controlled[2],'controlled'),writing(models[0][0],models[0][1],models[0][2],'guided',requirements),writing(controlled[3],controlled[4],controlled[5],'controlled'),writing(models[1][0],models[1][1],models[1][2],'guided',requirements),writing(models[2][0],models[2][1],models[2][2],'free',requirements)]
b11=[]
b11.append(unit('Telling the story','Narrate an unexpected event with background, sequence and outcome','Past integration; primero, mientras, de repente, al final',[
core('Estaba esperando el autobús cuando empezó a llover.','I was waiting for the bus when it started to rain.','Estaba',['Estuve','Estoy'],'Estaba frames the ongoing scene; empezó introduces a new event.','Luis: «¿Qué hacías cuando empezó la lluvia?»','Estaba esperando el autobús.',['Esperaré ayer.','He esperado mañana.'],'Esperabas el tren. De repente llegó Marta. Cuenta el encuentro.','Estaba esperando el tren cuando llegó Marta.'),
core('Primero llamé a Luis y después buscamos un taxi.','First I called Luis and then we looked for a taxi.','llamé',['llamaba','llamaré'],'These completed actions follow a clear order.','Marta: «¿Qué hicisteis después de la llamada?»','Buscamos un taxi.',['Buscaremos ayer.','Llamaremos mañana.'],'Primero compraste el billete; después subiste al tren.','Primero compré el billete y después subí al tren.'),
core('Al final llegamos a tiempo, aunque estábamos cansados.','In the end we arrived on time, although we were tired.','llegamos',['llegar','llegaremos'],'The past context makes llegamos a completed arrival; aunque adds a contrast.','Ana: «¿Cómo terminó el viaje?»','Llegamos a tiempo, aunque estábamos cansados.',['Nunca salimos.','Estamos en casa mañana.'],'Llegaste tarde, pero encontraste a tus amigos. Cuenta el resultado.','Al final llegué tarde, pero encontré a mis amigos.')],[
episode('Un paraguas compartido','Ana esperaba el autobús delante del mercado. Salió sin paraguas porque el cielo estaba claro. Mientras consultaba el horario, empezó a llover. Primero se puso junto a una tienda y después llamó a Luis. Él estaba cerca y llevaba un paraguas grande. De repente llegó el autobús, pero no paró en aquella esquina: las obras cambiaron la parada. Un empleado les señaló la siguiente calle. Caminaron juntos hasta allí. Al final subieron al autobús y llegaron al cine antes de empezar la película. Ana se rio de su plan: organizó las entradas, pero no miró el tiempo. Luis dijo que compartir el paraguas fue la parte más divertida.',[['las obras','roadworks'],['la esquina','corner']], '¿Qué cambió el recorrido?','La parada estaba en otra calle.',['No tenían entradas.','Luis perdió el paraguas.'],'¿Por qué Ana salió sin paraguas?','El cielo estaba claro.',['The sky was clear.'],'¿Para qué sirvió la ayuda del empleado?','Encontraron la nueva parada.',['Terminó la lluvia.','Cambió la película.'],'¿Qué valoró Luis?','Compartir el paraguas.',['Sharing the umbrella.'],'¿Qué resumen encaja?','Hubo un imprevisto, pero llegaron a tiempo.',['Todo salió exactamente como estaba previsto.','No llegaron al cine.'],'The ending distinguishes an unexpected problem from a successful result.'),
episode('La llamada del museo','Luis enseñaba el museo a su prima Elena cuando recibió una llamada de Ana. Al principio no la oyó bien porque había mucha gente en la sala. Salieron al patio y Ana repitió su propuesta: tenía una entrada extra para un concierto. Elena quería conocer música de la ciudad y aceptó. Primero terminaron la visita; después comieron cerca del museo. Mientras esperaban la comida, miraron cómo llegar al concierto en autobús. Al final encontraron a Ana junto a la entrada. Elena pensaba volver pronto a casa. El cambio de plan le dio una tarde diferente y una nueva amiga. Luis contó después que no organizó aquella tarde tan bien: simplemente aprovechó una invitación inesperada.',[['el patio','courtyard'],['aprovechó','made the most of']], '¿Qué añadió la llamada al día?','Un concierto después del museo.',['Una visita cancelada.','Una noche de trabajo.'],'¿Por qué salieron al patio?','Había ruido dentro.',['It was noisy inside.'],'¿Qué indica que no salieron inmediatamente?','Terminaron la visita antes.',['Ana estaba en el autobús.','El museo estaba cerrado.'],'¿Qué ganó Elena?','Una nueva amiga.',['A new friend.'],'¿Cómo puede contar la secuencia?','Visitamos el museo y después fuimos al concierto.',['No salimos de casa.','Mañana vimos el concierto.'],'The invitation changes the later plan, not the visit already under way.'),
episode('Las llaves del local','Marta iba a abrir el local de la asociación a las seis. Un grupo de vecinos esperaba fuera para preparar una cena. Cuando buscó las llaves, vio que llevaba las de su casa. Primero llamó a Diego, que guardaba una copia, pero él estaba trabajando. Mientras los vecinos organizaban las mesas en el patio, Marta fue al café a recoger las llaves. Volvió en diez minutos y todos entraron. Nadie tuvo que cancelar la cena. Marta pidió disculpas. Una vecina le dijo que la espera no fue tiempo perdido: prepararon el patio y conocieron a dos personas nuevas. El pequeño retraso cambió el principio del encuentro, pero no arruinó la cena.',[['una copia','a spare copy'],['arruinó','ruined']], '¿Qué causó el retraso?','Marta llevaba otras llaves.',['El local estaba lleno.','La cena terminó.'],'¿Por qué llamó a Diego?','Tenía una copia.',['He had a spare key.'],'¿Qué hicieron los vecinos mientras esperaban?','Prepararon el patio.',['Se fueron todos.','Compraron llaves.'],'¿Cómo valoró la espera una vecina?','No fue tiempo perdido.',['It was not wasted time.'],'¿Qué disculpa encaja?','Perdonad el retraso; llevé las llaves equivocadas.',['No hay ninguna puerta.','Llegasteis mañana.'],'The initial mistake, solution and reaction are separate parts of the story.'),
episode('Dos versiones','Ana y Diego contaron la misma excursión de formas distintas. Ana empezó por la lluvia: caminaban junto al río cuando llegó una tormenta. Diego empezó por la solución: encontraron una cafetería abierta. Primero pidieron bebidas calientes; después preguntaron por el próximo autobús. Mientras esperaban, una señora explicó un camino más corto hasta la estación. Al final volvieron sin problemas. Ana decía que el día fue un desastre porque no vieron el paisaje. Diego no estaba de acuerdo: conversaron con gente nueva y descubrieron un café agradable. Ninguno inventaba los hechos. Elegían detalles distintos para explicar cómo vivieron la tarde. Luis escuchó las dos versiones y entendió mejor lo ocurrido.',[['el paisaje','landscape'],['los hechos','facts']], '¿Por qué difieren las versiones?','Destacan aspectos diferentes.',['No fueron juntos.','Ocurrieron en distintas ciudades.'],'¿Por qué entraron en el café?','Por la tormenta.',['Because of the storm.'],'¿Qué puede concluir Luis?','Una experiencia admite distintas valoraciones.',['Uno necesariamente miente.','Nadie volvió.'],'¿Qué valoró Diego?','La conversación y el café.',['The conversation and the café.'],'¿Qué resumen respeta ambas versiones?','La lluvia cambió el plan; encontraron una alternativa.',['No llovió.','Nunca encontraron refugio.'],'Viewpoint changes which details matter, not the shared facts.')],[audio('Esperábamos delante del cine. De repente llegó Luis con las entradas. Primero entramos y después buscamos los asientos.','¿Qué pasó antes de entrar?','Luis llegó con las entradas.',['Buscaron los asientos.','Terminó la película.'],'The arrival precedes entry.'),audio_text('Ana preparaba la cena cuando llamaron a la puerta. Era Marta. Primero hablaron en la cocina y después cenaron juntas.','¿Qué hacía Ana al principio?','Preparaba la cena.',['She was preparing dinner.','Estaba preparando la cena.'],'The ongoing background is preparing dinner.')],prod('narration',['Escribe «I was reading when Luis called».','Translate the given sentence.','Estaba leyendo cuando Luis llamó.','Une en orden: compré entradas; esperé a Ana.','Link buying tickets and then waiting.','Primero compré las entradas y después esperé a Ana.'],[('Cuenta un retraso: dónde estabas, qué pasó y cómo terminó.','Describe a delay and outcome.','Estaba en la estación cuando anunciaron un retraso. Llamé a Marta y al final llegamos juntos.'),('Cuenta una tarde inesperada en cuatro frases.','Narrate an unexpected afternoon.','Esperaba el autobús cuando empezó a llover. Llamé a Luis. Encontramos un café. Al final pasamos una tarde agradable.'),('Escribe un mensaje sobre un imprevisto y su solución.','Explain an unexpected problem and solution.','Estaba esperando el tren cuando anunciaron un retraso. Primero llamé a Ana y después tomé el autobús. Al final llegué a tiempo.')],[('Da un contexto',['estaba','cuando']),('Ordena hechos',['primero','después']),('Cuenta el resultado',['al final'])])))
# Concise authoring notation retains five independent, passage-supported questions.
def scene(title,text,gloss,fact,cause,infer,view,response,why):
 return episode(title,text,gloss,*fact[:2],fact[2:],*cause[:2],cause[2:],*infer[:2],infer[2:],*view[:2],view[2:],*response[:2],response[2:],why)
b11.append(unit('Things that have changed','Compare past and present habits and explain how long a change has lasted','Antes/ahora, ya no, todavía, desde, desde hace, hace… que',[
core('Antes trabajaba en el café, pero ahora trabajo en casa.','I used to work in the café, but now I work at home.','trabajaba',['trabajo','trabajaré'],'Imperfect describes the old routine; present describes now.','Luis: «¿Sigues trabajando en el café?»','No, ya no trabajo allí.',['Sí, nunca trabajé mañana.','Todavía no ayer.'],'Antes estudiabas por la noche. Ahora estudias por la mañana.','Antes estudiaba por la noche, pero ahora estudio por la mañana.'),
core('Vivo aquí desde hace dos años.','I have lived here for two years.','desde hace',['desde','durante ayer'],'Desde hace introduces an elapsed duration extending to now; desde introduces a starting point.','Marta: «¿Desde cuándo vives aquí?»','Vivo aquí desde 2024.',['Desde hace 2024.','Hasta ayer mañana.'],'Llevas tres meses estudiando español. Usa desde hace.','Estudio español desde hace tres meses.'),
core('Ya no voy en coche, pero todavía tengo el mismo trabajo.','I no longer go by car, but I still have the same job.','Ya no',['Todavía','Ya'],'Ya no marks a stopped habit; todavía marks what continues.','Ana: «¿Has cambiado de trabajo?»','No, todavía tengo el mismo trabajo.',['Sí, todavía nunca.','No trabajo todavía ayer.'],'Ya no vives en Madrid; aún tienes amigos allí.','Ya no vivo en Madrid, pero todavía tengo amigos allí.')],[
scene('La bicicleta de Clara','Clara trabaja en la biblioteca desde hace tres años. Antes iba en coche porque vivía lejos. Ahora vive cerca y va en bicicleta casi todos los días. Ya no necesita buscar aparcamiento, pero todavía sale pronto: le gusta desayunar con sus compañeros antes de abrir. Luis pensaba que Clara cambió de empleo al mudarse. Ella explicó que el trabajo es el mismo; solo cambió el trayecto. Los días de lluvia toma el autobús. No quiere vender el coche todavía porque visita a sus padres en un pueblo sin buena conexión. Dice que usar menos el coche no significa dejar de usarlo por completo. El cambio facilita su rutina sin resolver todos los viajes.',[['el trayecto','journey'],['aparcamiento','parking']],['¿Qué cambió Clara?','Su forma de llegar al trabajo.','Su profesión.','El horario de la biblioteca.'],['¿Por qué usa ahora la bicicleta?','Vive cerca.','She lives nearby.'],['¿Por qué conserva el coche?','Algunos viajes todavía lo necesitan.','No sabe ir en bicicleta.','La biblioteca está lejos.'],['¿Cómo entiende el cambio?','No tiene que ser absoluto.','It need not be an absolute change.'],['Luis pregunta por su empleo. ¿Qué responde?','Todavía trabajo en la misma biblioteca.','Ya no vivo cerca.','Nunca trabajé allí.'],'Distinguish the changed journey from the continuing job and occasional car use.'),
scene('Un barrio distinto','Ana volvió a la calle donde vivía antes. Recordaba una tienda pequeña y una plaza casi vacía. Ahora hay una librería con mesas fuera y muchas familias pasan allí la tarde. Diego vive en el barrio desde 2020 y explicó que la plaza cambió poco a poco. Ya no entran coches durante el fin de semana. Sin embargo, algunos vecinos todavía echan de menos la antigua tienda porque vendía productos baratos. Ana compró un libro, pero no dijo que todo era mejor. Le gustó tener un lugar para sentarse y hablar; también entendió la preocupación por los precios. Comparar el barrio le ayudó a recordar que un cambio puede traer ventajas y dificultades a la vez.',[['echan de menos','miss'],['poco a poco','gradually']],['¿Qué cambio aparece?','La plaza tiene más vida sin coches los fines de semana.','No queda ninguna tienda.','Nadie vive allí.'],['¿Por qué algunos extrañan la tienda?','Vendía productos baratos.','It sold affordable products.'],['¿Qué conclusión apoya el texto?','El cambio tiene ventajas y dificultades.','Todo es peor.','Ana rechaza la librería.'],['¿Cómo valora Ana el barrio?','Ve aspectos positivos y preocupaciones.','She sees benefits and concerns.'],['¿Qué frase compara antes y ahora?','Antes había una tienda; ahora hay una librería.','Ahora nunca hay libros.','Desde hace 2020 vivía mañana.'],'The passage gives two viewpoints; a balanced comparison respects both.'),
scene('Una amistad que continúa','Elena y Marta se conocieron en un curso de cocina. Hace cuatro años que son amigas. Antes se veían todas las semanas porque estudiaban en el mismo centro. Ahora Elena trabaja por las tardes y Marta tiene otro horario. Ya no pueden cocinar juntas cada viernes, pero todavía hablan por teléfono. Este mes han preparado una cena en casa de Elena. Marta llevó la receta que usaban en clase y Elena cambió algunos ingredientes. Mientras cocinaban, hablaron de sus nuevas rutinas. No querían recuperar exactamente el pasado: buscaban una forma de seguir viéndose. Al final decidieron quedar una vez al mes. La frecuencia cambió, pero las dos seguían interesadas en cuidar la amistad.',[['la frecuencia','frequency'],['cuidar la amistad','maintain the friendship']],['¿Qué cambió en la amistad?','Se ven con menos frecuencia.','Ya no hablan.','Nunca cocinaron juntas.'],['¿Por qué no quedan cada viernes?','Sus horarios cambiaron.','Their schedules changed.'],['¿Qué indica el nuevo acuerdo?','Quieren mantener el contacto.','Quieren terminar la amistad.','Tienen el mismo horario.'],['¿Qué quieren conservar?','La amistad, no la rutina exacta.','The friendship, not the exact old routine.'],['¿Qué propuesta encaja?','Podemos quedar una vez al mes.','No quiero hablar contigo nunca.','Solo nos veremos ayer.'],'Continuity concerns the relationship; frequency is the part that changes.'),
scene('El nuevo horario de Diego','Diego estudia por las mañanas desde hace seis meses. Antes abría el café temprano y terminaba por la tarde. Ahora una compañera abre y él llega después de clase. Al principio se sentía cansado porque intentaba estudiar por la noche también. Ya no lo hace: prepara las tareas antes de cenar y descansa después. Todavía trabaja los sábados, así que no tiene todos los fines de semana libres. Luis le preguntó si estudiar era demasiado difícil. Diego contestó que organizar el tiempo era la parte complicada. Esta semana ha entregado su primer proyecto. Está contento, pero no presenta su nueva rutina como una solución perfecta. Sigue ajustándola cuando cambian los turnos del café.',[['los turnos','work shifts'],['ajustándola','adjusting it']],['¿Qué mantiene Diego?','El trabajo de los sábados.','El estudio nocturno diario.','La apertura temprana.'],['¿Por qué dejó de estudiar de noche?','Estaba cansado.','He was tired.'],['¿Qué significa desde hace seis meses?','Empezó hace seis meses y continúa.','Terminó hace seis meses.','Empezará en seis meses.'],['¿Qué le resulta complicado?','Organizar el tiempo.','Organising his time.'],['¿Qué frase resume el proceso?','He cambiado la rutina y todavía la estoy ajustando.','Todo está resuelto para siempre.','Ya no estudio nunca.'],'Duration extending to now differs from a completed period.')],[audio('Antes Marta estudiaba por la tarde. Ahora trabaja en ese horario. Ya no va al curso del viernes, pero todavía practica en casa.','¿Qué sigue haciendo?','Practica en casa.',['Va al curso del viernes.','Estudia por la tarde.'],'Todavía marks the continuing activity.'),audio_text('Vivo en Toledo desde hace tres años. Antes vivía en Madrid. Todavía trabajo allí dos días por semana.','¿Cuánto tiempo lleva viviendo en Toledo?','Tres años.',['Three years.','3 años'],'Desde hace + duration extends to the present.')],prod('change',['Escribe «I no longer work there».','Translate the given meaning.','Ya no trabajo allí.','Usa desde hace: estudio español; dos años.','State an ongoing two-year duration.','Estudio español desde hace dos años.'],[('Compara dos rutinas de antes y ahora. Incluye algo que continúa.','Compare routines and one continuing habit.','Antes iba en coche, pero ahora voy en bicicleta. Todavía trabajo en el mismo lugar.'),('Describe un cambio de tu barrio y dos opiniones sobre él.','Describe a neighbourhood change and two views.','Antes había una tienda pequeña. Ahora hay una librería. Me gusta, pero algunos vecinos echan de menos los precios de antes.'),('Escribe a una amiga explicando un cambio de horario y cómo mantener el contacto.','Explain a schedule change and suggest staying in touch.','Ahora trabajo por las tardes y ya no puedo quedar los viernes. Todavía quiero verte. ¿Podemos quedar un sábado al mes?')],[('Compara antes y ahora',['antes','ahora']),('Marca continuidad o cambio',['todavía','ya no'])])))
b11.append(unit('Plans and intentions','Explain plans, arrangements and future commitments','Simple future iré, tendré, haré, podré; ir a; present arrangements',[
core('Mañana iré a la oficina y hablaré con Elena.','Tomorrow I will go to the office and speak with Elena.','iré',['iba','fui'],'Ir uses the future stem ir- plus é. A future commitment differs from a past event.','Elena: «¿Vendrás a la reunión?»','Sí, iré mañana.',['Sí, fui mañana.','Estoy ayer allí.'],'Mañana trabajarás en casa y llamarás a Luis. Confirma el compromiso.','Mañana trabajaré en casa y llamaré a Luis.'),
core('Voy a preparar la cena; quedamos a las ocho.','I am going to prepare dinner; we are meeting at eight.','Voy a',['Fui a','Iba a'],'Voy a + infinitive presents an intention; quedamos can express an agreed arrangement.','Ana: «¿Ya tenemos hora para cenar?»','Sí, quedamos a las ocho.',['Nunca hay una hora.','Ayer quedaremos.'],'Vas a comprar las entradas. La reunión acordada es a las seis.','Voy a comprar las entradas; quedamos a las seis.'),
core('Tendré tiempo el sábado, pero no podré ir el viernes.','I will have time on Saturday, but I will not be able to go on Friday.','Tendré',['Tenía','Tuve'],'Tener uses tendr-; poder uses podr-. The contrast makes availability precise.','Marta: «¿Puedes ayudarme el sábado?»','Sí, tendré tiempo.',['No pude mañana.','Siempre tuvimos mañana.'],'Harás la reserva el lunes, pero no podrás llamar hoy.','Haré la reserva el lunes, pero no podré llamar hoy.')],[
scene('Una fecha confirmada','Elena organiza una reunión para preparar una exposición. En el grupo alguien escribió que sería el viernes, pero todavía no era una fecha confirmada. Luis pensó que podía comprar los billetes del tren. Elena le llamó antes de la compra: «No los compres aún; mañana hablaré con el museo». Después envió un mensaje más claro. Van a reunirse el sábado a las diez, y la sala ya está reservada. Luis respondió que llegará a las nueve y media. Ana va a preparar una lista de preguntas. No necesitan terminar todo ese día; quieren repartir las tareas. La nueva comunicación distingue una idea inicial, una decisión pendiente y un horario que todos han aceptado.',[['confirmada','confirmed'],['repartir','share out']],['¿Qué está confirmado al final?','La reunión del sábado a las diez.','La fecha inicial del viernes.','La exposición completa.'],['¿Por qué Elena llama a Luis?','Para evitar una compra demasiado pronto.','To prevent buying tickets too early.'],['¿Qué muestra la reserva de la sala?','El plan dejó de ser solo una propuesta.','La exposición terminó.','Luis no puede viajar.'],['¿Qué espera Ana preparar?','Una lista de preguntas.','A list of questions.'],['¿Qué respuesta confirma un compromiso?','Llegaré a las nueve y media.','Quizá fue ayer mañana.','No hay ninguna reunión.'],'The story contrasts tentative intentions with agreed arrangements.'),
scene('El sábado de Marta','Marta tiene tres invitaciones para el sábado y no quiere aceptar todas. Por la mañana ayudará a su padre con una compra. Después va a comer con Ana, como acordaron la semana pasada. Diego propone una excursión que ocupa todo el día. Marta le dice que no podrá ir, aunque le apetece. No inventa una excusa: explica los compromisos que ya tiene. Diego propone otra salida el domingo, pero Marta no confirma inmediatamente. Tendrá que mirar el horario del autobús primero. Ana agradece que Marta mantenga la comida. Las dos saben que cambiar un plan puede ser necesario, pero avisar con tiempo evita que otra persona espere sin saber qué pasa.',[['le apetece','she feels like it'],['una excusa','an excuse']],['¿Qué invitación rechaza Marta?','La excursión del sábado.','La comida con Ana.','La ayuda a su padre.'],['¿Por qué no puede ir?','Tiene compromisos previos.','She has prior commitments.'],['¿Está confirmada la salida del domingo?','No; debe mirar el horario.','Sí; todo está comprado.','No; Diego nunca la propone.'],['¿Qué valora Ana?','Que Marta mantenga el acuerdo.','That Marta keeps their arrangement.'],['¿Qué respuesta explica un límite?','No podré ir el sábado; ya tengo otros planes.','Sí a todo, aunque no iré.','Fui el próximo sábado.'],'Availability, preference and confirmation are not the same thing.'),
scene('Una promesa pequeña','Diego prometió enviar a Luis una receta, pero olvidó hacerlo. Cuando Luis preguntó de nuevo, Diego no respondió con una promesa enorme. Dijo: «La buscaré esta tarde y te la enviaré antes de las seis». Tenía el cuaderno en casa y sabía que podría consultarlo después del trabajo. Luis iba a cocinar al día siguiente, así que ese plazo era suficiente. Ana sugirió hacer una foto para no copiar toda la receta. Diego lo hizo y añadió una nota sobre una cantidad que podía confundir. Al final Luis recibió la información a tiempo. La promesa fue útil porque incluía una acción concreta y un límite realista, no solo una buena intención.',[['el plazo','deadline'],['el cuaderno','notebook']],['¿Qué hace precisa la promesa?','Una acción y una hora límite.','Una receta sin cantidades.','Una intención sin fecha.'],['¿Por qué podía cumplirla?','Tenía tiempo después del trabajo.','He had time after work.'],['¿Por qué la foto ayudó?','Evitó copiar toda la receta.','Cambió el día de la comida.','Eliminó los ingredientes.'],['¿Qué necesitaba Luis?','La receta antes de cocinar.','The recipe before cooking.'],['¿Qué compromiso encaja?','Te la enviaré antes de las seis.','Quizá nunca la busqué mañana.','No importa cuándo cocines.'],'A future commitment is credible when its action and timing are clear.'),
scene('Un viaje sin demasiados planes','Ana quiere pasar el domingo en Toledo con Clara. Va a comprar el billete de ida, pero prefiere decidir la vuelta más tarde. Clara teme perder el último tren. Las dos miran los horarios y acuerdan un límite: volverán antes de las ocho. Todavía no han elegido restaurante. Clara hará una lista corta de lugares y Ana buscará una exposición. No van a llenar cada minuto. Luis pregunta dónde estarán a las tres y Ana reconoce que aún no lo sabe. En lugar de presentar una idea como una reserva, explica qué está decidido y qué sigue abierto. Así pueden organizar lo necesario sin convertir una salida tranquila en un horario imposible.',[['sigue abierto','remains undecided'],['un límite','a limit']],['¿Qué está decidido?','Volver antes de las ocho.','El restaurante.','El lugar exacto a las tres.'],['¿Por qué miran los horarios?','Para no perder el último tren.','To avoid missing the last train.'],['¿Qué actitud muestra Ana?','Distingue decisiones de opciones abiertas.','Finge que todo está reservado.','No quiere viajar.'],['¿Qué quieren evitar?','Un horario demasiado lleno.','An overloaded schedule.'],['¿Cómo explicar la vuelta?','Volveremos antes de las ocho; el resto sigue abierto.','Ya comimos mañana a las tres.','No existe un último tren.'],'Future plans can include firm limits and flexible choices.')],[audio('Voy a comprar las entradas esta tarde. El concierto es el sábado; quedamos a las siete delante del teatro. Si hay algún cambio, os llamaré.','¿Qué es un acuerdo concreto?','Quedar el sábado a las siete.',['Comprar ayer.','Llamar siempre a las siete.'],'Present quedamos communicates the arrangement.'),audio_text('No podré ir el viernes porque trabajo. Tendré tiempo el sábado y haré la reserva por la mañana.','¿Cuándo hará la reserva?','El sábado por la mañana.',['On Saturday morning.','Sábado por la mañana'],'The planned action is tied to Saturday morning.')],prod('plans',['Escribe «Tomorrow I will make the reservation».','Translate the commitment.','Mañana haré la reserva.','Cambia al futuro: tengo tiempo el sábado.','Use simple future for Saturday availability.','Tendré tiempo el sábado.'],[('Confirma una reunión y explica qué vas a preparar.','Confirm an arrangement and preparation.','Quedamos a las seis. Voy a preparar una lista y la enviaré esta tarde.'),('Organiza una salida con decisiones firmes y opciones abiertas.','Plan an outing without pretending every detail is decided.','Iremos a Toledo el domingo y volveremos antes de las ocho. Todavía no hemos elegido restaurante. Voy a mirar dos opciones.'),('Explica a Luis por qué no puedes ir el viernes y propón una alternativa.','Decline Friday and propose an alternative.','No podré ir el viernes porque trabajo. Tendré tiempo el sábado. ¿Quedamos por la mañana?')],[('Expresa un plan',['voy a','iremos','haré']),('Da un horario o motivo',['sábado','porque','seis'])])))
b11.append(unit('Advice and solutions','Offer practical advice while respecting the other person’s choice','Conditional advice deberías/podrías; yo que tú; no hace falta; obligation',[
core('Deberías llamar antes de salir.','You should call before leaving.','Deberías',['Debiste','Deberás'],'Deberías softens advice; it is not a command or a completed action.','Ana: «No sé si la tienda está abierta».','Podrías llamar primero.',['Ya llamaste mañana.','Nunca preguntes nada.'],'Luis no sabe el horario. Recomienda mirarlo antes de viajar.','Deberías mirar el horario antes de viajar.'),
core('Yo que tú, pediría una copia del recibo.','If I were you, I would ask for a copy of the receipt.','pediría',['pedí','pediré'],'Yo que tú frames a suggestion from your perspective; conditional keeps it hypothetical.','Marta: «He perdido el recibo».','Yo que tú, pediría una copia.',['No tienes ninguna opción nunca.','Lo compraste mañana.'],'Ana no entiende un mensaje. Sugiere pedir una aclaración.','Yo que tú, pediría una aclaración.'),
core('No hace falta comprar otro billete; puedes cambiar este.','You do not need to buy another ticket; you can change this one.','No hace falta',['No hice falta','Hace no falta'],'No hace falta + infinitive removes an obligation and offers a practical alternative.','Luis: «¿Tengo que comprar otro?»','No hace falta; puedes cambiarlo.',['Debes comprar todos.','Nunca hay cambios.'],'No es necesario imprimir la reserva; se puede mostrar en el móvil.','No hace falta imprimir la reserva; puedes mostrarla en el móvil.')],[
scene('El ordenador lento','Luis se queja de que su ordenador funciona despacio. Quiere comprar uno nuevo esa misma tarde porque tiene una entrega al día siguiente. Clara le pregunta primero qué ocurre. El problema empezó después de instalar un programa y no afecta a todos los documentos. Clara no promete arreglarlo. Sugiere guardar una copia del trabajo y consultar al servicio técnico antes de gastar dinero. «Podrías usar el ordenador de la biblioteca para terminar», añade. Luis acepta esa solución temporal. Después descubre que una actualización resuelve el problema. Agradece que Clara no le dijera simplemente qué debía comprar. El consejo le dio opciones y protegió su trabajo sin presentar una opinión como un diagnóstico seguro.',[['la entrega','submission deadline'],['una actualización','an update']],['¿Qué propone Clara primero?','Proteger el trabajo y pedir ayuda técnica.','Comprar inmediatamente.','Borrar todos los documentos.'],['¿Por qué Luis tiene prisa?','Debe entregar un trabajo mañana.','He has a deadline tomorrow.'],['¿Qué función tiene la biblioteca?','Una solución temporal.','Un diagnóstico técnico.','Una tienda de ordenadores.'],['¿Qué valora Luis del consejo?','Le dio opciones sin prometer un diagnóstico.','It offered options without claiming a diagnosis.'],['¿Qué consejo encaja?','Podrías guardar una copia antes de cambiar nada.','Debes borrar todo sin mirar.','No necesitas entregar el trabajo.'],'Useful advice separates a temporary solution from certainty about the cause.'),
scene('La reserva equivocada','Ana reservó una habitación para dos noches, pero la confirmación muestra una sola. Está nerviosa y quiere cancelar sin llamar. Marta le dice que debería hablar primero con el hotel y tener a mano el correo. No hace falta empezar con una acusación: puede explicar la diferencia y preguntar por las opciones. Ana llama y la recepcionista revisa la reserva. Hay sitio para la segunda noche, aunque el precio es algo mayor. Ana pide la nueva confirmación por escrito antes de aceptar. Marta no decide por ella. Le ayuda a comparar el coste con cambiar de hotel. Al final Ana mantiene la reserva porque la ubicación le conviene y conoce el precio total.',[['tener a mano','have ready'],['por escrito','in writing']],['¿Qué recomienda Marta antes de cancelar?','Hablar con el hotel.','Reservar tres hoteles.','Acusar sin comprobar.'],['¿Por qué pide confirmación escrita?','Para tener claros los detalles.','To have clear details.'],['¿Qué hace Marta con la decisión?','Ayuda a comparar, pero no decide por Ana.','Elige sin preguntar.','Se niega a escuchar.'],['¿Por qué Ana mantiene la reserva?','Le convienen ubicación y coste conocido.','The location suits her and the total cost is clear.'],['¿Qué petición encaja?','¿Podría enviarme la confirmación por escrito?','No quiero conocer el precio.','La reserva es ayer mañana.'],'Advice prepares a calm exchange and leaves the choice with the learner.'),
scene('Una tarea demasiado grande','Diego tiene que preparar una presentación y no sabe por dónde empezar. Ha escrito muchas notas, pero no ha elegido las ideas principales. Elena le sugiere dividir el trabajo en tres partes. Primero podría explicar el problema; después mostrar un ejemplo; al final proponer una solución. No hace falta contar todos los detalles que conoce. Diego teme olvidar algo importante. Elena le recomienda ensayar con un compañero y pedir preguntas al final. Él prepara una versión más corta y descubre que puede explicarla sin leer cada palabra. No ha aprendido menos: ha organizado mejor lo que sabe. El consejo trata de claridad, no de hablar más rápido para incluirlo todo.',[['ensayar','rehearse'],['las ideas principales','main ideas']],['¿Cuál es el problema de Diego?','Tiene notas sin una estructura clara.','No sabe ningún detalle.','No tiene presentación.'],['¿Por qué conviene una versión más corta?','Ayuda a explicar las ideas principales.','It helps explain the main ideas.'],['¿Qué cambia al organizar el trabajo?','Puede explicarlo sin leer todo.','Tiene que hablar más rápido.','Olvida el tema completo.'],['¿Qué aconseja Elena?','Claridad antes que cantidad.','Clarity rather than quantity.'],['¿Qué consejo encaja?','Podrías elegir tres ideas y ensayar.','Incluye todo y habla sin parar.','No hace falta entender el problema.'],'Removing less relevant detail can improve communication, not reduce understanding.'),
scene('Consejos que no son órdenes','Marta escucha a dos amigos hablar de un viaje. Uno dice que todos deberían visitar cinco ciudades en una semana. El otro prefiere conocer una sola con calma. Marta no quiere elegir por ellos. Pregunta cuánto tiempo tienen y qué les interesa. Sugiere comparar los trayectos antes de reservar. También recuerda que no hace falta seguir su propio itinerario: a ella le gusta caminar, pero su amiga necesita descansar más. Los amigos deciden pasar tres días en una ciudad y dejar libre el último día. Agradecen una propuesta que tiene en cuenta sus preferencias. Marta entiende que un consejo puede ser razonable para una persona y poco útil para otra.',[['el itinerario','itinerary'],['tiene en cuenta','takes into account']],['¿Qué pregunta Marta antes de aconsejar?','Por el tiempo y los intereses.','Por todos los hoteles del país.','Por una decisión ya impuesta.'],['¿Por qué no propone copiar su ruta?','Sus preferencias son diferentes.','Their preferences differ.'],['¿Qué muestra el plan final?','Adapta el consejo a las personas.','Obedece una orden única.','Incluye cinco ciudades.'],['¿Cómo entiende Marta un buen consejo?','Depende de la situación de cada persona.','It depends on each person’s situation.'],['¿Qué formulación deja elección?','Podríais comparar los trayectos antes de decidir.','Tenéis que hacer exactamente mi viaje.','No hay ninguna alternativa.'],'Conditional advice can guide a decision without turning preference into obligation.')],[audio('Yo que tú, llamaría al hotel antes de cancelar. No hace falta comprar otra reserva todavía. Primero pide que comprueben las fechas.','¿Cuál es el consejo principal?','Comprobar la reserva antes de cancelarla.',['Cancelar sin hablar.','Comprar dos habitaciones.'],'The suggested order is check, then decide.'),audio_text('Podrías dividir la presentación en tres partes. No hace falta leer todas las notas; deberías elegir las ideas principales.','¿Qué debería elegir?','Las ideas principales.',['The main ideas.'],'The advice prioritises selection and structure.')],prod('advice',['Escribe «You should call first».','Translate softened advice.','Deberías llamar primero.','Expresa que no es necesario imprimir el billete.','Say printing is unnecessary.','No hace falta imprimir el billete.'],[('Ofrece dos opciones a alguien que ha perdido una reserva.','Offer two practical options.','Podrías llamar al hotel o buscar el correo. Yo que tú, comprobaría las fechas antes de reservar otra vez.'),('Escribe consejos para organizar una tarea. Explica por qué ayudan.','Advise on organising a task and explain why.','Deberías elegir las ideas principales porque tienes poco tiempo. Podrías ensayar con una amiga. No hace falta leer todas las notas.'),('Una amiga quiere cancelar un viaje por un cambio de horario. Aconséjala sin decidir por ella.','Give advice without deciding for your friend.','Yo que tú, miraría si puedes cambiar el billete. Podrías llamar a la empresa. No hace falta cancelar antes de conocer las opciones.')],[('Ofrece una opción',['podrías','deberías','yo que tú']),('Explica una razón',['porque','antes de'])])))
b11.append(unit('Experiences and reactions','Describe an experience and explain a personal reaction','Me sorprendió/preocupó/encantó; me pareció; lo pasé; tenía ganas de',[
core('Me sorprendió la tranquilidad del barrio.','The quietness of the neighbourhood surprised me.','sorprendió',['sorprendí','sorprendieron'],'The thing causing the reaction controls the verb: la tranquilidad is singular.','Ana: «¿Qué te llamó la atención?»','Me sorprendió la tranquilidad.',['Yo sorprendió el barrio.','Me sorprendieron la tranquilidad.'],'Dos detalles te sorprendieron: el precio y la atención.','Me sorprendieron el precio y la atención.'),
core('Tenía ganas de conocer el museo y lo pasé muy bien.','I wanted to visit the museum and had a very good time.','Tenía',['Tuve mañana','Tengo ayer'],'Tenía ganas de gives the prior wish; lo pasé bien describes the completed experience.','Luis: «¿Disfrutaste de la visita?»','Sí, lo pasé muy bien.',['Sí, lo fui muy bien.','No tengo mañana ayer.'],'Querías ver la exposición. Cuenta que disfrutaste de la visita.','Tenía ganas de ver la exposición y lo pasé muy bien.'),
core('Me pareció interesante, aunque algunas partes fueron difíciles.','I found it interesting, although some parts were difficult.','pareció',['parecí','parecieron'],'Me pareció introduces your evaluation, not an objective fact everyone must share.','Marta: «¿Te gustó la charla?»','Me pareció interesante, aunque fue larga.',['Fue interesante para todo el mundo sin excepción.','Yo pareció interesante.'],'La película te gustó, pero el final fue confuso. Expresa tu valoración.','Me gustó la película, pero el final me pareció confuso.')],[
scene('Una exposición inesperada','Ana tenía ganas de visitar una exposición de fotografías. Esperaba ver edificios conocidos, pero encontró retratos de personas del barrio. Cada fotografía incluía una frase sobre su vida. Le sorprendió reconocer a la señora que veía siempre en la parada del autobús. Nunca habló con ella y ahora sabía que trabajó muchos años en un teatro. Luis prefirió las imágenes de calles antiguas. No discutieron sobre cuál era la mejor parte; compartieron lo que les llamó la atención. Al salir, Ana dijo que lo pasó muy bien porque la visita cambió su manera de mirar un lugar familiar. No necesitó viajar lejos para descubrir una historia nueva.',[['retratos','portraits'],['llamó la atención','caught the attention']],['¿Qué esperaba Ana?','Fotografías de edificios conocidos.','Un concierto.','Una película.'],['¿Por qué disfrutó especialmente?','Descubrió historias de gente del barrio.','She discovered neighbours’ stories.'],['¿Qué cambió la visita?','Su mirada sobre un lugar familiar.','Su dirección de casa.','El trabajo de Luis.'],['¿Qué prefirió Luis?','Las calles antiguas.',['Old street scenes.'][0]],['¿Cómo expresar la reacción de Ana?','Me sorprendió reconocer a una vecina.','Yo sorprendió una vecina.','No había fotografías.'],'Different personal reactions can coexist without a single correct preference.'),
scene('La primera presentación','Diego dio su primera presentación delante de compañeros de clase. Antes de empezar estaba preocupado porque pensaba olvidar las palabras. Elena le ayudó a ensayar, pero no escribió el texto por él. Al principio Diego habló muy deprisa. Después hizo una pausa y miró sus tres ideas principales. Un compañero preguntó por un ejemplo y Diego pudo explicarlo sin leer. Lo que más le sorprendió fue que las preguntas le ayudaron en lugar de interrumpirlo. Al final recibió comentarios sobre la claridad y sobre una parte demasiado larga. Lo pasó mejor de lo esperado. No presentó la actividad como perfecta: entendió qué funcionó y qué puede mejorar para la próxima vez.',[['ensayar','rehearse'],['interrumpirlo','interrupt him']],['¿Qué le preocupaba antes?','Olvidar las palabras.','No tener compañeros.','Llegar al teatro.'],['¿Por qué fueron útiles las preguntas?','Le ayudaron a explicar un ejemplo.','They helped him explain an example.'],['¿Qué valoración es equilibrada?','Hubo aciertos y algo que mejorar.','Todo fue perfecto.','Nada funcionó.'],['¿Qué le sorprendió?','Que las preguntas le ayudaran.','That the questions helped him.'],['¿Qué reflexión encaja?','Me fue mejor de lo esperado; debo acortar una parte.','Nunca prepararé otra presentación.','No recibí comentarios.'],'An encouraging result need not erase useful critical feedback.'),
scene('Una cena con opiniones distintas','Clara invitó a sus amigos a un restaurante nuevo. A Marta le encantó la sopa, pero a Luis le pareció demasiado salada. Ana valoró que el camarero explicara los ingredientes con paciencia. Diego estaba preocupado por el precio, aunque al final la cuenta fue menor de lo esperado. Al comentar la cena, separaron comida, atención y coste. Clara no se sintió atacada porque alguien no disfrutó de un plato. Explicó que quería conocer el lugar y no garantizar una experiencia perfecta. Todos lo pasaron bien conversando. Decidieron que podían repetir otra vez y elegir platos diferentes. La conversación mostró que una experiencia compartida puede producir reacciones distintas sin estropear la relación.',[['la atención','service'],['estropear','spoil']],['¿Sobre qué no estuvieron todos de acuerdo?','La sopa.','La existencia del restaurante.','La fecha de la cena.'],['¿Por qué Diego estaba preocupado?','Por el precio.','Because of the price.'],['¿Qué separaron al valorar la cena?','Comida, atención y coste.','La cena y la conversación como una sola nota.','Solo el nombre del local.'],['¿Cómo recibió Clara la crítica?','No la tomó como un ataque personal.','She did not take it personally.'],['¿Qué comentario permite discrepar con respeto?','Lo pasé bien, aunque la sopa me pareció salada.','Si no te gusta, eres mal amigo.','Todos tienen que pensar igual.'],'A reaction is personal; explain it without turning disagreement into conflict.'),
scene('Volver al sendero','Luis volvió con su padre a un camino que recorrían cuando era pequeño. Tenía ganas de enseñárselo a Ana, pero estaba preocupado por una cuesta difícil. Su padre propuso una ruta más corta y varias paradas. Durante la caminata contaron recuerdos y compararon el paisaje de antes con el de ahora. A Ana le sorprendió ver cuánto conocía Luis cada curva. Luis descubrió que disfrutaba más caminando despacio que intentando terminar rápido. Al final lo pasaron bien, aunque no llegaron al punto más alto. Su padre dijo que el objetivo era compartir la mañana, no demostrar fuerza. Luis aceptó esa valoración y empezó a pensar en otra salida tranquila.',[['el camino','path'],['la cuesta','slope']],['¿Qué cambió el padre?','Propuso una ruta más corta.','Canceló la salida.','Quitó todas las paradas.'],['¿Por qué Luis estaba preocupado?','Por una cuesta difícil.','Because of a difficult slope.'],['¿Qué demuestra el final?','Disfrutar no dependía de llegar arriba.','La salida fracasó por completo.','Nadie compartió recuerdos.'],['¿Qué valoró el padre?','Compartir la mañana.','Spending the morning together.'],['¿Qué valoración encaja?','Lo pasamos bien, aunque no llegamos arriba.','No caminamos nada.','Solo importa terminar primero.'],'The final interpretation changes the criterion for a successful experience.')],[audio('Tenía ganas de ver la exposición. Me sorprendieron las fotos del barrio y me encantó escuchar las historias. Algunas explicaciones fueron largas, pero lo pasé bien.','¿Cuál es la valoración general?','Positiva, con una pequeña crítica.',['Totalmente negativa.','No llegó a verla.'],'Pero preserves a positive overall reaction despite a limitation.'),audio_text('Me preocupó el precio al principio. Después vimos la cuenta y fue menos de lo esperado. Me pareció un lugar agradable.','¿Qué le preocupó primero?','El precio.',['The price.'],'The price is the initial concern.')],prod('reactions',['Escribe «I had a very good time».','Translate the reaction.','Lo pasé muy bien.','Dos detalles te sorprendieron. Completa: me ___ los precios y el horario.','Use plural agreement.','Me sorprendieron los precios y el horario.'],[('Valora una visita con una reacción positiva y una dificultad.','Evaluate a visit with a positive reaction and a difficulty.','Me encantó la exposición, aunque algunas explicaciones fueron largas. Lo pasé bien y aprendí algo nuevo.'),('Cuenta una experiencia que fue diferente de lo esperado.','Describe an experience that differed from expectations.','Tenía ganas de ver la obra, pero estaba preocupado por no entenderla. Me sorprendió la claridad de los actores. Al final lo pasé muy bien.'),('Escribe a una amiga sobre una actividad. Explica qué te sorprendió y qué mejorarías.','Report an activity, surprise and possible improvement.','Lo pasé bien en la excursión. Me sorprendió el paisaje, aunque el camino fue largo. La próxima vez haría más paradas.')],[('Expresa una reacción',['me sorprendió','me encantó','me pareció']),('Añade una valoración con motivo',['porque','aunque'])])))
b11.append(unit('Explaining your view','Express a view, support it and acknowledge a different advantage','Creo/pienso/me parece que; por una parte; sin embargo; por eso; por/para',[
core('Creo que el tren es mejor porque permite descansar.','I think the train is better because it allows us to rest.','Creo',['Creí ayer mañana','Creer'],'Positive creo que normally takes indicative; porque supplies support, not certainty for everyone.','Luis: «¿Por qué prefieres el tren?»','Porque puedo descansar durante el viaje.',['Porque sí, no hay ninguna razón.','Para ayer llegamos.'],'Prefieres caminar porque conoces mejor el barrio. Explica tu opinión.','Creo que caminar es mejor porque conozco mejor el barrio.'),
core('Por una parte es barato; por otra parte tarda más.','On one hand it is cheap; on the other hand it takes longer.','Por una parte',['Después de parte','Para una parte'],'The paired phrases organise two relevant aspects of the same option.','Ana: «¿El autobús tiene alguna desventaja?»','Sí, tarda más; sin embargo, cuesta menos.',['No existe ninguna diferencia.','Es ayer más mañana.'],'Compara una casa pequeña y barata con una grande y cara.','Por una parte la casa pequeña es barata; por otra parte tiene menos espacio.'),
core('Estudio español para hablar con mis vecinos.','I study Spanish in order to speak with my neighbours.','para',['por','desde'],'Para + infinitive expresses a purpose; porque introduces a reason clause. Por has other reason/route meanings, not this purpose pattern.','Marta: «¿Para qué estudias español?»','Para hablar con mis vecinos.',['Por hablaré mañana.','Desde hablar con vecinos.'],'Aprendes a cocinar para preparar cenas en casa. Explica el propósito.','Aprendo a cocinar para preparar cenas en casa.')],[
scene('Una reunión en línea','Elena propone hacer una reunión en línea porque algunos compañeros viven lejos. Luis prefiere reunirse en persona: cree que así es más fácil conversar sin interrupciones. En lugar de repetir sus preferencias, comparan las necesidades del grupo. Dos personas no pueden viajar y otra tiene una conexión inestable. Por una parte, la reunión en línea evita trayectos; por otra parte, puede dificultar escuchar a todos. Ana propone una sesión corta en línea para repartir tareas y un encuentro presencial después. No resuelve cada problema, pero permite empezar. Elena acepta porque su objetivo es organizar el trabajo, no defender una herramienta por sí misma. Luis reconoce que su opción favorita no sirve igual para todos.',[['en línea','online'],['inestable','unstable']],['¿Qué busca Elena principalmente?','Organizar el trabajo del grupo.','Defender una herramienta a cualquier precio.','Evitar todo contacto.'],['¿Por qué propone reunirse en línea?','Algunos viven lejos.','Some live far away.'],['¿Qué aporta la propuesta de Ana?','Combina ventajas de dos formatos.','Niega todas las dificultades.','Obliga a viajar a todos.'],['¿Qué reconoce Luis?','Su preferencia no sirve igual para todos.','His preference does not suit everyone equally.'],['¿Qué argumento es razonado?','Podemos empezar en línea para incluir a quienes viven lejos.','Mi opción es la única posible porque me gusta.','No hay problemas de conexión.'],'Compare reasons and needs rather than confuse a preference with a universal answer.'),
scene('El banco de la plaza','El ayuntamiento quiere quitar un banco para ampliar el paso de una plaza. Clara piensa que hace falta espacio para circular. Marta explica que muchas personas mayores descansan en ese banco cuando vuelven del mercado. Las dos escuchan experiencias concretas antes de opinar. Un vecino propone mover el banco unos metros en lugar de quitarlo. La propuesta mantiene un lugar para descansar y deja libre la zona más estrecha. Clara dice que le parece una solución mejor porque responde a dos necesidades. Marta no afirma que todos los bancos deban estar en el mismo lugar. Su argumento se apoya en el uso de este banco. El grupo prepara un mensaje breve con motivos claros para enviar la propuesta.',[['el ayuntamiento','town council'],['estrecha','narrow']],['¿Qué propone el vecino?','Mover el banco, no quitarlo.','Cerrar el mercado.','Quitar todos los bancos.'],['¿Por qué Marta quiere conservarlo?','Sirve para descansar.','People use it to rest.'],['¿Por qué convence la alternativa?','Atiende dos necesidades.','No cambia nada.','Ignora a las personas mayores.'],['¿En qué apoya Marta su argumento?','En el uso concreto del banco.','In how this bench is used.'],['¿Qué mensaje encaja?','Proponemos mover el banco para dejar paso y conservar un lugar de descanso.','Todo debe quedarse siempre igual.','Nadie usa la plaza.'],'A concrete example supports an argument without proving every wider claim.'),
scene('Comprar menos, elegir mejor','Diego quiere cambiar todos los vasos del café porque algunos no son iguales. Ana le pregunta si están rotos o si solo cambió la moda. Los vasos todavía funcionan. Por una parte, un conjunto nuevo daría una imagen uniforme; por otra parte, costaría dinero y produciría residuos. Diego escucha a sus clientes y descubre que valoran más la limpieza que el diseño. Decide sustituir únicamente los vasos dañados. No presenta su decisión como una regla para todos los negocios. Explica que, en su café, tiene más sentido gastar en arreglar la puerta. Ana está de acuerdo porque la puerta causa un problema real cada mañana. La conversación transforma una impresión inicial en una decisión con prioridades.',[['residuos','waste'],['dañados','damaged']],['¿Qué decide Diego?','Cambiar solo los vasos dañados.','Cambiar todos por moda.','No limpiar los vasos.'],['¿Por qué prioriza la puerta?','Causa un problema real.','It causes a real problem.'],['¿Qué cambia durante la conversación?','Evalúa necesidades en lugar de apariencia solamente.','Deja de escuchar a clientes.','Afirma que todos los cafés son iguales.'],['¿Qué valoran los clientes?','La limpieza más que el diseño.','Cleanliness more than design.'],['¿Qué explicación respeta el contexto?','En nuestro café, arreglar la puerta es más urgente.','Ningún negocio debe comprar vasos nunca.','La moda prueba que están rotos.'],'Good reasons identify priorities and avoid unsupported universal claims.'),
scene('Dos formas de aprender','Luis disfruta aprendiendo palabras con tarjetas. Elena prefiere leer historias y encontrar las palabras en contexto. Al principio cada uno recomienda su método como si fuera el único. Después comparan qué les cuesta. Luis recuerda formas cortas, pero a veces no sabe usarlas en una conversación. Elena entiende historias, aunque olvida algunas palabras al hablar. Deciden probar una combinación: elegirán frases de una historia para repasarlas después. Luis reconoce que una tarjeta puede tener contexto; Elena admite que el recuerdo activo también ayuda. No necesitan abandonar lo que les funciona. Buscan una solución para sus dificultades concretas. Al final describen su acuerdo con una razón: quieren recordar palabras para usarlas, no solo reconocerlas.',[['tarjetas','flashcards'],['recuerdo activo','active recall']],['¿Qué acuerdo alcanzan?','Combinar historias y repaso de frases.','Abandonar todo lo anterior.','Usar un único método obligatorio.'],['¿Para qué quieren recordar palabras?','Para usarlas.','To use them.'],['¿Qué aporta escuchar al otro?','Identificar una dificultad propia.','Demostrar que nadie aprende.','Evitar practicar.'],['¿Qué admite Elena?','Que recordar activamente ayuda.','That active recall helps.'],['¿Qué opinión matizada encaja?','Las historias ayudan, pero también necesito recuperar frases de memoria.','Solo existe un método válido.','Reconocer siempre equivale a hablar.'],'A supported view can change when another perspective reveals a need.')],[audio('Por una parte, el piso es barato. Por otra parte, está lejos del trabajo. Prefiero pagar un poco más para ahorrar tiempo cada día.','¿Qué prioridad explica la decisión?','Ahorrar tiempo diario.',['Tener más habitaciones.','Vivir más lejos.'],'Para gives the purpose behind accepting more cost.'),audio_text('Creo que debemos mover el banco, no quitarlo. Así dejamos paso y conservamos un lugar para descansar.','¿Qué quieren conservar?','Un lugar para descansar.',['A place to rest.','El banco'],'The argument balances circulation and rest.')],prod('views',['Escribe «I study Spanish to speak with my neighbours».','Translate the purpose.','Estudio español para hablar con mis vecinos.','Une: cuesta menos; tarda más. Usa por una parte / por otra parte.','Organise two aspects.','Por una parte cuesta menos; por otra parte tarda más.'],[('Elige entre tren y autobús y explica una ventaja de cada uno.','Choose transport while recognising both advantages.','Creo que el tren es mejor porque permite descansar. El autobús cuesta menos; sin embargo, tarda más.'),('Da tu opinión sobre una forma de aprender y considera otra.','Express a learning preference with another perspective.','Me parece útil leer historias porque las palabras tienen contexto. Sin embargo, también necesito practicar de memoria para hablar.'),('Propón una solución para una plaza con poco espacio y personas que necesitan sentarse.','Propose a reasoned solution balancing two needs.','Creo que podemos mover el banco para dejar más paso. Por otra parte, debemos conservar un lugar para descansar. Así atendemos dos necesidades.')],[('Expresa tu opinión',['creo que','me parece','pienso que']),('Apoya o matiza',['porque','sin embargo','por otra parte'])])))
b11.append(unit('When things go wrong','Clarify a less predictable service problem and negotiate a practical solution','Communication repair; delivery/booking/lost-property problems; polite clarification',[
core('Creo que ha habido un error con la reserva.','I think there has been a mistake with the booking.','ha habido',['han habido','ha haber'],'Impersonal haber stays singular: ha habido un error / varios errores.','Recepción: «Solo tenemos una noche». Tú reservaste dos.','Creo que ha habido un error; reservé dos noches.',['Nunca hay una reserva posible.','Sí, reservé mañana ayer.'],'El pedido contiene otro producto. Explica el error con calma.','Creo que ha habido un error con el pedido.'),
core('¿Podría explicarlo de otra manera?','Could you explain it another way?','Podría',['Pudo','Puede ayer'],'Conditional podría softens a request; it does not imply an inability or fault.','La explicación es demasiado rápida. ¿Qué pides?','¿Podría repetirlo más despacio?',['No quiero escuchar nada.','Ya repetí mañana.'],'No entiendes una instrucción. Pide otra explicación.','¿Podría explicarlo de otra manera?'),
core('Perdí la mochila mientras cambiaba de tren.','I lost my backpack while changing trains.','Perdí',['Perdía','Perderé'],'Perdí presents the loss; mientras cambiaba supplies the ongoing situation.','Empleado: «¿Dónde vio la mochila por última vez?»','La vi en el tren antes de cambiar.',['La veré ayer.','No tengo ninguna información.'],'Perdiste las llaves mientras salías del café. Cuenta la situación.','Perdí las llaves mientras salía del café.')],[
scene('Una entrega sin paquete','Marta recibió un aviso de entrega, pero no encontró ningún paquete en casa. Antes de escribir una queja, miró la dirección y preguntó a sus vecinos. Nadie lo tenía. Llamó a la empresa y explicó la diferencia entre el aviso y lo ocurrido. El empleado dijo que el paquete estaba en un punto de recogida. Marta no entendió el nombre de la calle y pidió que lo repitiera más despacio. Después preguntó hasta qué hora podía recogerlo y qué documento necesitaba. Anotó los datos y confirmó la dirección. El problema no desapareció con una disculpa, pero consiguió la información necesaria. Al final recogió el paquete sin comprar el producto otra vez.',[['punto de recogida','collection point'],['el aviso','notification']],['¿Qué diferencia inicia el problema?','El aviso dice entregado, pero no hay paquete en casa.','Marta no pidió nada.','El paquete está abierto.'],['¿Por qué pide repetir la calle?','No entendió el nombre.','She did not understand the name.'],['¿Qué demuestra la confirmación final?','Comprueba que entendió la información.','Acepta sin escuchar.','Compra otro producto.'],['¿Qué consiguió con la llamada?','Datos para recoger el paquete.','Information to collect the parcel.'],['¿Qué pregunta ayuda a resolverlo?','¿Qué documento necesito para recogerlo?','¿Por qué existen calles?','No quiero saber dónde está.'],'Clarifying location and requirements is more useful than accepting a vague apology.'),
scene('Una mochila reconocible','Luis perdió una mochila durante un cambio de tren. En objetos perdidos le preguntaron por el color, el tamaño y algún detalle especial. Era azul, pero eso no bastaba: tenía una cinta amarilla en una cremallera y un libro con su nombre dentro. El empleado encontró una mochila parecida. Luis no dijo inmediatamente que era suya. Describió el contenido antes de abrirla y después comprobó el libro. La cinta no estaba en el lugar que recordaba, pero el nombre y los objetos coincidían. Firmó la recogida y agradeció la ayuda. El relato muestra que describir algo útil no consiste en añadir muchos adjetivos: conviene escoger detalles que distingan ese objeto de otros.',[['la cremallera','zip'],['objetos perdidos','lost property']],['¿Qué detalle ayuda más a identificarla?','El libro con su nombre.','Solo ser azul.','Ser una mochila.'],['¿Por qué no la reclama inmediatamente?','Quiere comprobar que es suya.','He wants to check ownership.'],['¿Qué información es más útil?','Detalles que la distinguen.','Muchos adjetivos generales.','Ningún contenido.'],['¿Qué comprobó al final?','El nombre y los objetos.','The name and contents.'],['¿Qué descripción encaja?','Es azul y tiene un libro con mi nombre dentro.','Es una cosa normal sin detalles.','Será roja ayer.'],'Useful identification relies on distinctive evidence, not only a common colour.'),
scene('Dos personas con el mismo nombre','Ana llegó a un alojamiento donde había dos reservas a nombre de Ana. La recepcionista empezó a explicar que su habitación estaba cancelada. Ana mostró el número de confirmación y preguntó si hablaban de la misma reserva. Al comparar las fechas, vieron que la cancelación correspondía a otra persona. Ana no necesitó levantar la voz. Dio información concreta y pidió una comprobación. La recepcionista se disculpó y confirmó las dos noches. Antes de subir, Ana repitió el horario de salida para asegurarse de entenderlo. Luis, que esperaba fuera, pensó que la espera significaba un problema grave. Ana explicó que fue una confusión resuelta con datos, no una discusión.',[['a nombre de','in the name of'],['una comprobación','a check']],['¿Qué causó la confusión?','Dos reservas con el mismo nombre.','Dos hoteles cerrados.','Un viaje cancelado por Ana.'],['¿Qué permitió distinguir las reservas?','El número y las fechas.','The confirmation number and dates.'],['¿Qué muestra su forma de responder?','Pide comprobar antes de discutir.','Acepta una cancelación incorrecta.','Oculta la confirmación.'],['¿Cómo describe Ana la espera?','Una confusión resuelta con datos.','A confusion resolved using details.'],['¿Qué pregunta encaja?','¿Podemos comprobar el número de confirmación?','¿Por qué no conoce a todas las Anas?','No tengo ninguna reserva nunca.'],'A request to compare identifiers repairs a misunderstanding without blame.'),
scene('Una instrucción incompleta','Diego debía enviar un documento para una actividad. El mensaje decía «antes del jueves», pero no explicaba si debía usar un formulario o el correo. Diego envió un correo el miércoles y después descubrió que no aparecía en la lista. En lugar de reenviarlo muchas veces, preguntó qué paso faltaba. Elena explicó que el formulario incluía una autorización necesaria. Diego pidió que indicaran ese requisito en el mensaje original. Completó el formulario y recibió confirmación. Elena aceptó que la instrucción podía ser más clara. Los dos distinguieron la intención de Diego de un procedimiento incompleto. Resolver el problema requirió explicar lo que ya hizo y preguntar qué debía hacer después.',[['el requisito','requirement'],['el formulario','form']],['¿Qué faltaba en la primera instrucción?','El modo de enviar y la autorización.','La existencia del jueves.','El nombre de Diego.'],['¿Por qué no bastó el correo?','Faltaba una autorización del formulario.','The form included a necessary authorisation.'],['¿Qué mejora propone Diego?','Explicar el requisito desde el principio.','Eliminar todas las fechas.','Reenviar cien veces.'],['¿Qué reconoce Elena?','La instrucción podía ser más clara.','The instruction could be clearer.'],['¿Qué petición repara la comunicación?','¿Puede indicar qué paso falta?','Ya lo hice todo, no quiero saber más.','Nunca hay formularios.'],'Clarification identifies the missing procedure without denying the learner’s effort.')],[audio('En el mensaje pone que el pedido está entregado, pero no lo he recibido. He comprobado la dirección. ¿Puede decirme dónde está y cómo recogerlo?','¿Qué necesita la persona?','Localización e instrucciones de recogida.',['Otro pedido inmediato.','Cancelar su dirección.'],'The request follows a concrete mismatch and asks for next steps.'),audio_text('Perdí una mochila azul al cambiar de tren. Tiene una cinta amarilla y un libro con mi nombre. La vi por última vez en el primer tren.','¿Dónde la vio por última vez?','En el primer tren.',['On the first train.'],'The last known location is explicit.')],prod('repair',['Escribe «Could you repeat it more slowly?».','Translate a polite clarification request.','¿Podría repetirlo más despacio?','Explica: perdí las llaves; salía del café. Usa mientras.','Link a completed loss to an ongoing action.','Perdí las llaves mientras salía del café.'],[('Explica una diferencia entre tu reserva y la confirmación. Pide comprobarla.','Explain a booking mismatch and request a check.','Reservé dos noches, pero la confirmación muestra una. Creo que ha habido un error. ¿Podemos comprobar las fechas?'),('Describe un objeto perdido con detalles que lo distingan y explica dónde lo viste.','Describe a lost object and last known location.','Perdí una mochila azul con una cinta amarilla. Dentro hay un libro con mi nombre. La vi por última vez al cambiar de tren.'),('Escribe a una empresa: recibiste un aviso, no el paquete. Explica lo comprobado y pide el siguiente paso.','Explain a missing delivery and request actionable information.','He recibido un aviso de entrega, pero no tengo el paquete. He comprobado la dirección y preguntado a los vecinos. ¿Puede decirme dónde recogerlo y qué documento necesito?')],[('Explica un problema concreto',['pero','error','perdí']),('Pide aclaración o solución',['puede','podría','comprobar'])])))
b11.append(unit('A week to remember','Sustain a short connected account integrating events, reactions, reasons and changed plans','B1.1 synthesis: tense meaning, future, conditional advice, viewpoint',[
core('La semana empezó mal, pero al final encontramos una solución.','The week started badly, but in the end we found a solution.','encontramos',['encontrar','encontraremos'],'The surrounding past account makes encontramos a completed outcome.','Marta: «¿Todo salió mal?»','No; hubo problemas, pero encontramos una solución.',['Sí, nunca ocurrió ningún problema.','Mañana terminó ayer.'],'El viaje empezó con un retraso, pero llegaste. Resume el resultado.','El viaje empezó con un retraso, pero al final llegué.'),
core('Me preocupó el cambio; sin embargo, pudimos seguir adelante.','The change worried me; however, we were able to continue.','pudimos',['podíamos mañana','podremos'],'Pudimos reports a successful possibility on that occasion; sin embargo marks contrast.','Ana: «¿Cómo os afectó el cambio?»','Nos preocupó, pero seguimos adelante.',['No sabemos nada de esa semana.','Mañana nos afectó ayer.'],'Te sorprendió el retraso, pero encontraste otra opción.','Me sorprendió el retraso; sin embargo, encontré otra opción.'),
core('La próxima vez comprobaré los horarios y pediré ayuda antes.','Next time I will check the schedules and ask for help earlier.','comprobaré',['comprobé','comprobaba'],'Future commitment connects reflection to a concrete next action.','Luis: «¿Qué harás de otra manera?»','Pediré ayuda antes.',['Pedí mañana.','No pasó nada nunca.'],'La próxima vez harás una lista y reservarás antes.','La próxima vez haré una lista y reservaré antes.')],[
scene('La semana de la exposición','Elena preparó una pequeña exposición con sus compañeros. El lunes descubrieron que la sala no tenía suficientes mesas. Primero pidieron ayuda al centro y después llamaron a un café cercano. Diego pudo prestarles dos mesas. Mientras organizaban las fotografías, Ana encontró un error en una fecha. Lo corrigieron antes de imprimir el cartel. El jueves Elena estaba cansada y temía olvidar algo. Luis le sugirió repartir las últimas tareas. El sábado llegaron los visitantes y hicieron preguntas interesantes. Al final Elena lo pasó bien, aunque la semana fue difícil. Dijo que la próxima vez preparará una lista compartida desde el principio. Su relato no oculta los problemas; explica cómo respondieron a ellos.',[['prestarles','lend them'],['el cartel','poster']],['¿Qué ayudó con las mesas?','El café prestó dos.','Cancelaron la exposición.','Llegaron menos visitantes.'],['¿Por qué corrigieron la fecha antes de imprimir?','Para evitar un error en el cartel.','To avoid a poster error.'],['¿Qué aprende Elena para la próxima vez?','Preparar una lista compartida antes.','Trabajar siempre sola.','No aceptar preguntas.'],['¿Cómo valora el resultado?','Disfrutó, aunque fue una semana difícil.','She enjoyed it despite a difficult week.'],['¿Qué resumen es equilibrado?','Hubo dificultades y el grupo encontró soluciones.','Todo salió sin ningún cambio.','Nunca abrieron la exposición.'],'A connected account links difficulties, responses and reflection.'),
scene('El viaje de Clara','Clara iba a visitar a su hermana durante el fin de semana. El tren del viernes se retrasó y perdió una conexión. Primero se preocupó porque su hermana esperaba en la estación. Después la llamó y buscó otra opción. Podía tomar un autobús, aunque llegaría más tarde. Su hermana propuso recogerla en otra parada. Clara aceptó y confirmó la nueva hora. El sábado caminaron y cocinaron juntas. El viaje no fue como pensaba, pero lo pasó muy bien. Al volver, explicó que la comunicación fue más importante que mantener el horario inicial. La próxima vez dejará más tiempo entre conexiones. No cree que eso elimine todos los problemas, pero sí puede reducir una dificultad previsible.',[['la conexión','connection'],['previsible','predictable']],['¿Qué perdió Clara?','Una conexión.','La dirección de su hermana.','Todas sus pertenencias.'],['¿Por qué llamó a su hermana?','Para explicar el retraso y cambiar la recogida.','To explain the delay and change the pickup.'],['¿Qué puede mejorar sin garantizar todo?','Dejar más tiempo entre conexiones.','No viajar nunca.','No comunicar cambios.'],['¿Qué valoró al final?','La comunicación y el tiempo juntas.','Communication and time together.'],['¿Qué reflexión encaja?','El plan cambió, pero encontramos otra opción.','Todo fue exactamente igual.','No pude ver a mi hermana.'],'A changed itinerary need not mean a failed visit.'),
scene('Un proyecto compartido','Marta y Ana prepararon un taller para vecinos nuevos. Antes Marta hacía casi todo sola y terminaba agotada. Esta vez pidió ayuda desde el principio. Ana escribió el mensaje de invitación y Luis organizó el espacio. El día del taller hubo más gente de la prevista. Primero movieron algunas sillas y después dividieron el grupo en dos. A Marta le sorprendió que los participantes también ofrecieran soluciones. Al final varias personas propusieron otra sesión. Marta explicó que todavía hubo momentos de confusión, pero ya no sentía que todo dependía de ella. Quiere mantener esa forma de trabajar. La próxima semana hablará con el grupo para decidir un tema, en lugar de elegirlo sin escuchar.',[['agotada','exhausted'],['de la prevista','than expected']],['¿Qué cambió respecto a antes?','Marta repartió tareas desde el principio.','Trabajó totalmente sola.','Canceló el taller.'],['¿Por qué dividieron el grupo?','Había más gente de la prevista.','More people came than expected.'],['¿Qué indica la propuesta de otra sesión?','El encuentro despertó interés.','Nadie disfrutó.','Todos conocían ya el tema.'],['¿Qué dejó de sentir Marta?','Que todo dependía de ella.','That everything depended on her.'],['¿Qué plan mantiene esa mejora?','Hablaré con el grupo antes de elegir el tema.','Elegiré todo sin preguntar.','Nunca pediré ayuda.'],'The experience connects changed habits with shared responsibility.'),
scene('La conversación del domingo','El domingo Ana, Luis y Diego hablaron de sus semanas. Ana contó una visita agradable; Luis explicó un retraso y Diego una presentación difícil. No compitieron por decidir quién tuvo la semana peor. Primero escucharon lo ocurrido y después preguntaron qué ayudó en cada caso. Ana disfrutó porque no llenó todo el día de planes. Luis llamó cuando cambió el horario. Diego pidió comentarios y acortó su presentación. Cada uno encontró una idea útil en la experiencia de otro. Al final acordaron una salida sencilla para la semana siguiente. Todavía no eligieron el lugar, pero fijaron una hora para hablar. El encuentro transformó tres relatos individuales en una conversación con preguntas, razones y propuestas.',[['acortó','shortened'],['fijaron','set']],['¿Cómo organizaron la conversación?','Escucharon y preguntaron antes de proponer.','Compitieron por la peor semana.','Solo habló Ana.'],['¿Qué ayudó a Diego?','Los comentarios y una presentación más corta.','Feedback and a shorter presentation.'],['¿Qué salió de compartir experiencias?','Ideas útiles y una nueva propuesta.','Una clasificación de amigos.','Una salida ya reservada.'],['¿Qué valoran del encuentro?','Escucharse y aprender de distintas experiencias.','Listening and learning from different experiences.'],['¿Qué pregunta continúa el diálogo?','¿Qué te ayudó a resolverlo?','¿Por qué tu semana no cuenta?','¿Quién ganó la semana?'],'Connected communication includes responding to other accounts, not only telling your own.')],[audio('La semana empezó con un problema de espacio. Pedimos mesas prestadas y repartimos las tareas. Me preocupó el tiempo, pero al final abrimos la exposición. La próxima vez haré una lista antes.','¿Qué une el relato con el futuro?','Una mejora concreta para la próxima vez.',['Una promesa de no tener problemas nunca.','Una fecha sin relación.'],'Reflection produces an actionable next step.'),audio_text('Antes preparaba todo sola. Esta vez Ana escribió la invitación y Luis organizó las sillas. Me sorprendió la ayuda del grupo.','¿Qué cambio hizo esta vez?','Repartió las tareas.',['She shared the tasks.','Pidió ayuda'],'The contrast concerns sharing responsibility.')],prod('synthesis',['Escribe «Next time I will ask for help earlier».','Translate the future reflection.','La próxima vez pediré ayuda antes.','Une: me preocupó el cambio; encontramos una solución. Usa sin embargo.','Link reaction and outcome.','Me preocupó el cambio; sin embargo, encontramos una solución.'],[('Cuenta tres momentos de una semana y cómo se relacionan.','Link three moments from a week.','El lunes hubo un retraso. Después cambiamos el plan y pedimos ayuda. Al final encontramos una solución que nos permitió continuar.'),('Cuenta una semana con un problema, una reacción y una reflexión.','Narrate a week with a problem, reaction and reflection.','Preparaba una presentación cuando cambió la fecha. Me preocupó tener menos tiempo. Una compañera me ayudó a organizarla. La próxima vez empezaré antes.'),('Escribe a una amiga: explica un problema de la semana, cómo lo resolviste y qué harás después.','Write a connected message linking past problem, solution and next step.','Esta semana cambió el horario del viaje y me preocupó llegar tarde. Primero llamé a Luis y después buscamos otro tren. Al final llegamos juntos. La próxima vez comprobaré las conexiones antes de comprar.')],[('Ordena lo ocurrido',['primero','después','al final']),('Añade reacción o reflexión',['me preocupó','me sorprendió','la próxima vez'])])))
save('B1.1',b11)
b12=[]
b12.append(unit('People and relationships','Explain an interpersonal misunderstanding and agree a constructive response','Llevarse bien, confiar en, misunderstandings; por/para consolidation',[
core('Me llevo bien con Elena, aunque a veces no estamos de acuerdo.','I get on well with Elena, although sometimes we disagree.','Me llevo',['Me lleva','Mi llevo'],'Llevarse bien describes a relationship; disagreement does not automatically mean conflict.','Luis: «¿Os lleváis bien?»','Sí, aunque tenemos opiniones distintas.',['Sí, todos pensamos exactamente igual siempre.','Yo se lleva con Elena.'],'Te llevas bien con Luis, pero preferís actividades distintas.','Me llevo bien con Luis, aunque preferimos actividades distintas.'),
core('Pensé que estabas enfadada porque no respondiste.','I thought you were angry because you did not reply.','Pensé',['Pienso mañana','Pensar'],'Pensé reports an interpretation, not proof of the other person’s feelings.','Marta: «No estaba enfadada; estaba trabajando».','Perdona, interpreté mal tu silencio.',['No, yo conozco tus sentimientos mejor.','No tengo que escuchar.'],'Interpretaste mal un mensaje corto. Reconoce el malentendido.','Perdona, interpreté mal tu mensaje.'),
core('Confío en ti, pero necesito entender qué pasó.','I trust you, but I need to understand what happened.','Confío en',['Confío de','Confío a'],'Confiar takes en. The request allows clarification without rejecting trust.','Ana: «¿Por qué quieres hablar?»','Para entender lo que pasó, no para discutir.',['Por empezar una discusión sin escuchar.','Porque todo está claro y no importa.'],'Quieres aclarar un cambio sin discutir. Expresa el propósito.','Quiero hablar para entender el cambio, no para discutir.')],[
scene('Un mensaje demasiado corto','Marta escribió a Elena para cambiar una cena. Elena respondió solo «vale». Marta pensó que estaba enfadada porque normalmente añadía una pregunta o un comentario. Durante dos días no volvió a escribir. Elena, por su parte, esperaba la nueva hora y no entendía el silencio. Cuando se encontraron, descubrieron que Elena respondió deprisa entre dos reuniones. No estaba molesta con la propuesta. Marta reconoció que interpretó una palabra sin comprobar el contexto. Elena admitió que podía haber añadido «dime la nueva hora». Las dos se llevan bien, pero no leen los mensajes de la misma forma. Acordaron preguntar antes de sacar conclusiones. No prometieron estar siempre disponibles: buscaron una manera de distinguir un retraso normal de algo que necesitan aclarar.',[['molesta','upset'],['sacar conclusiones','draw conclusions']],['¿Qué originó el malentendido?','Interpretar un mensaje corto sin contexto.','Una cena que ninguna quería.','Una reunión confirmada.'],['¿Por qué respondió Elena tan brevemente?','Estaba entre reuniones.','She was between meetings.'],['¿Qué acuerdo evita repetir el problema?','Preguntar antes de concluir que hay enfado.','Contestar siempre inmediatamente.','No escribir nunca.'],['¿Qué reconoce Marta?','Que interpretó sin comprobar.','That she interpreted without checking.'],['¿Qué respuesta repara la conversación?','Pensé que estabas enfadada; ahora entiendo lo que pasó.','Tu mensaje prueba que nunca me escuchas.','No importa tu explicación.'],'Distinguish a personal interpretation from evidence of another person’s feelings.'),
scene('El grupo del curso','Luis y Clara preparan un trabajo con dos compañeros. Uno habla mucho y otro casi no interviene. Clara piensa que el segundo no está interesado. Luis propone preguntarle qué parte prefiere hacer. El compañero explica que necesita más tiempo para organizar sus ideas y teme interrumpir. Tiene varias propuestas escritas que el grupo no conoce. Deciden enviar las preguntas antes de reunirse y dejar un turno para cada persona. El trabajo mejora porque aparecen ideas que antes quedaban fuera. Clara reconoce que participar no siempre significa hablar primero. Tampoco ignoran las responsabilidades: cada uno confirma una tarea y una fecha. El cambio permite escuchar mejor sin convertir la paciencia en una excusa para no cumplir acuerdos.',[['interviene','contributes'],['un turno','a turn']],['¿Qué confundió Clara con desinterés?','Hablar poco.','Llegar sin trabajo.','Rechazar una tarea.'],['¿Por qué hablaba poco el compañero?','Necesitaba ordenar sus ideas.','He needed time to organise ideas.'],['¿Qué aporta enviar preguntas antes?','Facilita distintas formas de participar.','Elimina las reuniones para siempre.','Evita responsabilidades.'],['¿Qué aprende Clara?','Participar no es hablar primero.','Participation is not speaking first.'],['¿Qué propuesta es constructiva?','Enviemos las preguntas antes y dejemos un turno a cada persona.','Solo escucharemos a quien habla más.','Nadie tendrá tareas.'],'A fair process combines inclusion with clear responsibilities.'),
scene('Dos amigos, dos planes','Ana quiere pasar toda una tarde con Luis, pero él solo tiene una hora. Ana interpreta el límite como falta de interés. Luis explica que debe ayudar a su padre y que no quiere cancelar otra vez. Le propone un paseo corto y una cena otro día. Ana entiende que una disponibilidad limitada no equivale a una amistad limitada. Explica que tenía ganas de hablar con calma y los dos buscan otro momento. No terminan pensando lo mismo sobre cada plan: Ana prefiere acordar fechas antes y Luis suele decidir más tarde. Aun así, confían el uno en el otro. Acordar una próxima cena permite cuidar la amistad sin exigir que uno abandone todos sus compromisos por el otro.',[['equivale a','is equivalent to'],['disponibilidad','availability']],['¿Qué confundió Ana al principio?','Poco tiempo con poco interés.','Una hora con todo el día.','La cena con el trabajo.'],['¿Por qué Luis tiene una hora?','Debe ayudar a su padre.','He must help his father.'],['¿Qué soluciona la próxima cena?','Un momento para hablar con calma.','Todas sus diferencias.','El trabajo del padre.'],['¿Qué mantiene la relación?','La confianza aunque prefieren organizarse de modo distinto.','Trust despite different planning styles.'],['¿Qué respuesta respeta ambos límites?','Podemos pasear hoy y hablar con más tiempo otro día.','Si eres mi amigo, debes cancelar todo.','Nunca volveremos a hablar.'],'An explanation can separate relationship quality from immediate availability.'),
scene('La foto compartida','Diego publicó una foto de una cena sin preguntar a quienes aparecían. Elena le pidió quitarla porque no quería una imagen suya en una página pública. Diego se sorprendió: pensaba que era una manera de agradecer la visita. Elena explicó que apreciaba la cena, pero prefería decidir qué imágenes comparte. Diego retiró la foto y pidió disculpas. Después preguntó si podía publicar una foto solo de los platos. Elena aceptó. No tuvieron que discutir si todas las fotos son buenas o malas. El punto era respetar una preferencia concreta y preguntar antes. Diego entendió que una buena intención no elimina el efecto que una acción tiene en otra persona. La próxima vez pedirá permiso sin esperar a que alguien proteste.',[['retiró','removed'],['permiso','permission']],['¿Qué pidió Elena?','Retirar su imagen pública.','Cancelar la cena.','Eliminar todas las fotos del mundo.'],['¿Por qué se sorprendió Diego?','Su intención era agradecer la visita.','He intended to thank the visitors.'],['¿Qué distingue Elena?','Apreciar la cena y decidir sobre su imagen.','Todas las fotos y todas las cenas son malas.','Una foto demuestra amistad.'],['¿Qué aprendió Diego?','La intención no elimina el efecto.','Good intentions do not erase effects.'],['¿Qué respuesta respeta el límite?','Perdona; la retiro y preguntaré antes la próxima vez.','Debes aceptar porque mi intención era buena.','No importa lo que prefieras.'],'Constructive repair acknowledges the specific effect and changes future action.')],[audio('Pensé que no querías venir porque respondiste muy tarde. Ahora entiendo que estabas trabajando. Perdona; la próxima vez preguntaré antes de sacar conclusiones.','¿Qué cambia en la conversación?','La interpretación del retraso.',['La fecha del trabajo.','El lugar de la cena.'],'New context changes the initial interpretation.'),audio_text('Nos llevamos bien, aunque nos organizamos de manera distinta. Yo prefiero acordar una hora antes; Luis suele decidir más tarde.','¿Qué prefiere la primera persona?','Acordar una hora antes.',['Agreeing a time in advance.'],'The speakers differ in planning style.')],prod('relationships',['Escribe «I trust you».','Translate the fixed phrase.','Confío en ti.','Transforma: yo me llevo bien; nosotros.','Change to nosotros.','Nos llevamos bien.'],[('Aclara un malentendido sin acusar a la otra persona.','Clarify a misunderstanding without blame.','Pensé que estabas enfadada porque no respondiste. Ahora entiendo que estabas trabajando. La próxima vez preguntaré antes.'),('Cuenta un desacuerdo y cómo cuidaste la relación.','Describe disagreement and how you maintained the relationship.','Nos llevamos bien, aunque preferimos planes distintos. Expliqué que necesitaba más tiempo y escuché su propuesta. Encontramos otro día para quedar.'),('Escribe a alguien: explica tu interpretación, reconoce otra posibilidad y propone hablar.','Write a message acknowledging interpretation and proposing clarification.','Interpreté tu mensaje como una negativa, pero quizá tenías poco tiempo. Confío en ti y quiero entender lo que pasó. ¿Podemos hablar esta tarde?')],[('Explica sin acusar',['pensé','interpreté','quizá']),('Propón aclarar',['hablar','entender','preguntar'])])))
b12.append(unit('Work and study','Explain responsibilities, experience and a reasoned work/study decision','Responsibilities, applications, collaboration; desde/experience; clear formal requests',[
core('Me encargo de organizar las reuniones del equipo.','I am responsible for organising the team meetings.','Me encargo',['Me encarga','Mi encargo'],'Encargarse de links a person with a responsibility and an infinitive.','Elena: «¿Qué haces en el equipo?»','Me encargo de organizar las reuniones.',['Me encargo a reuniones.','No existe ninguna tarea.'],'Tú organizas los materiales del curso. Explica tu responsabilidad.','Me encargo de organizar los materiales del curso.'),
core('Elegí este curso porque combina teoría y práctica.','I chose this course because it combines theory and practice.','Elegí',['Elijo ayer','Elegiré ayer'],'Elegí reports a decision; porque explains the criterion behind it.','Luis: «¿Por qué has elegido este curso?»','Porque combina teoría y práctica.',['Solo porque existe, no hay razón.','Para el curso es ayer.'],'Elegiste un trabajo porque puedes aprender y colaborar.','Elegí este trabajo porque puedo aprender y colaborar.'),
core('Tengo experiencia atendiendo a clientes y me gustaría aprender más.','I have experience serving customers and would like to learn more.','me gustaría',['me gustará ayer','yo gustar'],'Me gustaría expresses a polite goal rather than claiming you already know everything.','Empresa: «¿Qué quiere desarrollar?»','Me gustaría mejorar la atención al cliente.',['Ya sé todo y nunca aprenderé.','Me gustan aprender.'],'Tienes experiencia organizando actividades; quieres mejorar la comunicación.','Tengo experiencia organizando actividades y me gustaría mejorar la comunicación.')],[
scene('Una solicitud con ejemplos','Clara quiere trabajar unas horas en un centro cultural. Su primer borrador dice que es responsable y que aprende rápido. Elena le pregunta qué ejemplos apoyan esas frases. Clara recuerda que organizó un club de lectura y resolvió cambios de horario cuando faltó una sala. Añade esos datos a la solicitud. No afirma tener experiencia en todas las tareas del puesto. Explica lo que sabe hacer y lo que le gustaría aprender. También pregunta por el horario porque debe seguir estudiando. Elena le recuerda que una solicitud no es una lista de elogios: ayuda al centro a entender si sus necesidades y la disponibilidad de Clara encajan. El mensaje final es más concreto, sin convertirse en una promesa imposible de cumplir.',[['el borrador','draft'],['el puesto','position']],['¿Qué mejora la solicitud?','Ejemplos concretos de experiencia.','Más elogios sin ejemplos.','Prometer saber todo.'],['¿Por qué pregunta por el horario?','Debe seguir estudiando.','She must continue studying.'],['¿Qué evita el mensaje final?','Promesas imposibles.','Mostrar experiencia.','Preguntar por condiciones.'],['¿Cómo entiende Elena una solicitud?','Debe mostrar si encajan necesidades y disponibilidad.','It helps match needs and availability.'],['¿Qué frase aporta evidencia?','Organicé un club de lectura y resolví cambios de sala.','Soy perfecta en todo.','Nunca necesito aprender.'],'Relevant examples support a claim better than unbounded praise.'),
scene('Repartir el trabajo','Diego y Luis preparan una actividad para un curso. Luis piensa que Diego comprará los materiales; Diego cree que esa tarea corresponde a Luis. Dos días antes descubren que nadie ha hecho la compra. En vez de discutir quién es más responsable, revisan el mensaje donde repartieron las tareas. Solo decía «nos encargamos de los materiales». Acuerdan una división explícita: Diego hará la lista y Luis comprará lo necesario. También fijan una hora para comprobar el resultado. El error les sirve para cambiar cómo colaboran. No basta con decir que el equipo hará algo si nadie sabe qué parte le corresponde. Al final preparan la actividad a tiempo y añaden nombres a las próximas tareas.',[['le corresponde','is their responsibility'],['explícita','explicit']],['¿Qué falló en el primer acuerdo?','No asignó responsabilidades individuales.','Nadie tenía tiempo en absoluto.','No existía una actividad.'],['¿Por qué no compraron?','Cada uno pensó que lo haría el otro.','Each thought the other would do it.'],['¿Qué mejora la nueva división?','Relaciona cada tarea con una persona.','Elimina la comprobación.','Deja todo igual.'],['¿Qué aprendieron sobre colaborar?','El acuerdo debe ser concreto.','The agreement must be specific.'],['¿Qué mensaje evita la confusión?','Diego hará la lista y Luis comprará los materiales.','Alguien hará algo.','No hace falta confirmar nada.'],'Clear responsibility prevents a shared phrase from hiding an unassigned task.'),
scene('Un curso compatible','Ana compara dos cursos de fotografía. Uno es más conocido, pero termina tarde y exige asistir cuatro días. Otro tiene menos clases y permite preparar un proyecto desde casa. Ana trabaja por las tardes y no puede cambiar todos sus turnos. Luis recomienda el primero porque aprendió mucho allí. Ana escucha su experiencia, pero explica que sus condiciones son distintas. Elige el segundo porque puede completar las tareas sin dejar el trabajo. Antes de pagar pregunta cuánto apoyo recibirá durante el proyecto. No decide solo por el precio ni por la reputación. Busca un curso que combine aprendizaje y una rutina sostenible. Luis acepta que su recomendación puede ser buena sin ser la mejor opción para Ana.',[['la reputación','reputation'],['sostenible','sustainable']],['¿Qué limita la decisión de Ana?','Sus turnos de trabajo.','La cámara de Luis.','No querer aprender.'],['¿Por qué elige el segundo?','Es compatible con su trabajo.','It fits her work schedule.'],['¿Qué muestra la pregunta sobre apoyo?','Considera la calidad además del horario.','Solo mira el precio.','No hará el proyecto.'],['¿Qué acepta Luis?','Su recomendación no sirve igual para Ana.','His recommendation may not suit Ana equally.'],['¿Qué explicación encaja?','Lo elegí porque puedo estudiar sin dejar el trabajo.','Todos deben elegir el más conocido.','No importa si puedo asistir.'],'A reasoned decision links personal constraints with learning needs.'),
scene('Pedir comentarios útiles','Elena recibe un proyecto de Diego y escribe que está bien. Diego se alegra, pero no sabe qué mantener ni qué cambiar. Le pide un ejemplo de una parte clara y otra que necesita trabajo. Elena señala una explicación breve que funciona y una conclusión que repite datos sin responder a la pregunta. Diego revisa la conclusión y entrega una segunda versión. No pide que Elena escriba por él; busca información para decidir. Elena también aprende a dar comentarios más concretos. En la siguiente reunión preguntan qué tipo de ayuda necesita cada compañero. El intercambio muestra que pedir orientación no significa dejar de ser responsable del propio trabajo. Una valoración positiva puede animar, pero un ejemplo específico permite mejorar.',[['la conclusión','conclusion'],['orientación','guidance']],['¿Qué pidió Diego?','Ejemplos concretos para mejorar.','Que Elena escribiera todo.','Una nota sin explicación.'],['¿Por qué no bastó «está bien»?','No indicó qué mantener o cambiar.','It did not show what to retain or change.'],['¿Qué conserva Diego?','La responsabilidad de revisar.','La primera conclusión sin cambios.','El papel de evaluador de Elena.'],['¿Qué aprende Elena?','Dar comentarios más concretos.','To give more specific feedback.'],['¿Qué petición encaja?','¿Puede señalar una parte clara y otra que deba mejorar?','Escríbalo todo por mí.','No quiero ejemplos.'],'Specific feedback supports independent revision rather than replacing it.')],[audio('Me encargo de preparar el material. Elegí esta tarea porque tengo experiencia organizando actividades, pero necesito confirmar el número de participantes antes de comprar.','¿Qué falta antes de comprar?','Confirmar cuántas personas participan.',['Elegir el curso.','Pedir otro trabajo.'],'A responsibility still needs a concrete input.'),audio_text('El curso más conocido termina tarde. He elegido otro porque puedo seguir trabajando por las tardes y preparar el proyecto desde casa.','¿Por qué ha elegido el otro curso?','Es compatible con su trabajo.',['It fits their work schedule.','Puede trabajar y estudiar'],'The reason is compatibility, not simply cost.')],prod('work',['Escribe «I am responsible for organising meetings».','Translate the responsibility.','Me encargo de organizar reuniones.','Expresa con me gustaría: quiero aprender más.','Soften the learning goal.','Me gustaría aprender más.'],[('Presenta experiencia con un ejemplo y explica una meta.','Present experience and a learning goal.','Tengo experiencia organizando actividades. El año pasado preparé un taller para vecinos. Me gustaría aprender a coordinar un equipo.'),('Explica una decisión de estudio considerando tus condiciones.','Explain a study decision and constraints.','Elegí un curso con proyectos desde casa porque trabajo por las tardes. Quiero aprender, pero necesito un horario compatible. Antes de pagar pregunté qué apoyo ofrecen.'),('Escribe una solicitud breve: experiencia, disponibilidad y una pregunta concreta.','Write an application with experience, availability and a practical question.','Tengo experiencia atendiendo a clientes y organizando actividades. Estoy disponible por las mañanas y me gustaría aprender más. ¿Podría indicarme el horario del puesto?')],[('Apoya experiencia con un ejemplo',['experiencia','organicé','preparé']),('Expresa un objetivo o una necesidad',['me gustaría','necesito','porque'])])))
b12.append(unit('Media and technology','Explain technology habits, weigh benefits and resolve a familiar digital problem','Instructions, se puede; advantages/disadvantages; reasons and clarification',[
core('Uso el móvil para informarme, pero compruebo la fuente.','I use my phone to get information, but I check the source.','para',['por','desde'],'Para introduces the purpose; checking a source is separate from simply reading a message.','Ana: «¿Compartes todo lo que lees?»','No; primero compruebo la fuente.',['Sí, toda noticia es verdadera.','No existe ninguna fuente.'],'Usas el ordenador para estudiar y compruebas las instrucciones.','Uso el ordenador para estudiar y compruebo las instrucciones.'),
core('Se puede guardar una copia antes de actualizar.','You can save a copy before updating.','Se puede',['Se pueden','Se pudo mañana'],'Se puede + infinitive describes an available action without specifying one person.','Luis: «¿Cómo protejo el documento?»','Puedes guardar una copia primero.',['Borra todo sin mirar.','No hace falta ninguna copia nunca.'],'Explica cómo proteger fotos antes de cambiar de móvil.','Se puede guardar una copia antes de cambiar de móvil.'),
core('La aplicación ahorra tiempo; sin embargo, no sustituye una explicación clara.','The app saves time; however, it does not replace a clear explanation.','sustituye',['sustituyo','sustituyen'],'La aplicación is singular third person. Sin embargo introduces a limit to an advantage.','Clara: «¿La herramienta lo resuelve todo?»','No; ayuda, pero todavía necesitamos explicar las tareas.',['Sí, nadie debe preguntar.','Nunca sirve para nada.'],'Una página facilita reservas, pero no siempre explica los cambios.','La página facilita las reservas; sin embargo, no siempre explica los cambios.')],[
scene('Una noticia en el grupo','Luis recibió en un grupo una noticia sobre el cierre de una estación. El mensaje no incluía fecha y una imagen parecía oficial. Estaba a punto de compartirlo cuando Ana preguntó dónde se publicó. Buscaron la información en la página de la empresa. El cierre fue el año anterior y la estación ya estaba abierta. Luis explicó al grupo la diferencia y añadió la fecha correcta. No se limitó a decir que todo era falso: la imagen describía un hecho real, pero antiguo. La experiencia le enseñó a comprobar origen y tiempo antes de usar una noticia para tomar decisiones. Ana recordó que una fuente conocida tampoco elimina la necesidad de leer los detalles relevantes para el viaje actual.',[['el origen','origin'],['se publicó','was published']],['¿Qué hacía engañoso el mensaje?','No aclaraba que el cierre era antiguo.','Nunca hubo estación.','La imagen era una receta.'],['¿Por qué buscaron otra página?','Para comprobar origen y fecha.','To check source and date.'],['¿Qué distinción hace Luis?','Un hecho real puede no ser información actual.','Toda imagen es falsa.','Toda página conocida es perfecta.'],['¿Qué aprende Luis?','Comprobar antes de compartir.','To check before sharing.'],['¿Qué corrección es útil?','El cierre fue el año pasado; la estación ya está abierta.','Todo internet miente siempre.','Compartid sin mirar la fecha.'],'Accuracy depends on context and time, not only whether an event once happened.'),
scene('El documento que desapareció','Diego estaba escribiendo un documento cuando la aplicación dejó de responder. Cerró la ventana y al volver vio una versión anterior. Se preocupó porque pensó que todo estaba perdido. Elena le pidió comprobar las copias guardadas y la hora de la última actualización. Encontraron una copia automática con casi todo el trabajo. Diego recuperó el texto y escribió de nuevo un párrafo corto. Después activó una forma de guardar versiones con nombres claros. Elena no aseguró que nunca volvería a fallar. Explicó qué paso redujo el riesgo y qué información necesitó para buscar la copia. El problema se resolvió sin culpar a Diego por no conocer cada función de la aplicación.',[['la copia automática','automatic backup'],['recuperó','recovered']],['¿Qué encontraron?','Una copia con casi todo el trabajo.','Un documento vacío para siempre.','Una nueva aplicación obligatoria.'],['¿Por qué miraron la hora de actualización?','Para identificar la versión reciente.','To identify the recent version.'],['¿Qué cambia después?','Guarda versiones con nombres claros.','Promete que nada fallará.','Deja de escribir.'],['¿Cómo explica Elena la solución?','Como reducción del riesgo, no garantía absoluta.','Risk reduction, not an absolute guarantee.'],['¿Qué instrucción ayuda?','Comprueba las copias y la hora antes de borrar nada.','Borra todas las versiones.','Todo está perdido sin comprobar.'],'A useful instruction is actionable and honest about limits.'),
scene('La llamada familiar','Clara llama a sus padres por vídeo cada domingo. A su padre le cuesta encontrar el botón para entrar. Antes Clara repetía las instrucciones más rápido porque pensaba que así terminarían antes. Ahora pregunta qué ve en la pantalla y explica un paso cada vez. Su madre escribió una lista corta que dejan junto al ordenador. La próxima llamada empieza sin ayuda. Clara se alegra, pero no concluye que sus padres ya conocen todas las funciones. Ellos quieren hablar con la familia, no aprender cada herramienta disponible. La tecnología facilita una conversación importante cuando las instrucciones se adaptan a la persona. Un mensaje largo con palabras técnicas habría sido menos útil que dos pasos claros y una comprobación.',[['la pantalla','screen'],['un paso cada vez','one step at a time']],['¿Qué cambió Clara?','Explicó pasos más claros y comprobó la pantalla.','Habló aún más rápido.','Quitó las llamadas.'],['¿Por qué usan la herramienta?','Para hablar con la familia.','To talk with family.'],['¿Qué muestra la siguiente llamada?','La lista les permite empezar sin ayuda.','Ya dominan todas las funciones.','No necesitan hablar.'],['¿Qué comprende Clara?','La explicación debe adaptarse a la persona.','The explanation must fit the person.'],['¿Qué pregunta ayuda antes de dar otro paso?','¿Qué ves ahora en la pantalla?','¿Por qué no sabes todo?','Pulsa todo a la vez.'],'Successful support checks the user’s context rather than assuming it.'),
scene('Tiempo conectado','Ana nota que mira el móvil incluso mientras conversa. No quiere dejar de usarlo: le sirve para orientarse y mantener contacto con amigos. Decide probar un límite durante las comidas. Luis teme que no vea un mensaje urgente. Ana explica que puede avisar a su familia y revisar el teléfono después. La primera semana no es perfecta; algunas veces lo mira sin pensar. En vez de presentar el cambio como un fracaso, observa cuándo ocurre y deja el móvil fuera de la mesa. Descubre que escucha mejor sin perder el contacto con otras personas. No recomienda el mismo límite para todos: Diego trabaja con pedidos y necesita atender ciertos avisos. Hablan de necesidades distintas, no de una regla moral única.',[['avisos','notifications'],['sin pensar','without thinking']],['¿Qué busca Ana?','Escuchar mejor durante las comidas.','Eliminar todo contacto.','No orientarse nunca.'],['¿Por qué no propone lo mismo a Diego?','Su trabajo necesita algunos avisos.','His work requires some notifications.'],['¿Cómo interpreta los primeros errores?','Como información para ajustar el hábito.','Como fracaso total.','Como prueba de que no hay problema.'],['¿Qué conserva Ana?','El contacto fuera de ese límite.','Contact outside that boundary.'],['¿Qué propuesta respeta diferentes necesidades?','Podemos elegir límites según nuestra situación.','Todos deben apagarlo siempre.','Nadie debe cambiar hábitos.'],'Weigh benefits and limits without turning one experiment into a universal rule.')],[audio('La noticia era real, pero del año pasado. Antes de compartirla miré la fecha en la página de la empresa. La estación está abierta ahora.','¿Qué problema tenía el mensaje?','Era antiguo y parecía actual.',['No existía ninguna estación.','La empresa no tenía página.'],'Temporal context changes relevance.'),audio_text('Primero pregunta qué aparece en la pantalla. Después explica un paso y comprueba el resultado. No hace falta describir todas las funciones.','¿Qué debe preguntar primero?','Qué aparece en la pantalla.',['What appears on the screen.'],'The instruction starts from the user’s view.')],prod('technology',['Escribe «You can save a copy before updating».','Translate the instruction.','Se puede guardar una copia antes de actualizar.','Cambia a nosotros: compruebo la fuente.','Change the subject.','Comprobamos la fuente.'],[('Explica una ventaja y un límite de una herramienta.','Explain a tool’s benefit and limitation.','La aplicación ahorra tiempo, pero no sustituye una explicación clara. La uso para organizar tareas y compruebo los detalles.'),('Cuenta un problema digital y explica cómo lo resolviste.','Narrate a digital problem and solution.','La aplicación dejó de responder y vi una versión antigua. Busqué una copia reciente y recuperé casi todo el documento. Ahora guardo versiones con nombres claros.'),('Escribe instrucciones sencillas para alguien que no conoce una herramienta.','Give accessible instructions and check understanding.','Primero abre el mensaje y busca el botón azul. Después pulsa una vez. Si no ves la reunión, dime qué aparece en la pantalla y lo comprobamos juntos.')],[('Explica pasos o razones',['primero','después','porque']),('Reconoce un límite o comprueba',['pero','comprueba','si no'])])))
b12.append(unit('Health and wellbeing','Explain a health history and daily habits, and seek appropriate help','Symptoms over time; practical advice; avoiding medical claims',[
core('Me duele la espalda desde ayer y hoy me cuesta moverme.','My back has hurt since yesterday and today moving is difficult.','duele',['duelen','duelo'],'La espalda is singular, so duele; desde ayer gives onset rather than diagnosis.','Profesional: «¿Desde cuándo le duele?»','Desde ayer por la tarde.',['Dentro de ayer mañana.','Desde hace ayer.'],'Te duelen los pies desde esta mañana. Explica el inicio.','Me duelen los pies desde esta mañana.'),
core('He dormido poco esta semana y necesito descansar.','I have slept little this week and need to rest.','He dormido',['Soy dormido','He dormir'],'Haber + participle reports a recent/open-period pattern; it does not explain every symptom.','Ana: «¿Cómo has dormido esta semana?»','He dormido poco y estoy cansado.',['Dormiré ayer toda la semana.','El cansancio prueba una enfermedad concreta.'],'Has trabajado muchas horas esta semana y quieres descansar.','He trabajado muchas horas esta semana y necesito descansar.'),
core('Deberías pedir consejo profesional si el problema continúa.','You should seek professional advice if the problem continues.','Deberías',['Debiste mañana','Deberías que'],'Soft advice can recommend qualified help without prescribing treatment.','Luis pide un diagnóstico a una amiga. ¿Qué respuesta es responsable?','No puedo diagnosticarlo; deberías consultar a un profesional.',['Seguro que no es nada; ignóralo siempre.','Toma cualquier medicamento sin preguntar.'],'No sabes qué causa una molestia. Explica el límite y aconseja ayuda.','No sé qué lo causa; deberías pedir consejo profesional.')],[
scene('Preparar la consulta','Marta tiene una molestia en la espalda y prepara una consulta. Ana le propone escribir cuándo empezó, qué estaba haciendo y cómo ha cambiado. Marta añade que le cuesta moverse por la mañana, pero mejora algo después. No busca una lista de enfermedades en mensajes del grupo. Quiere explicar su situación con claridad al profesional. También anota una pregunta sobre sus actividades habituales. Ana no recomienda un tratamiento ni asegura que sea un problema pequeño. La ayuda consiste en organizar la información y acompañarla si lo necesita. Marta se siente más tranquila porque sabe qué contar, no porque alguien haya prometido una solución antes de escucharla. En la consulta podrá preguntar cuando no entienda una indicación.',[['la molestia','discomfort'],['la consulta','appointment']],['¿Qué prepara Marta?','Información sobre inicio y cambios.','Un diagnóstico del grupo.','Un tratamiento de Ana.'],['¿Por qué escribe los detalles?','Para explicarlos con claridad.','To explain them clearly.'],['¿Qué límite respeta Ana?','No diagnostica ni prescribe.','Asegura una solución.','Niega la molestia.'],['¿Por qué está más tranquila Marta?','Sabe qué contar y preguntar.','She knows what to explain and ask.'],['¿Qué pregunta es útil?','¿Puede explicar cómo seguir esta indicación?','¿Puede confirmar el diagnóstico de mis amigos?','No quiero contar cuándo empezó.'],'Language support organises information without replacing clinical judgment.'),
scene('Una rutina posible','Diego quiere dormir mejor. Trabaja algunos días hasta tarde y antes intentaba levantarse siempre muy temprano para estudiar. Esta semana ha dormido poco y nota cansancio. Elena le sugiere revisar el horario y buscar una rutina posible, no copiar la de otra persona. Diego decide estudiar menos tiempo después de un turno largo y preparar tareas en una mañana libre. No espera cambiar todo en un día. También reconoce que, si el problema continúa, necesitará consejo profesional. Al comentar su plan, explica qué depende de él y qué no puede modificar ahora. La conversación no convierte el cansancio en un fallo personal. Busca un ajuste práctico y deja espacio para pedir ayuda cuando sea necesario.',[['un turno largo','a long shift'],['un ajuste','an adjustment']],['¿Qué dificultad limita la rutina?','Algunos turnos terminan tarde.','No quiere estudiar nunca.','No tiene tareas.'],['¿Por qué no copia otra rutina?','Sus condiciones son distintas.','His circumstances differ.'],['¿Qué hace si el problema sigue?','Buscar consejo profesional.','Ignorarlo siempre.','Diagnosticar a otros.'],['¿Cómo entiende el cambio?','Un ajuste posible, no una transformación inmediata.','A realistic adjustment, not an instant transformation.'],['¿Qué explicación encaja?','Después de un turno largo estudiaré menos y descansaré.','Dormir menos siempre es mejor.','Todos tienen mi horario.'],'Practical habits must account for constraints and limits of informal advice.'),
scene('En la farmacia','Luis entra en la farmacia porque no entiende una indicación de un producto que ya tiene. Lleva el envase y explica qué le preocupa. La farmacéutica le pregunta si la duda es sobre la cantidad, el horario o una advertencia. Luis señala la frase concreta y pide una explicación más sencilla. No compra otro producto solo porque un amigo lo recomienda. La farmacéutica aclara la información y le indica cuándo debe consultar con un profesional sanitario. Luis repite lo entendido para comprobarlo. Al salir no dice que domina todos los detalles; conserva la información escrita y sabe dónde preguntar de nuevo. La interacción muestra cómo usar el idioma para evitar una suposición cuando una instrucción afecta a la salud.',[['el envase','packaging'],['una advertencia','a warning']],['¿Para qué entra Luis?','Para aclarar una indicación.','Para copiar un consejo de un amigo.','Para dar diagnósticos.'],['¿Por qué lleva el envase?','Para mostrar la información concreta.','To show the exact information.'],['¿Qué aporta repetir lo entendido?','Comprobar la comprensión.','Cambiar la indicación por su cuenta.','Demostrar dominio total.'],['¿Qué actitud muestra Luis?','Pregunta en lugar de suponer.','He asks rather than assumes.'],['¿Qué petición es adecuada?','¿Puede explicar esta frase de manera más sencilla?','Voy a cambiar todo sin preguntar.','Mi amigo sabe todas las dosis.'],'Clarification and confirmation are language skills, not medical expertise.'),
scene('Caminar sin competir','Clara y Ana empiezan a caminar juntas dos tardes por semana. Clara quiere recorrer más distancia cada día, mientras Ana necesita un ritmo más suave. Al principio Ana siente que debe seguirla para no decepcionarla. Después explica que quiere disfrutar y mantener una rutina, no competir. Clara escucha y acuerdan un camino con opciones más cortas. Algunos días Clara continúa sola y otros vuelven juntas. No presentan caminar como una solución para cualquier problema de salud. Es una actividad que les gusta y que pueden adaptar. Ana valora poder expresar un límite sin perder la compañía. El acuerdo dura porque no depende de que las dos tengan siempre la misma energía ni los mismos objetivos.',[['un ritmo más suave','a gentler pace'],['decepcionarla','disappoint her']],['¿Qué aclaró Ana?','Quiere una rutina, no competir.','Quiere caminar más cada día sin límite.','No quiere compañía.'],['¿Por qué necesitaban adaptar el camino?','Tenían ritmos diferentes.','They had different paces.'],['¿Qué permite el acuerdo?','Mantener compañía y respetar límites.','Eliminar todas las diferencias.','Prometer una cura.'],['¿Qué valora Ana?','Poder expresar un límite.','Being able to express a limit.'],['¿Qué respuesta respeta el objetivo?','Podemos elegir una ruta corta y adaptar el ritmo.','Debes seguirme aunque no puedas.','Esto cura cualquier problema.'],'A sustainable shared activity can respect different needs without medical promises.')],[audio('La molestia empezó ayer por la tarde. Hoy me cuesta moverme al levantarme. No sé qué la causa y quiero explicarlo bien en la consulta.','¿Qué información da?','Inicio y cambio de la molestia.',['Un diagnóstico confirmado.','Una recomendación de medicamento.'],'The account describes symptoms, not a diagnosis.'),audio_text('He dormido poco esta semana porque algunos turnos terminaron tarde. Voy a ajustar el horario, pero pediré consejo profesional si el problema continúa.','¿Qué hará si continúa?','Pedir consejo profesional.',['Seek professional advice.'],'The plan acknowledges a limit to self-adjustment.')],prod('health',['Escribe «My feet hurt».','Translate the symptom structure.','Me duelen los pies.','Explica con desde: la molestia empezó ayer.','State symptom onset.','Tengo esta molestia desde ayer.'],[('Prepara un mensaje para una consulta: inicio, cambio y una pregunta.','Describe onset, development and a question for a consultation.','Me duele la espalda desde ayer. Hoy me cuesta moverme por la mañana. ¿Qué información debo llevar a la consulta?'),('Describe una rutina que quieres cambiar y tus límites.','Explain a routine change and constraints.','He dormido poco esta semana porque trabajo hasta tarde. Quiero ajustar el horario de estudio y descansar más. Si continúa el problema, pediré consejo profesional.'),('Pide una explicación clara sobre una indicación sin inventar un diagnóstico.','Ask for clarification without claiming a diagnosis.','No entiendo esta indicación del envase. ¿Puede explicarla de forma más sencilla? Quiero comprobar que he entendido cuándo debo consultar a un profesional.')],[('Describe o aclara información',['desde','no entiendo','esta semana']),('Pide ayuda apropiada',['profesional','consulta','puede'])])))
b12.append(unit('Travel and culture','Recommend a visit with reasons, practical limits and cultural observations','Experiences, comparisons, recommendations; avoiding generalisations',[
core('Te recomendaría visitar el mercado por la mañana.','I would recommend visiting the market in the morning.','recomendaría',['recomendé mañana','recomendaré ayer'],'Conditional recommendation allows for the visitor’s preferences.','Ana: «¿Dónde puedo conocer productos del barrio?»','Te recomendaría el mercado.',['Todos deben hacer lo mismo.','No existe ningún producto.'],'Recomienda el museo a quien prefiere una visita tranquila.','Te recomendaría visitar el museo si prefieres una visita tranquila.'),
core('En mi experiencia, la visita guiada ayuda a entender el lugar.','In my experience, the guided visit helps you understand the place.','En mi experiencia',['Por todos siempre','Nunca por nadie'],'Marking your experience avoids presenting one observation as a universal rule.','Luis: «¿Merece la pena la visita guiada?»','En mi experiencia, ayuda a entender el lugar.',['Todas las visitas son idénticas.','No se puede escuchar.'],'Tu experiencia fue positiva, aunque la visita era larga.','En mi experiencia, la visita fue interesante, aunque era larga.'),
core('Prefiero pasar más tiempo en un lugar que visitar muchos deprisa.','I prefer spending more time in one place to visiting many in a hurry.','Prefiero',['Preferimos','Prefieres'],'Prefiero links your personal priorities to a comparison, not a rule for everyone.','Elena: «¿Por qué no quieres añadir otra ciudad?»','Prefiero conocer este lugar con calma.',['Porque todas las ciudades son iguales.','Nunca me interesa nada.'],'Prefieres caminar por el barrio a pasar todo el día en el autobús.','Prefiero caminar por el barrio que pasar todo el día en el autobús.')],[
scene('La recomendación de Elena','Elena visita a unos amigos que vienen a Madrid por primera vez. Luis les recomienda tres museos, pero ellos solo tienen una mañana y viajan con una niña pequeña. Elena pregunta qué les interesa antes de añadir lugares. Les gusta conocer mercados y caminar sin muchas prisas. Propone una ruta corta que termina en una plaza con sombra. No afirma que sea la mejor ruta de la ciudad; explica por qué puede servirles. Luis acepta que su lista reflejaba sus propios intereses. Durante el paseo hablan con un vendedor y prueban un producto que no conocían. Al final los visitantes agradecen tener tiempo para preguntar. La recomendación funcionó porque se adaptó a las personas y al tiempo disponible.',[['con sombra','shaded'],['sin muchas prisas','without much hurry']],['¿Qué hace útil la ruta?','Se adapta a los visitantes y su tiempo.','Incluye todos los museos.','Evita hablar con nadie.'],['¿Por qué no siguen la lista inicial?','Tienen poco tiempo e intereses distintos.','They have limited time and different interests.'],['¿Qué reconoce Luis?','Recomendaba según sus preferencias.','Su lista es obligatoria.','Los visitantes no tienen intereses.'],['¿Qué agradecen los visitantes?','Tiempo para preguntar.','Time to ask questions.'],['¿Qué recomendación es contextual?','Esta ruta puede serviros porque es corta y permite parar.','Es la única visita válida.','Debéis ver todo en una mañana.'],'A recommendation should connect reasons with the recipient’s circumstances.'),
scene('Una costumbre observada','Ana visita un pueblo durante una fiesta local. Ve que algunas tiendas cierran antes y piensa que nadie trabaja por la tarde. Clara le explica que ese día hay un horario especial y que otras semanas es distinto. Ana cambia su descripción: en lugar de hablar de todo el pueblo, cuenta lo que observó durante la fiesta. Pregunta por la celebración y escucha dos historias diferentes de vecinos. No intenta decidir una regla única a partir de una tarde. Al volver, recomienda visitar el lugar, pero aconseja comprobar los horarios. La experiencia le enseña que una observación cultural gana valor cuando incluye su contexto. Puede contar algo interesante sin convertirlo en una afirmación sobre todas las personas de una región.',[['una afirmación','a claim'],['la celebración','celebration']],['¿Qué limitaba la observación de Ana?','Era un día de fiesta con horario especial.','Nunca abrió ninguna tienda.','No estuvo en el pueblo.'],['¿Por qué cambia su descripción?','No representa una semana normal.','It does not represent an ordinary week.'],['¿Qué conclusión es prudente?','Una tarde no prueba una costumbre universal.','Todos trabajan igual.','No se puede observar nada.'],['¿Qué aprende sobre describir cultura?','Incluir el contexto.','To include context.'],['¿Qué relato evita generalizar?','Durante la fiesta algunas tiendas cerraron antes.','Nadie del pueblo trabaja por la tarde nunca.','Todos los pueblos son idénticos.'],'Describe the observed event and its limits before drawing a wider conclusion.'),
scene('La visita que cambió de ritmo','Diego reservó una visita guiada por un barrio histórico. Esperaba caminar mucho, pero el guía dedicó tiempo a escuchar recuerdos de una vecina. Al principio Diego miraba el reloj. Después comprendió por qué una calle cambió de nombre y cómo se usaba una antigua tienda. La visita fue más lenta de lo esperado, aunque le pareció más interesante. Ana prefería ver más edificios y comentó esa diferencia con respeto. El guía explicó que existían rutas con otro enfoque. Los dos entendieron que no necesitaban valorar la experiencia de forma idéntica. Al recomendarla, Diego habló del ritmo y de las historias para que otros pudieran elegir. No ocultó lo que podría ser una desventaja para alguien con poco tiempo.',[['el enfoque','focus or approach'],['histórico','historic']],['¿Qué cambió el ritmo?','Escuchar recuerdos de una vecina.','Una avería del autobús.','La cancelación total.'],['¿Por qué Diego empezó a valorarlo?','Entendió la historia de la calle.','He understood the street’s history.'],['¿Qué información añade al recomendar?','El ritmo y el enfoque.','Solo una nota perfecta.','Una garantía para todos.'],['¿Qué prefería Ana?','Ver más edificios.','Seeing more buildings.'],['¿Qué recomendación es informativa?','Es una ruta lenta centrada en historias; puede gustarte si tienes tiempo.','Todo el mundo debe disfrutarla igual.','No tiene ninguna limitación.'],'Help a future visitor choose by explaining both the benefit and the pace.'),
scene('El billete y la experiencia','Marta compara una excursión organizada con viajar por su cuenta. La primera incluye transporte y una guía; la segunda permite quedarse más tiempo en cada lugar. El precio no es muy diferente. Marta pregunta qué pasa si cambia el horario y cuánto tiempo libre ofrece la excursión. Luis viajó con esa empresa una vez y cuenta una experiencia positiva, pero recuerda que fue en otra temporada. Marta no usa esa anécdota como garantía. Elige viajar por su cuenta porque quiere visitar a una amiga además del museo. Agradece la recomendación y explica su motivo. La decisión no significa que la excursión sea mala. Significa que una opción útil para Luis no responde del todo a lo que Marta quiere hacer esta vez.',[['por su cuenta','independently'],['la temporada','season']],['¿Qué decide Marta?','Viajar por su cuenta.','Comprar ambas opciones.','No viajar nunca.'],['¿Por qué la elige?','Quiere visitar a una amiga también.','She also wants to visit a friend.'],['¿Qué límite tiene la experiencia de Luis?','Fue en otra temporada.','Nunca viajó.','No conoce la empresa.'],['¿Qué distingue Marta?','Una buena opción de una opción adecuada para ella.','A good option from one fitting her needs.'],['¿Qué respuesta mantiene el respeto?','Gracias; esta vez prefiero viajar por mi cuenta por mi visita a una amiga.','Tu experiencia no vale nada.','La excursión es necesariamente mala.'],'Personal fit can explain a different decision without dismissing another experience.')],[audio('Te recomendaría la visita si te gustan las historias del barrio. Es lenta y tiene pocas paradas, pero explica bien el contexto. Si tienes solo una hora, quizá prefieras otra ruta.','¿Para quién puede ser menos adecuada?','Para alguien con solo una hora.',['Para quien disfruta historias.','Para quien quiere contexto.'],'The limitation is time, not a rejection of the tour.'),audio_text('Durante la fiesta, algunas tiendas cerraron antes. No sé si ocurre normalmente; conviene comprobar el horario antes de ir.','¿Qué conviene comprobar?','El horario.',['The opening hours.'],'The speaker avoids generalising from a special event.')],prod('travel',['Escribe «I would recommend visiting the market».','Translate the recommendation.','Te recomendaría visitar el mercado.','Expresa una preferencia por conocer un lugar con calma.','State the specified preference.','Prefiero conocer un lugar con calma.'],[('Recomienda una visita explicando para quién puede servir y un límite.','Recommend a visit with audience and limitation.','Te recomendaría la ruta si te interesan las historias. Es tranquila, aunque necesitas bastante tiempo. Si solo tienes una hora, buscaría otra opción.'),('Cuenta una observación cultural sin generalizar.','Describe a cultural observation with its context.','Durante la fiesta algunas tiendas cerraron antes. Una vecina explicó que era un horario especial. No sé si ocurre normalmente, así que comprobaría los horarios antes de otra visita.'),('Compara viajar por tu cuenta y una excursión. Elige según tus necesidades.','Compare two travel options and justify a personal choice.','La excursión incluye transporte y guía, pero deja poco tiempo libre. Prefiero viajar por mi cuenta porque quiero visitar a una amiga. La recomendación puede ser buena para otra persona.')],[('Da contexto o motivo',['porque','si','durante']),('Reconoce un límite',['aunque','pero','no sé'])])))
b12.append(unit('Hopes and hypotheticals','Describe an imagined possibility and a desired change without presenting it as fact','Conditional gustaría/sería/podría/haría/iría; hypothetical context without full si paradigms',[
core('Me gustaría trabajar cerca de casa.','I would like to work near home.','gustaría',['gustó','gustarán'],'Me gustaría expresses a desired possibility, not a confirmed arrangement.','Luis: «¿Qué cambiarías de tu rutina?»','Me gustaría trabajar cerca de casa.',['Ya trabajo allí, aunque no es verdad.','Me gustan trabajar.'],'Te gustaría tener más tiempo para estudiar.','Me gustaría tener más tiempo para estudiar.'),
core('Con más tiempo, podría aprender a cocinar mejor.','With more time, I could learn to cook better.','podría',['pude','podré ayer'],'Con más tiempo frames a hypothetical circumstance; podría is conditional possibility.','Ana: «Imagina una tarde libre».','Iría al museo y cocinaría con Marta.',['Fui mañana.','Eso ya ha pasado necesariamente.'],'Imagina un fin de semana libre: visitarías a tu hermana.','Con un fin de semana libre, iría a visitar a mi hermana.'),
core('Sería agradable vivir cerca, pero tendría que cambiar de trabajo.','It would be pleasant to live nearby, but I would have to change jobs.','Sería',['Fue','Será ayer'],'Conditional describes an imagined benefit and cost, not a decision already made.','Elena: «¿Te mudarías sin pensarlo?»','No; tendría que comparar las opciones.',['Sí, ya me mudé mañana.','No existe ningún coste.'],'Sería útil un curso nuevo, pero tendrías que organizar el horario.','Sería útil hacer otro curso, pero tendría que organizar el horario.')],[
scene('Una tarde imaginada','Ana y Marta hablan de qué harían con una tarde completamente libre. Ana iría al museo y después caminaría sin mirar el reloj. Marta cocinaría con su familia. No están acordando una salida concreta: comparan deseos con sus rutinas actuales. Ana reconoce que podría reservar una hora el domingo, aunque no toda la tarde. Marta piensa que no hace falta esperar una semana perfecta para preparar una cena sencilla. Las dos distinguen imaginar de prometer. El ejercicio les ayuda a encontrar un cambio pequeño que sí pueden probar. Al terminar acuerdan llamar el domingo para ver cómo fue. No aseguran que el trabajo desaparecerá; buscan espacio dentro de sus condiciones reales.',[['imaginar','imagine'],['las condiciones','circumstances']],['¿Qué hacen al principio?','Comparan deseos hipotéticos.','Reservan un viaje confirmado.','Narran una cena pasada.'],['¿Por qué consideran cambios pequeños?','No tienen una tarde totalmente libre.','They do not have a completely free afternoon.'],['¿Qué distingue el acuerdo final?','Es concreto, a diferencia del deseo inicial.','Todo sigue siendo una promesa imposible.','La semana será perfecta.'],['¿Qué aprende Marta?','No necesita esperar condiciones perfectas.','She need not wait for perfect conditions.'],['¿Qué frase conserva el carácter imaginado?','Con más tiempo, cocinaría con mi familia.','Ya cociné mañana.','He reservado necesariamente todo.'],'A conditional desire can guide a small real action without becoming a factual claim.'),
scene('La casa cerca del trabajo','Luis ve un piso cerca de su trabajo y piensa que su vida sería más fácil allí. Tendría menos trayecto y podría volver a casa a comer. Sin embargo, el alquiler es mayor y perdería la cercanía de sus amigos. Ana le ayuda a comparar sin decidir por él. Hablan primero de una semana normal y después de los gastos. Luis no confunde «me gustaría» con «puedo pagarlo». Decide visitar el piso y preguntar por las condiciones antes de hacer una oferta. La posibilidad sigue abierta. La conversación le permite explicar ventajas y costes de una vida imaginada, pero la decisión necesita datos. Al final no anuncia una mudanza: dice qué va a comprobar y por qué.',[['el alquiler','rent'],['hacer una oferta','make an offer']],['¿Qué ventaja imagina Luis?','Menos trayecto al trabajo.','Un alquiler más bajo confirmado.','Más cercanía de todos sus amigos.'],['¿Por qué no decide inmediatamente?','Necesita comparar gastos y condiciones.','He needs to compare costs and conditions.'],['¿Qué evita confundir?','Un deseo con la capacidad de pagarlo.','El presente con el lunes.','Una casa con una oficina.'],['¿Cómo termina la conversación?','Con una comprobación, no una mudanza confirmada.','With a check, not a confirmed move.'],['¿Qué frase es prudente?','Sería más cómodo; voy a comprobar si puedo pagarlo.','Me gusta, por tanto ya puedo pagarlo.','Ya me he mudado sin decidir.'],'Desired consequences are hypothetical until relevant conditions are checked.'),
scene('Un proyecto posible','Elena quiere organizar un club de conversación. Con una sala disponible podría reunir a vecinos una tarde por semana. Diego ofrecería bebidas del café, pero no puede pagar todo el material. Clara ayudaría con la invitación. Antes de anunciarlo hablan de lo que cada uno realmente puede aportar. El entusiasmo no garantiza que tengan espacio ni participantes. Elena pide información al centro cultural y pregunta si otras actividades usan la sala. No cancela la idea por no tener todo resuelto. La convierte en una propuesta con condiciones claras. El grupo decide empezar con una sesión de prueba si consigue el espacio. Así puede aprender de la experiencia antes de prometer un programa completo.',[['aportar','contribute'],['una sesión de prueba','a trial session']],['¿Qué condición falta?','Una sala disponible.','Todas las bebidas de la ciudad.','Una lengua nueva.'],['¿Por qué plantean una sesión de prueba?','Para aprender antes de prometer un programa.','To learn before promising a full programme.'],['¿Qué hace Elena con la idea?','Aclara condiciones sin abandonarla.','La anuncia como garantizada.','Espera que nadie ayude.'],['¿Qué límite expresa Diego?','No puede pagar todo el material.','He cannot pay for all materials.'],['¿Qué propuesta es honesta?','Podríamos empezar con una sesión si conseguimos una sala.','Todo está garantizado aunque no tengamos espacio.','No necesitamos ninguna condición.'],'Conditional language makes a proposal useful without overstating available resources.'),
scene('Una segunda oportunidad','Diego piensa en una presentación que no salió como esperaba. Dice que ahora la haría de otra manera: elegiría menos ejemplos y dejaría más tiempo para preguntas. Elena aclara que esa reflexión no cambia lo ocurrido. Puede, sin embargo, ayudarle a preparar la próxima presentación. Diego se pregunta si sería mejor empezar con una historia corta. Ensaya dos introducciones y compara cuál resulta más clara. No pretende encontrar una fórmula perfecta. Le gustaría sentirse más tranquilo y sabe que podría conseguirlo con práctica y comentarios específicos. El relato de la dificultad termina en una posibilidad de mejora, no en una promesa de éxito automático. La semana siguiente pedirá a un compañero que escuche el ensayo.',[['el ensayo','rehearsal'],['una fórmula','a formula']],['¿Qué expresa «ahora la haría de otra manera»?','Una alternativa imaginada a su forma de presentar.','Una nueva versión ya realizada.','Una fecha confirmada.'],['¿Por qué ensaya dos introducciones?','Para comparar su claridad.','To compare clarity.'],['¿Qué puede cambiar la reflexión?','La preparación de la próxima vez.','Los hechos pasados.','Todas las dificultades automáticamente.'],['¿Qué quiere Diego?','Sentirse más tranquilo con práctica.','To feel calmer through practice.'],['¿Qué frase conecta deseo y acción?','Me gustaría mejorar; pediré comentarios sobre el ensayo.','El deseo garantiza el éxito.','Todo lo pasado desaparece.'],'A hypothetical alternative supports a future plan without rewriting history.')],[audio('Con más tiempo, iría al museo y cocinaría con Marta. No es un plan confirmado; esta semana solo puedo reservar una hora el domingo.','¿Qué está confirmado?','Solo una hora disponible el domingo.',['Toda una tarde en el museo.','La cena completa.'],'The speaker explicitly separates wish from availability.'),audio_text('Sería cómodo vivir cerca del trabajo, pero tendría que pagar más alquiler. Antes de decidir voy a comprobar los gastos.','¿Qué va a comprobar?','Los gastos.',['The costs.'],'The imagined benefit does not settle affordability.')],prod('hypothetical',['Escribe «I would like more time».','Translate a desired possibility.','Me gustaría tener más tiempo.','Expresa una posibilidad con más tiempo: aprender a cocinar.','Use conditional possibility.','Con más tiempo, podría aprender a cocinar.'],[('Describe un cambio deseado y dos consecuencias posibles.','Describe a desired change and possible consequences.','Me gustaría vivir cerca del trabajo. Podría caminar cada día, pero tendría que pagar más alquiler.'),('Imagina un proyecto útil y explica qué necesitarías.','Imagine a useful project and its conditions.','Organizaría un club de conversación. Necesitaría una sala y una persona para ayudar con las invitaciones. Empezaría con una sesión pequeña.'),('Escribe sobre una opción todavía no decidida: ventaja, coste y siguiente comprobación.','Explain an undecided option and next check.','Sería agradable hacer otro curso y podría aprender algo nuevo. Sin embargo, tendría que cambiar mi horario. Voy a preguntar por las fechas antes de decidir.')],[('Marca deseo o hipótesis',['me gustaría','sería','podría']),('Incluye un límite o condición',['pero','necesitaría','tendría'])])))
b12.append(unit('Wishes, reactions and necessity','Express a wish, reaction or necessity involving another person','Limited present subjunctive after quiero que, espero que, es importante que, me alegra que; subject changes',[
core('Quiero que vengas a la reunión.','I want you to come to the meeting.','vengas',['vienes','venir'],'With quiero que and another subject, use present subjunctive. With the same subject, quiero venir uses an infinitive.','Ana: «¿Quieres venir tú o que vaya yo?»','Quiero que vengas tú.',['Quiero que tú vienes.','Quiero que tú venir.'],'Quieres que Luis llegue a tiempo. Expresa el deseo.','Quiero que Luis llegue a tiempo.'),
core('Espero que tengáis tiempo para hablar.','I hope you have time to talk.','tengáis',['tenéis','tienen'],'Espero que introduces a hoped-for action. Vosotros uses tengáis here, not indicative tenéis.','Marta habla a dos amigos. ¿Qué deseo expresa?','Espero que podáis venir.',['Espero que vosotros pueden.','Espero que vosotros venir.'],'Deseas que tus amigos estén bien. Usa espero que.','Espero que estéis bien.'),
core('Es importante que escuchemos antes de decidir.','It is important that we listen before deciding.','escuchemos',['escuchamos','escuchar'],'Es importante que evaluates an action and takes subjunctive; regular -AR uses -emos with nosotros.','Elena: «¿Qué necesitamos para trabajar juntos?»','Es importante que todos escuchemos.',['Es importante que todos escuchamos.','Es importante nadie escuchar.'],'Te alegra que Ana tenga una nueva oportunidad.','Me alegra que Ana tenga una nueva oportunidad.')],[
scene('Una invitación con un deseo','Marta invita a sus amigos a una reunión para preparar una actividad del barrio. Escribe «quiero que vengáis con ideas, no solo para escuchar». Luis pregunta si eso significa que deben tener una propuesta perfecta. Marta aclara que espera que compartan dudas y ejemplos pequeños. No exige saberlo todo. Ana responde que le alegra que el grupo esté abierto a personas nuevas. Diego tiene poco tiempo y pregunta si puede llegar más tarde. Marta dice que es importante que avise para organizar el principio. El intercambio distingue una invitación, un deseo sobre la participación y una necesidad práctica. La forma de expresar esos puntos ayuda a no presentar cada preferencia como una obligación absoluta.',[['compartan','share: hoped-for action'],['avise','let someone know']],['¿Qué desea Marta?','Participación con ideas y dudas.','Propuestas perfectas obligatorias.','Solo silencio.'],['¿Por qué Diego debe avisar?','Para organizar el principio.','To organise the beginning.'],['¿Qué aclara Marta sobre las ideas?','No tienen que ser perfectas.','Nadie debe traer ninguna.','Solo Luis puede hablar.'],['¿Qué reacción expresa Ana?','Le alegra que el grupo esté abierto.','She is glad the group is open.'],['¿Qué deseo encaja?','Espero que compartáis también vuestras dudas.','Espero que compartís ninguna duda.','Solo quiero personas que lo saben todo.'],'Quiero que and espero que frame desired actions, not facts already established.'),
scene('Una noticia de Elena','Elena consigue una nueva oportunidad de trabajo. Clara le escribe que se alegra de la noticia y espera que tenga tiempo para descansar antes de empezar. Elena responde que está contenta y algo nerviosa. Todavía debe conocer al equipo y entender cómo se reparten las tareas. Clara no asegura que todo será fácil. Dice que es importante que pregunte cuando una instrucción no esté clara. Elena agradece una reacción que combina alegría y apoyo práctico. También explica qué necesita ahora: no quiere consejos sobre cada decisión, sino hablar de cómo organizar la primera semana. Clara escucha y cambia su propuesta. La conversación muestra que expresar una emoción por otra persona puede abrir espacio para escuchar, no solo para celebrar.',[['se reparten','are shared out'],['esté clara','be clear']],['¿Cómo se siente Elena?','Contenta y algo nerviosa.','Totalmente segura de todo.','Indiferente.'],['¿Qué necesita ahora?','Hablar de la primera semana.','To discuss the first week.'],['¿Qué hace Clara tras escuchar?','Adapta su apoyo.','Impone más consejos.','Promete que nada será difícil.'],['¿Qué combina su reacción?','Alegría y apoyo práctico.','Happiness and practical support.'],['¿Qué frase expresa una reacción adecuada?','Me alegra que tengas esta oportunidad.','Me alegra que tienes esto necesariamente perfecto.','Todo será fácil, no preguntes.'],'Emotion and practical support can coexist without guarantees.'),
scene('Escuchar antes de votar','El grupo de vecinos debe elegir una actividad para el mes siguiente. Luis quiere una excursión y Ana prefiere un taller. Algunas personas no conocen el coste ni el tiempo necesario. Elena propone escuchar las dos opciones antes de votar. «Es importante que todos tengamos la misma información», explica. Luis presenta el precio y la duración. Ana describe el espacio y los materiales. Después aparecen preguntas que ninguno esperaba. No cambian cada propuesta para gustar a todos; aclaran lo necesario para comparar. Al final el grupo decide empezar con el taller y preparar la excursión más adelante. Luis sigue prefiriendo salir, pero reconoce que la decisión tuvo un proceso más justo. Su deseo no desaparece, aunque acepta el resultado.',[['votar','vote'],['más justo','fairer']],['¿Qué pide Elena antes de votar?','La misma información para todos.','Que gane su opción sin escuchar.','Eliminar las preguntas.'],['¿Por qué presentan coste y duración?','Para comparar con datos.','To compare using information.'],['¿Qué distingue Luis al final?','Su preferencia del resultado del grupo.','Su deseo de una orden.','La votación de una excursión pasada.'],['¿Qué valora del proceso?','Fue más justo.','It was fairer.'],['¿Qué frase apoya la comparación?','Es importante que todos tengamos la misma información.','Es importante que solo yo decida.','No quiero que nadie pregunte.'],'Necessity language can support a fair process rather than a predetermined answer.'),
scene('Un mensaje antes del viaje','Ana escribe a su hermana antes de una visita. Quiere que llegue sin preocuparse por organizar cada detalle. Le dice que espera que tenga un viaje tranquilo y que le alegra que puedan pasar el fin de semana juntas. También pide que envíe la hora de llegada cuando la conozca. Su hermana responde que prefiere decidir algunas actividades después de descansar. Ana acepta y cambia un plan demasiado lleno. No confunde desear una visita agradable con controlar lo que hará la otra persona. Deja una comida confirmada y el resto abierto. El mensaje final incluye afecto, una petición necesaria y libertad para ajustar el fin de semana. Es más útil que una lista de obligaciones disfrazada de bienvenida.',[['afecto','affection'],['disfrazada de','disguised as']],['¿Qué cambia Ana?','Reduce un plan demasiado lleno.','Cancela la visita.','Quita la comida confirmada.'],['¿Por qué pide la hora de llegada?','Para organizar la recepción.','To organise the arrival.'],['¿Qué distingue la bienvenida final?','Afecto, necesidad práctica y flexibilidad.','Solo obligaciones.','Una garantía de buen tiempo.'],['¿Qué prefiere su hermana?','Decidir después de descansar.','To decide after resting.'],['¿Qué deseo es adecuado?','Espero que tengas un viaje tranquilo.','Espero que tienes que hacer todo mi plan.','No quiero escuchar tus preferencias.'],'Present subjunctive expresses the wished-for experience without certifying the outcome.')],[audio('Quiero que vengáis con preguntas. No hace falta preparar una propuesta perfecta. Es importante que todos escuchemos antes de decidir.','¿Qué espera la persona del grupo?','Preguntas y escucha, no perfección.',['Una decisión antes de escuchar.','Silencio sin dudas.'],'The message explicitly removes a perfection requirement.'),audio_text('Me alegra que tengas esta oportunidad. Espero que puedas descansar antes de empezar. Si alguna instrucción no está clara, pregunta.','¿Qué espera antes de empezar?','Que pueda descansar.',['That they can rest.','Descansar'],'The hoped-for action is rest.')],prod('wishes',['Expresa: quieres que tu amigo venga.','Use a wish involving another subject.','Quiero que vengas.','Hablas a vosotros: espero que tenéis tiempo. Corrige la forma.','Use present subjunctive after espero que.','Espero que tengáis tiempo.'],[('Invita a tus amigos y expresa qué esperas de la reunión.','Invite friends and explain your hopes.','Quiero que vengáis a la reunión. Espero que compartáis ideas y dudas. Es importante que escuchemos a todos.'),('Escribe una reacción a una buena noticia e incluye un deseo y una pregunta.','React to good news with a wish and a question.','Me alegra que tengas una nueva oportunidad. Espero que puedas descansar antes de empezar. ¿Qué necesitas para organizar la primera semana?'),('Da la bienvenida a una visita: afecto, petición práctica y flexibilidad.','Welcome a visitor with affection, a practical request and flexibility.','Me alegra que podamos pasar el fin de semana juntos. Espero que tengas un buen viaje. Quiero que me envíes la hora de llegada cuando la sepas; después podemos decidir los planes con calma.')],[('Expresa un deseo o reacción',['espero que','quiero que','me alegra que']),('Añade una necesidad o petición',['es importante que','envíes','pregunta'])])))
b12.append(unit('Making your case','Sustain an opinion with experience, a response to another view and a solution','B1 synthesis; examples, reasons, polite response, proposals and limited subjunctive',[
core('Entiendo tu punto de vista, pero creo que hay otra opción.','I understand your viewpoint, but I think there is another option.','Entiendo',['Entiendes','Entenderé ayer'],'Acknowledging a view does not require agreeing with its conclusion.','Luis: «Es demasiado caro».','Entiendo tu punto; podemos comparar otra opción.',['Tu opinión no merece respuesta.','No existe ningún precio.'],'Reconoce la preocupación por el tiempo y propone comparar horarios.','Entiendo tu preocupación, pero creo que podemos comparar los horarios.'),
core('Por ejemplo, el año pasado organizamos una actividad parecida.','For example, last year we organised a similar activity.','organizamos',['organizar','organizaremos'],'A relevant example supports a claim but does not guarantee the same outcome.','Ana: «¿En qué experiencia te basas?»','El año pasado organizamos una actividad parecida.',['Siempre tengo razón sin ejemplos.','No ocurrió nada.'],'Apoya tu propuesta con una actividad que preparaste el mes pasado.','Por ejemplo, el mes pasado preparé una actividad parecida.'),
core('Propongo que probemos una sesión antes de decidir.','I propose that we try one session before deciding.','probemos',['probamos','probaremos'],'Propongo que introduces a proposed action; present subjunctive probemos suits nosotros.','Elena: «¿Cómo podemos comprobar si funciona?»','Podemos hacer una sesión de prueba.',['Decidir sin ninguna información.','Nunca escuchar a nadie.'],'Propón hablar con los participantes antes de repetir la actividad.','Propongo que hablemos con los participantes antes de repetirla.')],[
scene('Un taller para empezar','Diego propone un taller de cocina para vecinos. Luis teme que cueste demasiado y que pocas personas participen. Diego escucha la preocupación y evita responder solo que será divertido. Cuenta que el año pasado organizó una cena pequeña y varias personas pidieron aprender la receta. Esa experiencia apoya la idea, pero no prueba que todos asistirán. Ana propone una sesión corta con inscripción previa. Así pueden conocer el interés antes de comprar muchos materiales. Luis acepta la prueba porque reduce un riesgo concreto. El grupo acuerda revisar los comentarios después. La conversación termina con una decisión limitada y comprobable, no con una promesa de éxito. Diego mantiene su propuesta, pero la mejora al responder a una objeción real.',[['inscripción previa','advance registration'],['una objeción','an objection']],['¿Cómo responden al riesgo de poca asistencia?','Inscripción previa y una prueba pequeña.','Compra ilimitada.','Promesa de éxito.'],['¿Qué experiencia apoya la idea?','Una cena donde pidieron aprender la receta.','A dinner where people asked to learn the recipe.'],['¿Qué no demuestra esa experiencia?','Que todos asistirán al taller.','Que existe interés de algunas personas.','Que hubo una cena.'],['¿Por qué Luis acepta?','La prueba reduce el riesgo.','The trial reduces risk.'],['¿Qué propuesta encaja?','Probemos una sesión y revisemos los comentarios.','Ya sabemos que todos vendrán.','No escucharemos ninguna preocupación.'],'An example supports a proposal; a bounded trial tests it.'),
scene('La biblioteca por la tarde','Clara propone ampliar un horario de biblioteca. Ana apoya la idea porque muchas personas trabajan por la mañana. Marta pregunta por el coste y por el personal necesario. Clara no trata la pregunta como oposición automática. Presenta un ejemplo de otro centro que abre una tarde más, pero reconoce que las condiciones no son idénticas. Propone probar un día durante un mes y contar cuántas personas lo usan. Marta pide que también pregunten qué horario prefieren los usuarios. El grupo incorpora esa sugerencia. La propuesta final incluye una razón, un ejemplo, un límite y una forma de evaluar. Nadie afirma que una experiencia ajena garantice el resultado. Buscar información forma parte de hacer el caso más sólido.',[['ampliar','extend'],['los usuarios','users']],['¿Qué añade Marta?','Preguntar por las preferencias de usuarios.','Cerrar toda la biblioteca.','Ignorar el coste.'],['¿Por qué quieren abrir por la tarde?','Muchos trabajan por la mañana.','Many work in the morning.'],['¿Qué permite la prueba de un mes?','Evaluar el uso antes de decidir más.','Garantizar todos los resultados.','Copiar otro centro exactamente.'],['¿Cómo entiende Clara las preguntas?','Como ayuda para mejorar la propuesta.','As help to improve the proposal.'],['¿Qué respuesta es razonada?','Podemos probar un día y comprobar la demanda.','Si otro centro lo hace, funcionará seguro.','Las preguntas son ataques.'],'A stronger argument acknowledges differences and proposes evidence gathering.'),
scene('Menos ruido, más opciones','Elena vive sobre un local donde hay música algunas noches. Quiere pedir un cambio, pero no desea que desaparezca toda actividad del barrio. Luis le aconseja describir horarios y efectos concretos. Elena explica que después de cierta hora no puede dormir. El encargado responde que algunos clientes trabajan tarde y solo pueden ir por la noche. Elena reconoce esa necesidad, pero pide bajar el volumen y cerrar la puerta. Propone revisar el resultado durante dos semanas. El encargado acepta probarlo. El acuerdo no elimina intereses diferentes. Busca una forma de reducir el efecto más molesto y comprobar si basta. Elena aprende que defender su necesidad con precisión puede abrir más opciones que exigir una solución total sin escuchar.',[['el encargado','manager'],['el volumen','volume']],['¿Qué pide Elena concretamente?','Menos volumen y la puerta cerrada.','Eliminar toda actividad.','Música más fuerte.'],['¿Por qué describe horarios?','Para mostrar cuándo le afecta.','To show when it affects her.'],['¿Qué mantiene el acuerdo?','Intereses distintos con una prueba de ajuste.','La misma situación sin cambios.','Una victoria total de una persona.'],['¿Qué reconoce Elena?','La necesidad de algunos clientes.','Some customers’ needs.'],['¿Qué mensaje defiende sin exagerar?','Entiendo vuestro horario; después de esta hora el ruido me impide dormir.','Nunca nadie debe salir de noche.','No hay ningún efecto concreto.'],'Specific effects and limited changes make negotiation more useful.'),
scene('La propuesta que evolucionó','Ana quería organizar una salida de todo un día. Marta explicó que varias personas solo podían venir por la mañana y Diego preguntó por el coste. Ana recordó una excursión anterior, pero esta vez el grupo tenía otras condiciones. En lugar de repetir su primer plan, propuso un paseo corto con una comida opcional. Quienes necesitaban volver podían hacerlo sin perder toda la actividad. Luis sugirió enviar dos horarios claros y Ana aceptó. Al final el mensaje no se parecía exactamente al borrador inicial, aunque mantenía su objetivo: pasar tiempo juntos. La discusión no fue un fracaso de la propuesta. Fue la manera de convertir una idea personal en un plan compartido. Todos sabían qué estaba acordado y qué seguía siendo opcional.',[['el borrador','draft'],['opcional','optional']],['¿Qué conserva el plan final?','El objetivo de pasar tiempo juntos.','La duración obligatoria de todo el día.','El primer borrador sin cambios.'],['¿Por qué acortaron la salida?','Algunos solo tenían la mañana.','Some only had the morning.'],['¿Qué muestra el cambio del borrador?','La propuesta incorporó otras necesidades.','La conversación no sirvió.','Ana dejó de querer participar.'],['¿Cómo se entiende la discusión?','Como construcción de un plan compartido.','As building a shared plan.'],['¿Qué resumen encaja?','Cambiamos detalles para conservar el objetivo común.','Nadie cedió ni escuchó.','Todos tienen las mismas condiciones.'],'A communicative success can be a revised shared plan rather than an unchanged personal idea.')],[audio('Entiendo que os preocupa el coste. El año pasado hicimos una actividad pequeña y hubo interés, pero no sabemos cuántas personas vendrán. Propongo una sesión con inscripción previa.','¿Qué papel tiene el ejemplo pasado?','Apoya la idea sin garantizar asistencia.',['Demuestra que todos vendrán.','No tiene relación con la propuesta.'],'The speaker states the limit explicitly.'),audio_text('Al principio quería una salida de todo el día. Ahora propongo un paseo corto y una comida opcional porque algunas personas solo tienen la mañana.','¿Qué parte es opcional?','La comida.',['The meal.'],'The revised plan separates shared and optional parts.')],prod('case',['Escribe «I understand your point of view».','Translate the acknowledgement.','Entiendo tu punto de vista.','Propón que nosotros probamos una sesión. Corrige tras propongo que.','Use subjunctive for the proposal.','Propongo que probemos una sesión.'],[('Defiende una idea con un ejemplo y reconoce una limitación.','Defend an idea with an example and limitation.','Creo que un taller puede funcionar. El año pasado varias personas pidieron aprender la receta. Sin embargo, esa experiencia no garantiza la asistencia.'),('Responde a una opinión distinta y construye una solución compartida.','Respond to disagreement and build a shared solution.','Entiendo la preocupación por el coste. También quiero que todos puedan participar. Propongo una sesión pequeña y revisar los comentarios antes de repetirla.'),('Escribe una propuesta: objetivo, motivo, ejemplo, objeción y siguiente paso.','Write a reasoned proposal with a response to an objection.','Quiero organizar un taller para compartir recetas. Hay interés porque el año pasado varias personas lo pidieron. Entiendo que el coste preocupa, así que propongo una sesión pequeña con inscripción previa. Después podemos evaluar el resultado.')],[('Sostén una posición',['creo','propongo','quiero']),('Añade apoyo y límite',['porque','por ejemplo','sin embargo','entiendo'])])))
save('B1.2',b12)
b21=[]
b21.append(unit('Stories with detail','Relate a detailed account while distinguishing chronology, background and viewpoint','Past integration; limited pluperfect for a prior event; narrator perspective',[
core('Cuando llegué, la reunión ya había empezado.','When I arrived, the meeting had already started.','había empezado',['empezará','ha empezar'],'Había + participle places the start before another past event. It is not simply a longer way to say empezó.','Elena: «¿Llegaste antes del principio?»','No; la reunión ya había empezado.',['Sí, empezará ayer.','La reunión nunca existe.'],'Llegaste al café después de que Luis saliera. Usa ya había.','Cuando llegué al café, Luis ya había salido.'),
core('Mientras Ana explicaba el problema, Luis buscó la confirmación.','While Ana was explaining the problem, Luis looked for the confirmation.','explicaba',['explicará','explicar'],'An ongoing explanation frames a completed response; viewpoint determines how an event is presented.','Ana: «¿Qué hiciste mientras hablaba?»','Busqué la confirmación.',['Buscaré ayer.','No estaba allí mañana.'],'Mientras Marta hablaba, tú anotaste los detalles.','Mientras Marta hablaba, anoté los detalles.'),
core('Según Clara, el cambio fue necesario; Luis lo vivió de otra manera.','According to Clara, the change was necessary; Luis experienced it differently.','Según',['Por todos','Desde'],'Según attributes a viewpoint rather than presenting it as the narrator’s fact.','Luis: «¿Todos interpretamos igual lo ocurrido?»','No; Clara lo vio como una solución y tú como una dificultad.',['Todos tenemos necesariamente la misma reacción.','No ocurrió ningún cambio.'],'Ana vio el retraso como un problema; Diego aprovechó para descansar.','Ana vio el retraso como un problema; Diego lo aprovechó para descansar.')],[
scene('La puerta del centro','Elena llegó al centro cultural convencida de que la reunión empezaba a las seis. Cuando entró, el grupo ya había repartido parte de las tareas. La invitación original decía seis, pero un mensaje posterior adelantó la hora. Elena no lo había visto. Luis, que recibió el aviso, pensó que ella decidió llegar tarde. Al explicar qué información tenía cada uno, la situación cambió. Clara mostró los dos mensajes y propuso usar una única confirmación final. Elena reconoció que podría haber comprobado el grupo antes de salir. Luis admitió que interpretó la llegada sin conocer el motivo. Después revisaron las tareas para incluirla. El relato no busca una persona totalmente culpable: muestra cómo información desigual produjo dos interpretaciones. Al final Elena participó en la preparación, pero el grupo dejó pendiente mejorar el sistema de avisos. Resolver la reunión concreta no significaba resolver para siempre la comunicación.',[['adelantó','brought forward'],['desigual','unequal'],['culpable','at fault']],['¿Qué estaba hecho cuando llegó Elena?','Parte del reparto de tareas.','La exposición completa.','La nueva confirmación única.'],['¿Por qué llegó con otra hora?','No vio el mensaje posterior.','She did not see the later message.'],['¿Qué cambia al comparar los mensajes?','Entienden que tenían información distinta.','Prueban que nadie llegó.','La invitación nunca existió.'],['¿Qué admite Luis?','Interpretó sin conocer el motivo.','He interpreted without knowing the reason.'],['¿Qué resumen distingue solución y límite?','La incluyeron, pero todavía deben mejorar los avisos.','Todo quedó resuelto para siempre.','Elena no participó.'],'Prior events and differing information explain the misunderstanding without erasing responsibility.'),
scene('El relato del encargado','Diego contó que el café se llenó de repente durante una tarde de lluvia. Antes había preparado pocas mesas porque esperaba una jornada tranquila. Cuando llegaron varios grupos, Ana ayudó a organizar la entrada. Diego recordaba sobre todo la rapidez con que tuvieron que actuar. Ana destacó que algunos clientes esperaron con paciencia y otros se quejaron. Los dos relatos coincidían en los hechos principales, pero no en el centro de atención. Elena les preguntó qué ocurrió antes de la llegada y qué decisiones tomaron después. Así distinguieron una previsión que resultó insuficiente de una respuesta improvisada. No podían afirmar que todos los clientes estaban contentos: no hablaron con todos. Sin embargo, sabían que ninguna persona quedó sin información sobre la espera. Al final prepararon un procedimiento sencillo para días parecidos, basado en lo que pudieron observar y no en una versión perfecta de la tarde.',[['una previsión','a forecast or expectation'],['improvisada','improvised'],['el procedimiento','procedure']],['¿Qué había previsto Diego?','Una tarde tranquila con pocas mesas.','Una fiesta anunciada.','Una jornada sin clientes para siempre.'],['¿Por qué cambiaron de organización?','Llegaron varios grupos por la lluvia.','Several groups arrived because of the rain.'],['¿Qué afirmación no pueden sostener?','Que todos estaban contentos.','Que explicaron la espera.','Que había lluvia.'],['¿Qué destacó Ana?','Las reacciones de los clientes.','Customers’ reactions.'],['¿Qué versión es cauta?','Informamos sobre la espera, aunque no conocemos la opinión de todos.','Todos disfrutaron, aunque no preguntamos.','No hubo necesidad de actuar.'],'A detailed account distinguishes observation, interpretation and unverified generalisation.'),
scene('Antes de la llamada','Clara llamó a Marta para explicar por qué canceló una visita. El día anterior había confirmado el horario y comprado el billete. Por la mañana recibió una llamada de su hermana, que necesitaba ayuda con una mudanza inesperada. Clara primero buscó una forma de mantener ambas cosas. Cuando vio que no podía, avisó a Marta y propuso otra fecha. Marta estaba decepcionada porque había preparado una comida especial. No pensó que la necesidad de Clara fuera falsa, pero le costó aceptar el cambio. Durante la conversación distinguieron dos planos: el motivo de cancelar y el efecto sobre la otra persona. Clara pidió disculpas sin prometer que nunca volvería a cambiar un plan. Marta explicó su reacción sin exigir que Clara ignorara a su hermana. La visita quedó para otro día y las dos entendieron mejor qué hizo difícil aquella llamada.',[['la mudanza','house move'],['decepcionada','disappointed'],['el efecto','effect']],['¿Qué ocurrió antes de la necesidad inesperada?','Clara confirmó y compró el billete.','Marta canceló todo.','La hermana terminó la mudanza.'],['¿Por qué cambió la visita?','Su hermana necesitaba ayuda.','Her sister needed help.'],['¿Qué dos aspectos separan?','Motivo y efecto de la cancelación.','La comida y el billete como objetos idénticos.','La verdad y una mentira demostrada.'],['¿Qué explica Marta?','Su decepción por el cambio.','Her disappointment about the change.'],['¿Qué respuesta reconoce ambos planos?','Entiendo la necesidad; también quiero explicar cómo me afectó.','Tu motivo elimina cualquier efecto sobre mí.','Mi reacción prueba que tu motivo es falso.'],'An understandable reason does not erase its impact on another person.'),
scene('La historia que faltaba','Luis vio un vídeo corto de una discusión en una estación. Parecía mostrar a una empleada negándose a ayudar a un viajero. Una noticia más larga explicaba que antes se había ofrecido otra conexión y que el viajero no aceptó el horario. Esa información no demostraba que la empleada actuara perfectamente, pero cambiaba la interpretación de su respuesta. Ana señaló que el vídeo empezaba después de la propuesta y no mostraba el intercambio completo. Los dos compararon lo visible con lo que solo afirmaba la noticia. No decidieron quién tenía toda la razón. Prepararon un resumen que indicaba qué se veía y qué se decía sobre el contexto anterior. Luis entendió que una narración breve puede ser verdadera en sus imágenes y aun así incompleta. La conclusión prudente fue pedir más contexto antes de compartir una acusación.',[['negándose','refusing'],['una acusación','an accusation'],['incompleta','incomplete']],['¿Qué omitía el vídeo corto?','Una propuesta anterior de conexión.','La existencia de la estación.','Todas las imágenes.'],['¿Por qué cambia la interpretación?','Aparece contexto anterior.','Earlier context becomes available.'],['¿Qué no demuestra la noticia larga?','Que la empleada actuara perfectamente.','Que hubo otra propuesta según la noticia.','Que el vídeo es breve.'],['¿Qué aprende Luis?','Una imagen verdadera puede ser incompleta.','A true image can be incomplete.'],['¿Qué resumen atribuye correctamente?','El vídeo muestra una respuesta; la noticia añade una oferta previa.','Las imágenes prueban toda la historia.','Ya sabemos quién tiene toda la razón.'],'Source attribution and chronology guard against an overconfident interpretation.')],[audio('Cuando llegué, el grupo ya había elegido una tarea. Yo no había visto el cambio de hora. Según Luis, llegué tarde por descuido; después entendió que teníamos mensajes distintos.','¿Qué modifica la interpretación de Luis?','Conocer que recibieron información distinta.',['Cambiar el nombre del grupo.','Terminar la tarea.'],'A prior information gap explains the arrival.'),audio_text('El vídeo empieza después de una propuesta. La noticia dice que antes se había ofrecido otra conexión. No sabemos si la respuesta fue adecuada, pero falta contexto.','¿Qué falta en el vídeo?','La propuesta anterior.',['The earlier proposal.'],'The speaker distinguishes visible material from reported context.')],prod('detailed narration',['Escribe «When I arrived, Luis had already left».','Translate the prior-past relationship.','Cuando llegué, Luis ya había salido.','Une: Ana explicaba; Luis buscó el correo. Usa mientras.','Frame the action with simultaneous background.','Mientras Ana explicaba, Luis buscó el correo.'],[('Cuenta un malentendido distinguiendo lo anterior y lo que cada persona sabía.','Narrate a misunderstanding with chronology and perspectives.','La reunión ya había empezado cuando llegué. Yo no había visto el cambio de hora. Luis pensó que no me importaba, pero después comparamos los mensajes.'),('Relata una experiencia desde dos perspectivas y reconoce qué no sabes.','Narrate from two viewpoints while acknowledging limits.','Diego recuerda la tarde como un problema de organización. Ana destaca la paciencia de algunos clientes. Sabemos que explicamos la espera, pero no conocemos la opinión de todos.'),('Escribe un relato detallado con antecedente, hecho, reacción y reflexión.','Write a detailed account with a prior event, reaction and reflection.','Habíamos confirmado la visita cuando surgió otra necesidad. Primero intenté mantener ambos planes, pero no pude. Mi amiga estaba decepcionada y hablamos del motivo y del efecto. Al final acordamos otra fecha y entendimos mejor la situación.')],[('Ordena antecedentes y hechos',['ya había','habíamos','cuando']),('Distingue perspectivas o límites',['según','pero','no sabemos'])])))
b21.append(unit('Causes and consequences','Explain a chain of causes and consequences without overstating what the evidence proves','Debido a, a causa de, por lo tanto, como resultado; cause versus correlation',[
core('El tren se retrasó debido a una avería.','The train was delayed because of a breakdown.','debido a',['para','desde'],'Debido a introduces the stated cause, here a noun phrase. Do not infer an unstated cause merely from a delay.','Ana: «¿Por qué llegó tarde?»','A causa de una avería.',['Para una avería mañana.','No conocemos ninguna causa aunque está anunciada.'],'La actividad cambió por la lluvia. Explica la causa con debido a.','La actividad cambió debido a la lluvia.'),
core('No había suficiente espacio; por lo tanto, dividimos el grupo.','There was not enough space; therefore, we split the group.','por lo tanto',['a pesar de que','antes de que'],'Por lo tanto links a consequence to the reason just stated.','Luis: «¿Qué efecto tuvo la falta de espacio?»','Dividimos el grupo.',['La sala se hizo más grande automáticamente.','Nadie llegó nunca.'],'Faltaban materiales. Como resultado, retrasasteis el taller.','Faltaban materiales; como resultado, retrasamos el taller.'),
core('La inscripción aumentó después del anuncio, pero no sabemos si fue la única causa.','Registration increased after the announcement, but we do not know if it was the only cause.','sabemos',['sabe','saber'],'After describes time; it does not by itself prove a single cause.','Elena: «¿El anuncio explica todo el aumento?»','Puede haber ayudado, pero necesitamos más información.',['Sí, el orden temporal lo prueba todo.','No pudo influir en absoluto sin datos.'],'Las visitas aumentaron tras cambiar el horario. Reconoce el límite causal.','Las visitas aumentaron, pero no sabemos si el horario fue la única causa.')],[
scene('Más gente en la biblioteca','Clara observó que la biblioteca recibió más visitas después de ampliar el horario. En una reunión alguien dijo que el cambio explicaba todo el aumento. Clara mostró que ese mes también hubo una exposición y empezó un curso cercano. El horario probablemente ayudó, pero no podía separar su efecto con los datos disponibles. Propuso preguntar a los usuarios por qué venían y comparar semanas sin actividades especiales. Luis pensó que tanta cautela debilitaba la propuesta. Clara explicó que no quería negar la mejora, sino entender qué conviene mantener. Como resultado, el grupo decidió conservar el horario durante otro mes y recoger información más precisa. La conclusión no fue «no sabemos nada». Sabían que había más visitas y varias causas posibles. Lo que no sabían era cuánto aportó cada una. Esa diferencia permitió actuar sin convertir una observación positiva en una explicación absoluta.',[['debilitaba','weakened'],['recoger información','collect information'],['disponibles','available']],['¿Qué dato está confirmado?','Aumentaron las visitas.','El horario fue la única causa.','No hubo exposición.'],['¿Por qué Clara pide más información?','Hubo varios cambios al mismo tiempo.','Several changes happened at once.'],['¿Qué decisión permite la cautela?','Mantener el horario y evaluar mejor.','Negar cualquier mejora.','Cerrar sin comparar.'],['¿Qué distingue Clara?','La observación de su explicación causal.','The observation from its causal explanation.'],['¿Qué conclusión es respaldada?','Hay más visitas y varias causas posibles.','El horario explica exactamente todo.','Los datos no sirven nunca.'],'Temporal sequence and a measured increase do not prove a single cause.'),
scene('El retraso en cadena','Diego debía llegar a un taller en otra ciudad. Una avería retrasó su primer tren y perdió la conexión. Debido a ese cambio llegó una hora tarde. El centro empezó la actividad sin él y adaptó el orden: Ana presentó los materiales mientras Luis atendía las preguntas. Diego avisó en cuanto tuvo una nueva hora de llegada. El retraso produjo dificultades, pero la información permitió reducirlas. Al terminar, el grupo distinguió la causa inicial de las consecuencias que podía controlar. No podían reparar el tren, pero sí reorganizar la sesión y avisar a quienes esperaban. Diego preparó después un mensaje con las fechas y el justificante del retraso. Explicar la cadena no significaba excusarse de todo. También reconoció qué hizo para ayudar y qué habría sido útil preparar antes del viaje, como dejar los materiales accesibles al grupo.',[['la avería','breakdown'],['el justificante','supporting document'],['accesibles','accessible']],['¿Cuál fue la causa inicial?','Una avería del primer tren.','La pregunta de un participante.','La falta de taller.'],['¿Por qué pudo adaptarse el centro?','Diego avisó y el grupo tenía funciones.','Diego informed them and the group had roles.'],['¿Qué consecuencia podían controlar?','El orden de la sesión.','La avería del tren.','La existencia de la conexión.'],['¿Qué reconoce Diego al reflexionar?','Podía dejar los materiales disponibles antes.','He could make materials available beforehand.'],['¿Qué explicación muestra la cadena?','La avería causó el retraso; por eso perdí la conexión y avisamos al centro.','Todo ocurrió por una sola pregunta.','No hubo ningún efecto.'],'A cause chain distinguishes an initial event from modifiable consequences.'),
scene('El precio y la asistencia','Marta bajó el precio de una actividad y esperaba que asistiera más gente. La siguiente sesión tuvo pocos participantes. Algunos concluyeron que el precio no importa. Ana señaló que ese día llovió mucho y coincidió con otra actividad del barrio. Marta también descubrió que el anuncio llegó tarde a varias personas. No usaron esos factores para afirmar lo contrario con la misma seguridad. Prepararon una nueva sesión con el mismo precio, una fecha distinta y más tiempo para avisar. Sabían que una prueba pequeña no aislaría todos los efectos, pero podía dar información útil. La conversación evitó dos errores: declarar que el precio siempre decide la asistencia o que nunca influye. En ambos casos se habría convertido un resultado limitado en una regla. Marta decidió describir lo observado y explicar qué quería comprobar después.',[['aislar','isolate'],['coincidió','coincided'],['factores','factors']],['¿Qué ocurrió tras bajar el precio?','La siguiente sesión tuvo poca asistencia.','Todas las sesiones se llenaron.','No hubo sesión.'],['¿Por qué no basta para negar el efecto del precio?','Hubo otros factores ese día.','Other factors were present that day.'],['¿Qué evitan con la nueva prueba?','Una conclusión absoluta a partir de un caso.','Recoger información.','Cambiar de fecha.'],['¿Qué quiere Marta comprobar?','Qué condiciones ayudan a participar.','Which conditions help participation.'],['¿Qué resumen es prudente?','Este resultado no demuestra que el precio nunca influya.','El precio nunca importa.','La lluvia explica todo con certeza.'],'A disappointing result supports questions, not an unbounded causal rule.'),
scene('Una puerta, varios efectos','El café de Diego tenía una puerta difícil de abrir. Una clienta explicó que evitaba entrar porque llevaba un carrito. Diego pensaba que el problema solo causaba una pequeña molestia. Después escuchó a otras personas y vio que también afectaba a quienes llevaban bolsas o tenían poca fuerza. Arregló la puerta y observó menos dificultades en la entrada. No midió si aumentaron todas las ventas por ese cambio. En su mensaje al equipo explicó primero el problema, después la reparación y finalmente el efecto observado. Clara le ayudó a evitar una afirmación demasiado grande. Podían decir que entrar era más fácil para varias personas; no que una puerta nueva resolvía todo el negocio. La causa concreta y el resultado limitado bastaban para justificar la mejora. Reconocer el límite no quitaba valor a una acción útil.',[['el carrito','pushchair or trolley'],['justificar','justify'],['la reparación','repair']],['¿Qué efecto observó Diego?','Menos dificultades para entrar.','Todas las ventas duplicadas.','Ninguna diferencia.'],['¿Por qué amplió su interpretación del problema?','Escuchó a más personas.','He heard from more people.'],['¿Qué afirmación supera la evidencia?','Que la puerta resolvió todo el negocio.','Que entrar resultó más fácil.','Que hubo una reparación.'],['¿Cómo valora Clara un resultado limitado?','Puede justificar una mejora útil.','It can justify a useful improvement.'],['¿Qué mensaje describe causa y resultado?','La puerta dificultaba entrar; tras arreglarla, observamos menos problemas.','La puerta garantiza todas las ventas.','Nunca había ninguna dificultad.'],'A bounded causal explanation can be valuable without claiming every benefit.')],[audio('Las visitas aumentaron después del horario nuevo, pero también hubo una exposición. No sabemos cuánto influyó cada factor. Mantendremos el horario y preguntaremos a los usuarios.','¿Qué distingue la persona?','Aumento observado y causa todavía no aislada.',['Ausencia total de visitas.','Una causa única demostrada.'],'The clip distinguishes observation from explanation.'),audio_text('Una avería retrasó el tren. Como resultado perdimos la conexión. Avisamos al centro y cambiaron el orden de la sesión.','¿Qué cambió el centro?','El orden de la sesión.',['The order of the session.'],'The centre controlled the session, not the train.')],prod('causes',['Explica con debido a: el tren se retrasó; una avería.','State the specified cause.','El tren se retrasó debido a una avería.','Une: faltaba espacio; dividimos el grupo. Usa por lo tanto.','Link cause and consequence.','Faltaba espacio; por lo tanto, dividimos el grupo.'],[('Explica un problema, dos consecuencias y una respuesta posible.','Explain a cause chain and response.','Una avería retrasó el tren. Por eso perdimos la conexión y llegamos tarde. Avisamos al centro para cambiar el orden de la actividad.'),('Analiza una mejora sin atribuirle todos los efectos automáticamente.','Analyse a change with cautious causal reasoning.','Las visitas aumentaron tras ampliar el horario, pero también hubo una exposición. El horario puede haber ayudado. Necesitamos comparar más semanas antes de explicar todo el aumento.'),('Escribe un informe breve: hecho observado, causas posibles y siguiente comprobación.','Write a short account separating evidence, possible causes and next check.','La asistencia bajó en la última sesión. Llovió y el anuncio llegó tarde, así que hay varias causas posibles. No sabemos si el precio influyó. Proponemos otra fecha y avisar antes para comparar los resultados.')],[('Relaciona causa y consecuencia',['debido a','por eso','como resultado']),('Reconoce alcance o comprobación',['no sabemos','puede','comparar'])])))
b21.append(unit('Certainty, doubt and possibility','Separate what is known, believed and possible when explaining a situation','Probablemente/quizá; puede que; es posible que; no creo que + present subjunctive',[
core('No creo que tenga tiempo hoy.','I do not think he or she has time today.','tenga',['tiene','tener'],'No creo que expresses doubt and takes subjunctive here. Creo que tiene normally presents a belief with indicative.','Luis: «¿Estás seguro de que vendrá?»','No; puede que tenga otro compromiso.',['Sí, no sé nada pero es seguro.','Puede que tiene necesariamente.'],'No crees que Ana pueda venir hoy.','No creo que Ana pueda venir hoy.'),
core('Es posible que lleguemos más tarde.','It is possible that we arrive later.','lleguemos',['llegamos','llegar'],'Es posible que presents an uncertain possibility; -AR subjunctive nosotros uses -emos with spelling preserved.','Ana: «¿Cuál es la hora exacta?»','No la sé; probablemente llegaremos después de las seis.',['Sé exactamente que no sé.','Llegamos ayer mañana.'],'Es posible que vosotros necesitéis otro horario.','Es posible que necesitéis otro horario.'),
core('Probablemente han cambiado el horario, pero debo comprobarlo.','They have probably changed the schedule, but I must check it.','han cambiado',['han cambiar','son cambiado'],'Probablemente qualifies the claim; it does not turn it into confirmed evidence.','Clara: «¿Ya está confirmado?»','No; es una posibilidad y voy a comprobarla.',['Sí, probablemente significa certeza absoluta.','No hace falta comprobar nunca.'],'Quizá el mensaje sea antiguo; quieres comprobar la fecha.','Quizá el mensaje sea antiguo; voy a comprobar la fecha.')],[
scene('La sala sin luces','Ana llega al centro y encuentra las luces apagadas. Piensa que quizá estaba cancelada la reunión. Luis cree que quizá cambiaron de sala, pero no tiene una confirmación. Clara recuerda que el edificio cierra una entrada temprano y propone mirar la otra. Nadie afirma conocer la causa solo por ver oscuridad. Encuentran un aviso que indica el nuevo acceso y el horario de la sesión. La reunión sigue prevista. Ana distingue su primera impresión de la información confirmada. Luis reconoce que su hipótesis sobre la sala no era exactamente la solución. Las posibilidades ayudaron a pensar en próximos pasos, pero necesitaban una comprobación. Al contar lo ocurrido, Ana no dice «la reunión estaba cancelada». Explica que lo pensó al principio y después encontró información distinta. La diferencia evita transmitir a otros una conclusión que ya sabe que no era correcta.',[['el acceso','entrance'],['la hipótesis','hypothesis'],['prevista','scheduled']],['¿Qué confirma el aviso?','Otro acceso y la reunión prevista.','Una cancelación total.','Una sala desaparecida.'],['¿Por qué Ana pensó en cancelación?','Vio las luces apagadas.','She saw the lights off.'],['¿Qué papel tuvieron las hipótesis?','Guiaron la búsqueda, no probaron la causa.','Eran hechos confirmados.','Impedían comprobar.'],['¿Qué reconoce Luis?','Su idea no era exactamente la solución.','His idea was not exactly the solution.'],['¿Qué relato distingue duda y hecho?','Pensé que estaba cancelada; después vi el aviso del nuevo acceso.','Estaba cancelada aunque se celebró.','La oscuridad prueba cualquier hipótesis.'],'Mark initial beliefs and later verification separately.'),
scene('Un rumor sobre el horario','Diego oye que el curso cambiará de día. Una compañera lo leyó en un mensaje de otro grupo y dice que probablemente sea cierto. Diego necesita organizar sus turnos, pero no toma el rumor como un horario oficial. Pregunta al centro y recibe una respuesta: están considerando el cambio, sin decisión final. Diego informa al grupo con esa misma distinción. No escribe que el horario ya ha cambiado. Elena agradece que no transforme una posibilidad en una noticia segura. El centro promete avisar antes del viernes. Mientras tanto, Diego prepara dos opciones de trabajo. La incertidumbre no le obliga a quedarse sin hacer nada, pero tampoco justifica actuar como si la decisión estuviera tomada. El relato muestra cómo una comunicación cauta puede permitir planificación sin inventar una certeza.',[['el rumor','rumour'],['están considerando','are considering'],['tomada','made']],['¿Qué sabe oficialmente Diego?','Se considera un cambio sin decisión final.','El nuevo día está confirmado.','No habrá curso nunca.'],['¿Por qué necesita información?','Para organizar sus turnos.','To organise his work shifts.'],['¿Qué hace mientras espera?','Prepara dos opciones.','Difunde una fecha inventada.','Ignora toda planificación.'],['¿Qué valora Elena?','No presentar una posibilidad como certeza.','Not presenting possibility as certainty.'],['¿Qué mensaje es fiel?','Puede que cambie el día; el centro todavía no ha decidido.','El día ya cambió con seguridad.','Todo rumor es necesariamente falso.'],'Uncertainty can support conditional planning rather than misinformation.'),
scene('Una explicación que no basta','Marta ve que una amiga no responde desde la mañana. Piensa que puede estar enfadada por una conversación anterior. Ana propone otra posibilidad: quizá tenga un día ocupado. Ninguna conoce el motivo. Marta decide enviar una pregunta breve y no una acusación. Más tarde la amiga explica que perdió el móvil durante varias horas. Esa respuesta aclara el caso, pero no demuestra que todas las ausencias de respuesta tengan el mismo motivo. Marta aprende a elegir lenguaje proporcional a lo que sabe. Puede decir «me preocupó no saber de ti» sin afirmar «sé que estabas enfadada». Su emoción es real aunque su explicación fuera equivocada. Al separar ambas cosas, la conversación resulta más fácil y no obliga a la amiga a defenderse de una intención que nunca tuvo.',[['proporcional','proportionate'],['una acusación','an accusation'],['la ausencia','absence']],['¿Qué sabía Marta al principio?','Solo que no había respuesta.','Que había enfado confirmado.','Que el móvil estaba perdido.'],['¿Por qué envía una pregunta?','No conoce el motivo.','She does not know the reason.'],['¿Qué sigue siendo real aunque cambie la explicación?','Su preocupación.','La acusación de enfado.','Una regla universal.'],['¿Qué aprende sobre su lenguaje?','Debe corresponder a lo que sabe.','It should match what she knows.'],['¿Qué respuesta evita una certeza falsa?','Me preocupó no saber de ti; ¿qué pasó?','Sé que estabas enfadada porque no respondiste.','Nunca hay otros motivos.'],'Emotional truth is not proof of a specific explanation.'),
scene('La previsión del paseo','Clara prepara una salida y ve una previsión de lluvia. Dice que probablemente necesitarán una ruta más corta. Luis interpreta que la excursión está cancelada. Clara aclara que la lluvia es una posibilidad y que todavía pueden adaptar el recorrido. Es posible que algunos caminos no estén disponibles, así que van a consultar la información local antes de salir. No usarán una previsión general para asegurar el estado de cada camino. El grupo acuerda dos opciones y una hora para confirmar. Ana valora saber qué está decidido: la reunión del grupo. Lo pendiente es la ruta. La conversación mantiene una diferencia entre probabilidad, condición práctica y acuerdo. Al final nadie promete buen tiempo ni una cancelación inevitable. Tienen un plan para comprobar lo relevante y comunicar la decisión a tiempo.',[['la previsión','forecast'],['el recorrido','route'],['inevitable','inevitable']],['¿Qué está acordado?','La reunión del grupo.','La ruta exacta sin comprobar.','Buen tiempo garantizado.'],['¿Por qué consultan información local?','Para conocer el estado de los caminos.','To check path conditions.'],['¿Qué entendió mal Luis?','Una probabilidad como cancelación.','La hora de la reunión.','La existencia de dos opciones.'],['¿Qué valora Ana?','Distinguir lo decidido y lo pendiente.','Separating agreed and pending details.'],['¿Qué mensaje es proporcionado?','Puede que llueva; confirmaremos la ruta tras comprobar los caminos.','Lloverá seguro en cada camino.','La reunión está cancelada por una posibilidad.'],'Probabilities, verified conditions and agreements serve different roles.')],[audio('No creo que el curso haya cambiado todavía. El centro dice que está considerando otra fecha. Puede que la confirme el viernes; mientras tanto prepararé dos opciones.','¿Qué sabe con seguridad?','Se considera un cambio, no está confirmado.',['El viernes empieza otro curso seguro.','Nada se está considerando.'],'The source separates deliberation from decision.'),audio_text('Probablemente necesitemos una ruta más corta por la lluvia. La reunión sigue acordada. Confirmaremos el recorrido después de consultar la información local.','¿Qué sigue acordado?','La reunión.',['The meeting.'],'The pending choice concerns the route, not gathering.')],prod('certainty',['Corrige tras no creo que: ella tiene tiempo.','Use subjunctive for expressed doubt.','No creo que ella tenga tiempo.','Exprésalo como posibilidad: nosotros llegamos tarde.','Use es posible que.','Es posible que lleguemos tarde.'],[('Explica qué sabes, qué sospechas y cómo lo comprobarás.','Separate fact, possibility and verification.','Sé que las luces están apagadas. Puede que haya cambiado el acceso, pero no está confirmado. Voy a buscar el aviso antes de decir que se ha cancelado.'),('Cuenta una interpretación equivocada y cómo cambió.','Describe a mistaken interpretation and new evidence.','Pensé que mi amiga estaba enfadada porque no respondió. No conocía el motivo. Después explicó que perdió el móvil. Mi preocupación era real, pero la explicación no era correcta.'),('Escribe una actualización sobre un posible cambio sin transmitirlo como certeza.','Write a cautious update and practical next step.','El centro está considerando cambiar el horario, pero todavía no ha decidido. Es posible que tengamos otra fecha. Mientras tanto podemos preparar dos opciones y esperar la confirmación del viernes.')],[('Separa evidencia y duda',['sé','puede que','es posible','todavía']),('Indica una comprobación',['comprobar','confirmación','buscar'])])))
b21.append(unit('Giving and defending opinions','Defend a position with qualification, a counterpoint and relevant support','Polite disagreement; si bien, aunque, sin embargo; partial agreement; support scope',[
core('Estoy de acuerdo en parte, pero la propuesta necesita un límite.','I partly agree, but the proposal needs a limit.','en parte',['por todas partes','desde parte'],'Partial agreement can accept one aspect without endorsing the entire proposal.','Luis: «¿Entonces rechazas toda la idea?»','No; acepto el objetivo, pero cambiaría el horario.',['Sí, todo acuerdo es rechazo.','Ninguna parte importa.'],'Aceptas la idea de una salida, pero prefieres una ruta corta.','Estoy de acuerdo con la salida, pero prefiero una ruta corta.'),
core('Si bien ahorra tiempo, también puede excluir a algunas personas.','Although it saves time, it can also exclude some people.','Si bien',['Por lo tanto','Debido a'],'Si bien introduces a concession; the following point qualifies the advantage.','Ana: «¿La inscripción solo por internet es suficiente?»','Es cómoda, pero algunas personas necesitan otra opción.',['Todas las personas tienen las mismas herramientas.','La comodidad elimina todos los límites.'],'La reunión en línea facilita participar, pero no todos tienen conexión.','Si bien facilita participar, no todos tienen una buena conexión.'),
core('Mi experiencia apoya la idea, pero no basta para generalizar.','My experience supports the idea, but is not enough to generalise.','basta',['basto','bastan'],'One experience can be relevant evidence with limited reach.','Elena: «¿Un caso demuestra que siempre funciona?»','No; necesitamos comparar otros casos.',['Sí, siempre es igual por un caso.','Nunca sirve ningún ejemplo.'],'Tu prueba salió bien, pero necesitas más resultados.','La prueba salió bien, pero necesitamos más resultados antes de generalizar.')],[
scene('Una inscripción para todos','El centro cultural propone aceptar inscripciones solo por una página web. Diego apoya la idea porque reduce el trabajo de apuntar nombres. Marta está de acuerdo con mejorar la organización, pero recuerda que algunas personas no tienen una conexión fiable. No quiere rechazar la herramienta; propone mantener un horario breve de atención presencial. Diego responde que eso cuesta tiempo. Marta aporta un ejemplo del taller anterior, donde dos vecinos necesitaron ayuda. Reconoce que dos casos no indican cuántas personas tendrán dificultades este mes. Propone registrar las solicitudes de ayuda durante una prueba. El grupo acuerda usar la página y ofrecer una alternativa limitada. La decisión no considera comodidad e inclusión como enemigos inevitables. Busca un equilibrio y una forma de revisar si el coste de la alternativa corresponde a una necesidad real.',[['fiable','reliable'],['presencial','in person'],['inclusión','inclusion']],['¿Qué acepta Marta?','Mejorar la organización con una herramienta.','Excluir toda tecnología.','La inscripción solo digital sin alternativas.'],['¿Por qué pide una alternativa?','Algunas personas necesitan ayuda.','Some people need help.'],['¿Qué límite reconoce en su ejemplo?','No mide la demanda actual.','Demuestra que todos necesitan ayuda.','No hubo dos vecinos.'],['¿Qué propone para evaluar?','Registrar solicitudes durante una prueba.','Recording requests during a trial.'],['¿Qué respuesta expresa acuerdo parcial?','La página ayuda; aun así, conviene una alternativa para quien la necesite.','Si hay una ventaja, no hay límites.','Todo debe hacerse sin ninguna página.'],'A counterpoint can qualify a proposal rather than deny its benefit.'),
scene('Más plazas no siempre bastan','Luis propone ampliar las plazas de un curso porque la lista de espera es larga. Clara comparte el objetivo, pero duda de que añadir personas al mismo grupo sea la mejor respuesta. Explica que la sala y el tiempo de conversación ya son limitados. Luis dice que dejar a gente fuera tampoco es justo. En lugar de elegir entre un grupo enorme y ninguna ampliación, comparan otra sesión más corta. Elena pregunta por el coste y por quién podría coordinarla. Clara reconoce que su propuesta necesita recursos. La discusión gana precisión cuando cada opción incluye sus límites. Al final deciden preguntar por disponibilidad antes de anunciar nuevas plazas. No presentan una solución todavía hipotética como un compromiso. Defienden el acceso y la calidad de participación sin afirmar que una sola medida resuelve ambas cosas automáticamente.',[['la lista de espera','waiting list'],['coordinarla','coordinate it'],['los recursos','resources']],['¿Qué duda Clara?','Que ampliar el mismo grupo sea la mejor opción.','Que exista una lista de espera.','Que alguien quiera estudiar.'],['¿Por qué importa el tamaño del grupo?','Limita el tiempo de conversación.','It limits speaking time.'],['¿Qué añaden las preguntas de Elena?','Condiciones y recursos necesarios.','Una cancelación automática.','La certeza de una nueva sesión.'],['¿Qué reconoce Clara?','Su propuesta también necesita recursos.','Her proposal also needs resources.'],['¿Qué postura es matizada?','Queremos más acceso, pero debemos conservar oportunidades de participar.','Más personas resuelve todo siempre.','La calidad exige excluir a todos.'],'Compare trade-offs without reducing a discussion to two absolute choices.'),
scene('La experiencia de un barrio','Ana cuenta que un nuevo carril de bicicleta le facilita llegar al trabajo. Diego pregunta si eso demuestra que todos los comercios se benefician. Ana reconoce que habla de su trayecto y no tiene datos sobre ventas. Marta conoce una tienda que tuvo dificultades durante las obras. Los tres separan efectos temporales de cambios posteriores. No niegan la utilidad del carril porque una tienda sufrió molestias, ni descartan esas molestias porque Ana está contenta. Proponen preguntar a vecinos y comerciantes después de un periodo suficiente. La conversación muestra que defender una mejora incluye reconocer costes y buscar información sobre grupos distintos. Ana mantiene su valoración personal, pero cambia una frase demasiado amplia. En vez de decir «todo el barrio ha ganado», explica qué mejoró para ella y qué consecuencias aún deben comprobar.',[['el carril','lane'],['comerciantes','shopkeepers'],['temporales','temporary']],['¿Qué evidencia tiene Ana?','Su trayecto mejoró.','Todas las ventas aumentaron.','Nadie tuvo molestias.'],['¿Por qué separan momentos?','Las obras y el uso posterior tienen efectos distintos.','Construction and later use have different effects.'],['¿Qué cambia Ana en su argumento?','Reduce el alcance de una afirmación general.','Abandona lo que observó.','Afirma más sin datos.'],['¿Cómo mantiene su valoración?','Como experiencia personal con límites.','As a personal experience with limits.'],['¿Qué frase respeta la evidencia?','Mi trayecto ha mejorado; aún falta evaluar otros efectos.','Todos han ganado exactamente lo mismo.','Una dificultad demuestra que nada sirve.'],'Qualified claims can preserve a real benefit while acknowledging other impacts.'),
scene('Una respuesta sin atacar','Elena escribe una propuesta para reducir el tiempo de una reunión. Un compañero responde que acortarla significa no escuchar a la gente. Elena no rechaza la preocupación: también quiere participación. Explica que propone enviar información antes y reservar la sesión para preguntas, no eliminar el diálogo. Da un ejemplo de la última reunión, donde leyeron datos que todos tenían en un correo. El compañero reconoce esa diferencia, pero pide conservar un turno para asuntos nuevos. Elena incorpora la idea. La respuesta funciona porque aclara el alcance y acepta una modificación relevante. No busca demostrar que el compañero entendió todo mal. Al final comparan un formato concreto en vez de discutir sobre palabras generales como «participación». La propuesta se vuelve más defendible porque describe qué cambiará y qué se mantendrá.',[['desde mi punto de vista','from my point of view'],['defendible','defensible'],['incorpora','incorporates']],['¿Qué propone eliminar Elena?','Lectura de información ya enviada.','Todas las preguntas.','Cualquier participación.'],['¿Por qué el ejemplo es relevante?','Muestra tiempo usado en datos ya disponibles.','It shows time spent on already available information.'],['¿Qué incorpora de la otra postura?','Un turno para asuntos nuevos.','La eliminación del correo.','Un ataque personal.'],['¿Qué busca su respuesta?','Aclarar y mejorar, no culpar.','To clarify and improve, not blame.'],['¿Qué respuesta sostiene el diálogo?','Comparto la preocupación; mi propuesta mantiene preguntas y añade tiempo para asuntos nuevos.','No has entendido nada, así que no hablaré.','Participación significa solo mi formato.'],'Clarify the actual proposal before defending or rejecting it.')],[audio('Estoy de acuerdo con usar la página para inscribirse. Si bien ahorra tiempo, algunas personas necesitan ayuda. Propongo una alternativa breve y registrar cuántas solicitudes recibe.','¿Qué relación hay entre las dos ideas?','Ventaja reconocida y límite con propuesta.',['Rechazo total de la página.','Garantía de que todos necesitan ayuda.'],'The concession qualifies, rather than cancels, the benefit.'),audio_text('Mi trayecto ha mejorado, pero no sé cómo han cambiado las ventas. Conviene separar las obras temporales del uso posterior del carril.','¿Qué no sabe la persona?','Cómo han cambiado las ventas.',['How sales have changed.'],'The speaker bounds the available evidence.')],prod('defence',['Escribe «I partly agree».','Translate partial agreement.','Estoy de acuerdo en parte.','Une con si bien: ahorra tiempo; tiene límites.','Express concession.','Si bien ahorra tiempo, tiene límites.'],[('Defiende una propuesta, reconoce una objeción y ofrece una adaptación.','Defend a proposal with an objection and adjustment.','Creo que la página puede ahorrar tiempo. Entiendo que algunas personas necesitan ayuda, así que mantendría un horario breve de atención presencial.'),('Desarrolla una opinión con ejemplo y límite de evidencia.','Develop an opinion with an example and evidence limit.','El carril ha mejorado mi trayecto. Por ejemplo, llego al trabajo sin buscar aparcamiento. Sin embargo, mi experiencia no demuestra cómo afecta a todas las tiendas. Conviene preguntar a otros grupos.'),('Responde a una crítica aclarando qué cambiaría y qué conservarías.','Respond to criticism by clarifying scope and preserving a shared goal.','Comparto la preocupación por escuchar a todos. Mi propuesta no elimina las preguntas: envía los datos antes y reserva la reunión para discutirlos. También incluiría un turno para asuntos nuevos. Podemos probar el formato y revisar si mejora la participación.')],[('Reconoce otra postura',['entiendo','comparto','si bien']),('Defiende con apoyo y límites',['por ejemplo','sin embargo','no demuestra','propuesta'])])))
b21.append(unit('Formal everyday communication','Write a clear enquiry or complaint with relevant evidence and a reasonable request','Register; le agradecería; quisiera; formal structure; specific remedy',[
core('Le agradecería que comprobara los datos de la reserva.','I would appreciate you checking the booking details.','comprobara',['comprueba','comprobar'],'A conditional polite request can take imperfect subjunctive: agradecería que comprobara. The request is bounded and practical.','Empresa: «¿Qué necesita?»','Quisiera confirmar las fechas y el precio total.',['Exijo cualquier cosa sin datos.','Quiero que sabes todo.'],'Pide formalmente confirmar la dirección.','Le agradecería que confirmara la dirección.'),
core('El producto recibido no coincide con el pedido.','The product received does not match the order.','coincide',['coincido','coinciden'],'A complaint first identifies a concrete mismatch rather than assigning an intention.','Servicio: «¿Cuál es el problema?»','Pedí una talla mediana y recibí una pequeña.',['Ustedes siempre quieren engañar a todos.','No hay ningún pedido.'],'Pediste dos entradas y recibiste una. Explica el hecho.','Pedí dos entradas y recibí una.'),
core('Solicito una solución y agradecería una respuesta antes del viernes.','I request a solution and would appreciate a reply before Friday.','agradecería',['agradecí mañana','agradecen'],'A clear request and reasonable deadline make a message actionable.','Empresa: «¿Qué solución propone?»','Un cambio por el producto que pedí.',['No quiero ninguna solución concreta.','Todas las personas son malas.'],'Pide un cambio y una confirmación por escrito.','Solicito un cambio y una confirmación por escrito.')],[
scene('Una reclamación concreta','Marta recibió una chaqueta de talla pequeña aunque el pedido indicaba mediana. Su primer mensaje expresaba enfado, pero no incluía el número de compra. Ana le propuso distinguir lo ocurrido, la evidencia y la solución solicitada. Marta adjuntó una foto de la etiqueta y copió los datos del pedido. Escribió que quería un cambio por la talla correcta y preguntó cómo devolver el producto recibido. No afirmó que la empresa quisiera engañarla: no conocía la causa del error. El servicio respondió con un procedimiento y un plazo. Marta pidió confirmar si había algún coste adicional. La reclamación no perdió firmeza por mantener un tono cortés. Ganó claridad porque la persona que la recibió podía identificar el caso y responder a una petición específica. Al final Marta guardó el intercambio hasta recibir la nueva chaqueta.',[['adjuntó','attached'],['la etiqueta','label'],['la reclamación','complaint']],['¿Qué añadió al mensaje?','Datos, evidencia y petición concreta.','Más acusaciones sin número.','Una garantía de intención maliciosa.'],['¿Por qué evitó atribuir intención?','No conocía la causa del error.','She did not know the cause of the error.'],['¿Qué logró la cortesía?','Mantener firmeza con claridad.','Renunciar al cambio.','Aceptar cualquier coste sin preguntar.'],['¿Qué pidió además del procedimiento?','Confirmar posibles costes.','Confirmation of possible costs.'],['¿Qué petición es específica?','Solicito un cambio por la talla mediana del pedido.','Arreglen todo de alguna manera.','Ustedes siempre engañan.'],'A firm formal complaint separates observed facts from inferred motives.'),
scene('Preguntar antes de pagar','Luis quiere contratar una actividad para un grupo. La página anuncia un precio, pero no indica si incluye materiales ni qué ocurre con una cancelación. Escribe una consulta breve con el número de participantes y dos preguntas. El centro responde sobre el precio, pero omite la condición de cancelación. Luis agradece la información y vuelve a preguntar por ese punto. No trata la primera respuesta incompleta como una negativa. Tampoco paga antes de conocer un detalle importante para el grupo. Elena revisa el mensaje y recomienda mantener las preguntas separadas para facilitar la respuesta. Cuando llega la confirmación final, Luis resume las condiciones a sus compañeros. El registro formal le permite ser cortés y preciso sin añadir fórmulas largas que oculten lo que necesita saber.',[['contratar','book a service'],['omite','omits'],['las condiciones','terms']],['¿Qué faltó en la primera respuesta?','La condición de cancelación.','El nombre de la actividad.','Todo el precio.'],['¿Por qué pregunta de nuevo?','Es importante antes de pagar.','It matters before paying.'],['¿Cómo interpreta la omisión?','Como un punto pendiente, no necesariamente una negativa.','Como rechazo demostrado.','Como permiso para inventar condiciones.'],['¿Qué recomienda Elena?','Separar las preguntas.','Separate the questions.'],['¿Qué seguimiento es adecuado?','Gracias; queda pendiente saber qué ocurre si cancelamos.','Su respuesta prueba mala intención.','Pagaré sin conocer nada más.'],'A follow-up can preserve politeness while making an unanswered requirement explicit.'),
scene('El tono de dos mensajes','Clara debe informar de un cambio de horario a una amiga y a un centro cultural. A su amiga escribe una explicación cercana y propone hablar por teléfono. Al centro envía el número de reserva, la nueva disponibilidad y una solicitud de cambio. No cambia los hechos entre mensajes; cambia el modo de presentarlos según lo que cada destinatario necesita. Ana le pregunta si el mensaje formal debe ser más largo. Clara responde que no necesariamente: conviene incluir datos y una petición clara. Una fórmula cortés no sustituye esos elementos. Antes de enviar, revisa que la nueva fecha aparezca igual en ambos textos. Mantener el registro adecuado no significa esconder la información ni sonar distante por obligación. Significa facilitar una respuesta útil dentro de una relación diferente.',[['el destinatario','recipient'],['la disponibilidad','availability'],['el registro','register']],['¿Qué cambia Clara entre mensajes?','La presentación y el tono.','Los hechos.','La fecha según quien lea.'],['¿Por qué incluye datos al centro?','Para identificar la reserva y el cambio.','To identify the booking and change.'],['¿Qué no garantiza una fórmula cortés?','Una petición clara por sí sola.','Un tono respetuoso.','Una relación diferente.'],['¿Qué verifica antes de enviar?','La misma nueva fecha en ambos.','The same new date in both.'],['¿Qué principio resume su decisión?','Adapta el registro sin alterar los hechos.','Lo formal debe ocultar el problema.','Cuanto más largo, siempre mejor.'],'Register adaptation changes expression, not the truth of the message.'),
scene('Cerrar una reclamación','Diego reclamó un cobro duplicado por una reserva. La empresa respondió que devolvería una cantidad, pero el mensaje no mostraba cómo la calculó. Diego comparó los dos cargos y pidió un desglose. La nueva respuesta confirmó que el primer cálculo era incompleto. Antes de dar el caso por cerrado, comprobó el importe y el plazo. Después envió un agradecimiento breve con una confirmación de lo acordado. No retiró el registro de la reclamación hasta recibir la devolución. Elena pensaba que pedir detalles después de una disculpa era desconfiar demasiado. Diego explicó que una disculpa y una solución verificable cumplen funciones distintas. La conversación terminó cuando la cantidad llegó y coincidió con el acuerdo. La cortesía no le impidió comprobar un resultado que afectaba a su dinero.',[['el cobro','charge'],['el desglose','breakdown'],['la devolución','refund']],['¿Por qué pidió un desglose?','No estaba claro cómo calcularon la devolución.','No hubo ningún cargo.','Quería otra reserva.'],['¿Qué comprobó antes de cerrar?','Importe y plazo.','Amount and deadline.'],['¿Qué distingue de la disculpa?','Una solución verificable.','Un ataque personal.','Una promesa sin datos.'],['¿Qué explica a Elena?','Comprobar no contradice la cortesía.','Checking does not conflict with politeness.'],['¿Qué confirmación es útil?','Confirmo el importe y el plazo acordados; esperaré la devolución.','La disculpa demuestra que ya recibí todo.','No hace falta mirar la cantidad.'],'Formal resolution requires a specific agreed action and observed result.')],[audio('Recibí una talla pequeña, pero el pedido indica mediana. Adjunto los datos y solicito un cambio. Le agradecería que confirmara el procedimiento y cualquier coste antes del viernes.','¿Qué pide además del cambio?','Procedimiento y posibles costes.',['Una acusación pública.','Otro producto sin identificar.'],'The complaint is actionable and bounded.'),audio_text('Gracias por explicar el precio. Queda pendiente la condición de cancelación. Antes de pagar, quisiera saber qué ocurre si debemos cambiar la fecha.','¿Qué información sigue pendiente?','La condición de cancelación.',['The cancellation condition.'],'The follow-up identifies an omitted point.')],prod('formal',['Escribe una petición formal para confirmar la dirección.','Use the taught formal request.','Le agradecería que confirmara la dirección.','Explica el hecho: pedí dos entradas; recibí una.','State a mismatch without motive.','Pedí dos entradas y recibí una.'],[('Escribe una consulta con dos preguntas claras antes de pagar.','Write an enquiry with two practical questions.','Quisiera contratar la actividad para ocho personas. ¿El precio incluye los materiales? Le agradecería que indicara también la condición de cancelación.'),('Escribe una reclamación: hecho, evidencia, petición y plazo razonable.','Write a structured complaint.','El pedido indica una talla mediana, pero recibí una pequeña. Adjunto los datos y una foto de la etiqueta. Solicito un cambio por la talla correcta. Le agradecería una respuesta esta semana.'),('Responde a una solución incompleta sin perder cortesía ni precisión.','Follow up on an incomplete remedy politely and precisely.','Gracias por responder. Entiendo que devolverán el cobro duplicado, pero no aparece el cálculo del importe. Le agradecería que enviara un desglose y confirmara el plazo. Después podré comprobar que la solución coincide con lo acordado.')],[('Identifica el caso',['pedido','reserva','cobro']),('Pide una acción concreta',['solicito','agradecería','confirmara'])])))
b21.append(unit('News, media and information','Summarise a source accurately and distinguish fact, reported claim and viewpoint','Source attribution; dice que/dijo que; direct versus reported information; no automatic tense backshift',[
core('La noticia afirma que el servicio mejorará, pero no aporta datos todavía.','The report claims the service will improve, but does not provide data yet.','afirma',['afirmo','afirman'],'Attribution identifies whose claim it is; it does not endorse or verify the claim.','Ana: «¿Eso lo has comprobado tú?»','No; es lo que afirma la noticia.',['Sí, porque alguien lo dijo.','Toda afirmación es falsa.'],'El artículo dice que cambiará el horario, sin fecha confirmada. Resume con atribución.','El artículo dice que cambiará el horario, pero no da una fecha confirmada.'),
core('Luis dijo que estaba preocupado por el coste.','Luis said he was worried about the cost.','estaba',['estará ayer','estar'],'Report the content and speaker faithfully. Tense follows the temporal meaning; Spanish does not require blind backshift in every report.','Marta: «¿Cuál era la preocupación de Luis?»','El coste, según lo que dijo.',['La duración, aunque nunca la mencionó.','Todos los asuntos a la vez.'],'Ana dijo: «Estoy cansada». Cuenta lo que dijo en un contexto pasado.','Ana dijo que estaba cansada.'),
core('El dato describe una situación; la conclusión es una interpretación.','The data describes a situation; the conclusion is an interpretation.','describe',['describo','describen'],'Separate the reported observation from the argument drawn from it.','Clara: «¿Qué debemos separar al resumir?»','Los datos, las opiniones y quién los expresa.',['Toda opinión es un dato.','Nunca importa la fuente.'],'Una cifra muestra más visitas; el autor cree que el horario lo explica. Distingue ambos.','La cifra muestra más visitas; el autor cree que se debe al horario.')],[
scene('Una cifra y un titular','Ana lee un titular que anuncia un gran cambio en el transporte. El texto cita un aumento de viajeros durante una semana. También recoge la opinión de una responsable que atribuye la subida al nuevo horario. Luis está a punto de resumirlo como una mejora permanente demostrada. Ana le recuerda que el dato cubre una semana y que la explicación pertenece a la responsable. Preparan un resumen con tres partes: la cifra observada, el periodo y la interpretación atribuida. No niegan la posibilidad de mejora. Evitan ampliar el alcance de la información más allá de lo publicado. Después buscan si hay resultados de otros meses. La actividad les permite transmitir una noticia interesante sin convertir un titular llamativo en una conclusión propia. El lector del resumen puede distinguir lo medido de lo que alguien cree que explica la medida.',[['el titular','headline'],['atribuye','attributes'],['lo medido','what was measured']],['¿Qué periodo cubre la cifra?','Una semana.','Todos los años futuros.','Una década.'],['¿Por qué separan la explicación?','Pertenece a una responsable citada.','It belongs to a quoted official.'],['¿Qué error evitan?','Presentar una mejora permanente como demostrada.','Leer la cifra.','Considerar una posibilidad.'],['¿Cómo organizan el resumen?','Dato, periodo e interpretación atribuida.','Data, period and attributed interpretation.'],['¿Qué resumen es fiel?','Hubo más viajeros esa semana; una responsable lo atribuye al horario.','El horario garantiza mejora permanente.','No hay ningún dato.'],'Source attribution and scope prevent a summary from overstating the report.'),
scene('Lo que dijo la vecina','Clara entrevista a una vecina sobre una plaza renovada. La vecina dice que le gusta tener más bancos, aunque le preocupa el ruido por las noches. Al preparar un texto, Clara escribe primero que la vecina está en contra de la reforma. Elena le pide comprobar las palabras originales. La respuesta incluía una valoración positiva y una preocupación específica. Clara revisa el resumen: la vecina aprecia los bancos, pero pide atender el ruido. No elimina la crítica para hacer un texto favorable ni elimina el apoyo para crear una discusión. Mantiene el equilibrio que expresó la persona. También distingue una cita exacta de una paráfrasis. La versión final ocupa menos palabras, pero conserva la relación entre las ideas. Resumir no consiste en escoger una frase que confirme el enfoque del autor, sino en representar lo relevante de manera proporcionada.',[['la reforma','renovation'],['una paráfrasis','a paraphrase'],['proporcionada','proportionate']],['¿Qué perdió el primer resumen?','La valoración positiva de los bancos.','Toda referencia al ruido.','El nombre de la plaza.'],['¿Por qué revisa las palabras originales?','Para representar la postura completa.','To represent the full position.'],['¿Qué cambia en la versión final?','Conserva apoyo y preocupación.','Quita toda crítica.','Inventa oposición total.'],['¿Qué necesita distinguir Clara?','Cita exacta y paráfrasis.','Exact quotation and paraphrase.'],['¿Qué resumen respeta la respuesta?','Le gustan los bancos, pero le preocupa el ruido nocturno.','Rechaza toda la renovación.','No tiene ninguna preocupación.'],'A summary should retain the source’s qualification, not only one convenient fragment.'),
scene('Dos fuentes sobre un servicio','Diego compara una página de una empresa con comentarios de usuarios. La página dice que una devolución tarda pocos días. Algunos comentarios describen esperas largas. Ana observa que no saben cuántos clientes tuvieron cada experiencia ni cuándo se escribieron los comentarios. Eso no vuelve inútiles las opiniones, pero limita lo que pueden concluir. Diego escribe al servicio para preguntar por el plazo actual y las condiciones. Después resume las diferencias a Luis: una fuente presenta la política oficial y otras relatan casos individuales. No mezcla ambas como si midieran lo mismo. La respuesta del servicio confirma un plazo y explica qué documentación lo inicia. Diego decide guardar esa información para poder reclamar si hace falta. La comparación de fuentes produce una pregunta concreta en lugar de una confianza o desconfianza absoluta.',[['la política oficial','official policy'],['casos individuales','individual cases'],['la documentación','documentation']],['¿Qué describe la página?','La política oficial.','Todas las experiencias medidas.','La opinión de Ana.'],['¿Por qué pregunta por el plazo actual?','Los comentarios tienen contexto limitado.','The comments have limited context.'],['¿Qué distingue el resumen?','Una política y experiencias individuales.','Dos datos idénticos.','Una fuente siempre falsa.'],['¿Cómo usa Diego los comentarios?','Como motivo para preguntar, no como medida completa.','As a reason to ask, not a full measurement.'],['¿Qué pregunta responde a la incertidumbre?','¿Cuál es el plazo actual y qué documentación lo inicia?','¿Por qué todos mienten?','No necesito conocer condiciones.'],'Different source types answer different questions and have different limits.'),
scene('Un mensaje que cambió al pasar','Luis contó a Ana que quizá cambiaría la hora de una cena si terminaba tarde. Ana escribió al grupo que la cena iba a cambiar. Marta interpretó que ya estaba cancelada. Cuando Luis vio los mensajes, aclaró que solo había mencionado una posibilidad. El grupo comparó las tres versiones y localizó el cambio de sentido. Una condición se convirtió en una decisión y después en una cancelación. Ana corrigió el mensaje y pidió confirmar la hora cuando Luis lo supiera. No necesitó copiar toda la conversación, pero sí conservar quizá y la condición. Al final acordaron quién enviaría la confirmación definitiva. La experiencia mostró que resumir correctamente depende de mantener la fuerza de una afirmación, no solo sus palabras principales. Un pequeño cambio de certeza puede producir una gran diferencia práctica.',[['la fuerza de una afirmación','strength of a claim'],['definitiva','final'],['la condición','condition']],['¿Qué dijo Luis originalmente?','Una posibilidad condicionada.','Una cancelación segura.','Una nueva hora fija.'],['¿Por qué corrigen el mensaje?','Cambió el grado de certeza.','It changed the degree of certainty.'],['¿Qué debe conservar el resumen?','La posibilidad y la condición.','Solo la palabra cena.','Una fecha inventada.'],['¿Qué reconoce Ana?','Transmitió una decisión que no existía.','She conveyed a decision that was not made.'],['¿Qué versión es fiel?','Quizá cambie la hora si Luis termina tarde; falta confirmación.','La cena está cancelada definitivamente.','Luis ya eligió otra fecha.'],'Preserve certainty and conditions when reporting someone else’s message.')],[audio('La cifra muestra más visitas durante una semana. La responsable afirma que el horario ayudó, pero el artículo no compara otros meses.','¿Qué pertenece a la responsable?','La explicación del aumento.',['La duración exacta de todas las semanas futuras.','La voz de todos los usuarios.'],'The causal explanation is attributed, not independently demonstrated.'),audio_text('Luis dijo que quizá cambiaría la hora si terminaba tarde. No dijo que la cena estuviera cancelada. Necesitamos conservar la condición al resumir.','¿Qué no dijo Luis?','Que la cena estuviera cancelada.',['That dinner was cancelled.','La cancelación de la cena'],'The speaker explicitly rejects the stronger report.')],prod('sources',['Cuenta en pasado: Luis dijo «Estoy preocupado».','Report the stated concern in a past context.','Luis dijo que estaba preocupado.','Distingue: el artículo da una cifra; la autora interpreta su causa.','Separate fact and attributed interpretation.','El artículo da una cifra; la autora interpreta su causa.'],[('Resume una noticia separando dato, periodo e interpretación.','Summarise information with attribution and scope.','La noticia muestra más viajeros durante una semana. Una responsable lo atribuye al horario. El texto no compara otros meses, así que no demuestra una mejora permanente.'),('Compara dos fuentes y explica qué pregunta sigue pendiente.','Compare sources and identify a remaining question.','La página ofrece la política oficial y los comentarios describen experiencias individuales. No sabemos cuántos casos representan. Preguntaría por el plazo actual antes de decidir.'),('Corrige un resumen que transformó una posibilidad en una decisión.','Correct an overconfident report and preserve its condition.','El mensaje anterior fue demasiado seguro. Luis dijo que quizá cambiaría la hora si terminaba tarde; no canceló la cena. Esperaremos su confirmación y mantendremos informadas a las personas del grupo.')],[('Atribuye una afirmación',['dice','dijo','afirma','según']),('Conserva alcance o certeza',['quizá','no sabemos','durante','no demuestra'])])))
b21.append(unit('Hypothetical situations','Explain an imagined present alternative and its likely consequences','Si + imperfect subjunctive; conditional result; real/open si + indicative',[
core('Si tuviera más tiempo, haría el curso.','If I had more time, I would take the course.','tuviera',['tendría','tengo mañana'],'An imagined present condition uses si tuviera; the result uses conditional haría. Si tengo can express an open real condition.','Ana: «¿Qué harías con una tarde libre?»','Si tuviera tiempo, visitaría el museo.',['Si tendría tiempo, visitaría.','Si tuve mañana, fui.'],'Con más dinero comprarías un ordenador. Usa si.','Si tuviera más dinero, compraría un ordenador.'),
core('Si podemos cambiar la fecha, iremos juntos.','If we can change the date, we will go together.','podemos',['podríamos que','pudimos mañana'],'An open practical condition takes indicative here; it differs from an imagined si pudiéramos.','Luis: «¿La posibilidad sigue abierta?»','Sí; si podemos cambiar la fecha, iremos juntos.',['No, toda frase con si es irreal.','Sí, ya fuimos mañana.'],'Si tienes tiempo mañana, llamarás a Marta. Expresa una condición abierta.','Si tengo tiempo mañana, llamaré a Marta.'),
core('Si pudierais elegir, ¿qué opción preferiríais?','If you could choose, which option would you prefer?','pudierais',['podríais','podéis ayer'],'Vosotros imperfect subjunctive is pudierais; the imagined result is preferiríais.','Marta habla a dos amigos: «¿Qué haríais?»','Si pudiéramos, elegiríamos la ruta corta.',['Si podríamos, elegimos ayer.','Nunca tenemos ninguna preferencia.'],'Imagina que pudieras trabajar desde casa. Explica una consecuencia.','Si pudiera trabajar desde casa, tendría menos trayecto.')],[
scene('Una condición abierta','Clara pregunta si pueden cambiar la fecha de una actividad. El centro todavía no ha respondido. Luis dice «si podemos cambiarla, iremos juntos». Ana interpreta que ya eligieron otra fecha. Clara aclara que el resultado depende de una condición pendiente. Mientras esperan, preparan una alternativa para quienes no puedan asistir. No describen una situación imposible ni un deseo sin relación con los datos. Están hablando de una opción real que debe confirmarse. Después el centro ofrece dos fechas y el grupo compara disponibilidad. La frase condicional no prometía que todos irían, sino que podrían organizarse si conseguían el cambio. Al cerrar la conversación, Clara escribe qué condición se cumplió y qué acuerdo tomaron. Así la posibilidad inicial no queda mezclada con la decisión final.',[['pendiente','pending'],['se cumplió','was met'],['la disponibilidad','availability']],['¿Qué falta al principio?','La respuesta del centro.','Una actividad inexistente.','Una decisión ya publicada.'],['¿Por qué no hay acuerdo definitivo?','Depende de cambiar la fecha.','It depends on changing the date.'],['¿Qué tipo de condición presenta Luis?','Una posibilidad práctica abierta.','Un pasado imposible de cambiar.','Una garantía sin condición.'],['¿Qué aclara Clara al final?','Condición cumplida y acuerdo tomado.','The met condition and resulting agreement.'],['¿Qué mensaje es preciso al principio?','Si podemos cambiar la fecha, iremos juntos; falta confirmación.','Ya iremos todos sin ninguna condición.','No existe una respuesta posible.'],'A real condition can remain open until the required information arrives.'),
scene('Imaginando otro horario','Diego trabaja por las tardes y estudia por las mañanas. Elena le pregunta qué cambiaría si pudiera elegir cualquier horario. Diego dice que empezaría más tarde y tendría una tarde libre para ver a su familia. No afirma que el café pueda ofrecerle ese turno ahora. La conversación sirve para identificar qué valora, no para anunciar una decisión. Elena le pregunta qué parte podría mejorar dentro del horario actual. Diego piensa que podría reservar un domingo sin actividades de estudio. La hipótesis amplia produce una acción pequeña y realista. Al final explica las dos cosas por separado: si tuviera libertad total, elegiría otro turno; esta semana va a dejar una tarde sin tareas. Confundir ambas habría creado una expectativa que su trabajo todavía no permite cumplir.',[['el turno','shift'],['la expectativa','expectation'],['realista','realistic']],['¿Qué describe Diego al principio?','Un horario imaginado.','Un cambio confirmado por el café.','Un viaje pasado.'],['¿Por qué no lo anuncia como decisión?','No sabe si el trabajo lo permite.','He does not know whether work allows it.'],['¿Qué obtiene de la hipótesis?','Una prioridad para un cambio posible.','La garantía de otro turno.','La eliminación del trabajo.'],['¿Qué valora especialmente?','Tiempo con su familia.','Time with family.'],['¿Qué distingue deseo y acción?','Si pudiera elegir, cambiaría el turno; ahora reservaré una tarde libre.','Ya tengo el turno ideal sin hablar con nadie.','Las hipótesis son siempre promesas.'],'Imagined alternatives can clarify values without manufacturing a commitment.'),
scene('La opción de Luis','Luis quiere estudiar en otra ciudad, pero no puede pagar todos los gastos. Si tuviera una ayuda, podría hacerlo sin trabajar tantas horas. Clara le pregunta por otras condiciones: alojamiento, tiempo de estudio y contacto con su familia. Luis reconoce que el dinero no es el único factor. Busca información sobre ayudas reales y considera un curso más corto cerca de casa. No usa la hipótesis para concluir que solo existe una vida buena posible. Elena propone comparar qué aprendería con cada opción. El análisis distingue una alternativa deseada de una opción disponible. Luis termina con una solicitud de información y una fecha para revisar los resultados. Su deseo sigue siendo importante, pero ahora puede explicarlo junto con límites y próximos pasos.',[['una ayuda','financial support'],['disponible','available'],['los gastos','expenses']],['¿Qué condición imagina Luis?','Recibir una ayuda económica.','Tener ya todos los gastos pagados.','No estudiar nunca.'],['¿Por qué Clara añade otras preguntas?','El dinero no es el único factor.','Money is not the only factor.'],['¿Qué cambia en el análisis?','Compara una opción deseada y otra disponible.','Abandona cualquier aprendizaje.','Da la ayuda por segura.'],['¿Qué mantiene Luis?','Su deseo con límites y pasos concretos.','His wish with limits and concrete steps.'],['¿Qué frase conserva la hipótesis?','Si tuviera una ayuda, podría estudiar allí; voy a preguntar por las condiciones.','Tengo una ayuda aunque nadie la ha concedido.','Solo hay una opción válida en la vida.'],'Conditional possibilities should be compared with actual resources and constraints.'),
scene('Una decisión de grupo','El equipo tiene presupuesto para una actividad. Ana pregunta qué harían si pudieran gastar más. Algunos elegirían una excursión larga; otros prepararían dos talleres pequeños. La pregunta imaginada revela prioridades distintas, pero no aumenta el dinero disponible. Marta vuelve después a las opciones reales y propone decidir con el presupuesto actual. Luis sugiere una versión más corta de la excursión y Diego calcula materiales para un taller. Comparan qué beneficios conservaría cada adaptación y qué perdería. Nadie usa el deseo como argumento suficiente. Al final acuerdan una actividad pequeña y guardan las otras propuestas para otra ocasión. La conversación demuestra que una hipótesis puede abrir ideas, siempre que el grupo vuelva a las condiciones reales antes de comprometer recursos que no tiene.',[['el presupuesto','budget'],['comprometer','commit'],['los recursos','resources']],['¿Qué no cambia la pregunta imaginada?','El presupuesto disponible.','Las prioridades reveladas.','Las ideas consideradas.'],['¿Por qué vuelven a opciones reales?','Deben decidir con recursos actuales.','They must decide with current resources.'],['¿Qué comparan en las adaptaciones?','Beneficios conservados y pérdidas.','Solo el deseo más fuerte.','Dinero imaginario como real.'],['¿Qué utilidad tuvo la hipótesis?','Abrir ideas y mostrar prioridades.','Opening ideas and revealing priorities.'],['¿Qué frase evita una promesa falsa?','Si tuviéramos más presupuesto, haríamos otra salida; ahora elegimos una opción pequeña.','El deseo aumenta nuestro dinero.','Todo lo imaginado ya está aprobado.'],'Hypothetical exploration and actual resource decisions are distinct stages.')],[audio('Si tuviera más tiempo, haría un curso largo. Ahora no puedo, pero sí puedo asistir a un taller breve. Voy a comparar lo que aprendería en cada opción.','¿Qué opción está disponible ahora?','Un taller breve.',['El curso largo completo.','Ninguna actividad posible.'],'The speaker separates imagined resources from current availability.'),audio_text('Si podemos cambiar la fecha, iremos juntos. Es una posibilidad real, pero todavía falta la respuesta del centro.','¿Qué falta?','La respuesta del centro.',['The centre’s response.'],'The open condition depends on confirmation.')],prod('conditions',['Expresa: si tuviera tiempo; hacer el curso.','Use imagined condition and conditional result.','Si tuviera tiempo, haría el curso.','Hablas a vosotros: si podríais elegir. Corrige la condición.','Use imperfect subjunctive after hypothetical si.','Si pudierais elegir.'],[('Distingue una opción imaginada y una acción posible ahora.','Separate an imagined alternative from a current action.','Si tuviera más tiempo, haría el curso largo. Ahora puedo asistir a un taller breve y voy a preguntar por el contenido.'),('Explica una hipótesis con consecuencias y límites.','Explain a hypothetical option and trade-offs.','Si pudiera trabajar desde casa, tendría menos trayecto. Sin embargo, perdería parte del contacto con mis compañeros. Tendría que organizar momentos para hablar con ellos.'),('Propón una decisión real tras comparar dos alternativas hipotéticas.','Turn hypothetical comparison into a realistic decision.','Si tuviéramos más presupuesto, haríamos dos actividades. Con los recursos actuales, podríamos organizar un taller pequeño. Propongo comparar materiales y elegir una opción que podamos mantener sin prometer gastos imposibles.')],[('Marca condición y resultado',['si tuviera','si pudiera','haría','podría']),('Distingue recursos reales',['ahora','actuales','sin embargo'])])))
b21.append(unit('Discussing a problem','Explain a problem, compare options and recommend a solution responsive to another view','Integrated argument: cause, evidence, options, consequences, conditional proposal',[
core('El problema no es solo el precio, sino también el horario.','The problem is not only the price but also the schedule.','sino también',['pero también que','por tanto solo'],'No solo … sino también expands the issue without denying the first factor.','Ana: «¿Basta con bajar el precio?»','No; también debemos revisar el horario.',['Sí, todo se reduce al precio.','Nunca importa ningún factor.'],'No basta con una sala; también necesitas una persona para coordinar.','No basta con una sala; también necesitamos una persona para coordinar.'),
core('Si probáramos una sesión corta, podríamos evaluar la demanda.','If we tried a short session, we could evaluate demand.','probáramos',['probaríamos','probamos ayer mañana'],'Hypothetical si takes imperfect subjunctive; conditional result explains a possible benefit.','Luis: «¿Cómo comprobamos el interés sin prometer demasiado?»','Podríamos hacer una sesión de prueba.',['Prometer todo sin información.','No evaluar nunca.'],'Si cambiaseis el horario, podríais incluir a más personas.','Si cambiáramos el horario, podríamos incluir a más personas.'),
core('Reconozco ese riesgo; por eso propongo revisar el resultado después de un mes.','I recognise that risk; therefore I propose reviewing the result after a month.','Reconozco',['Reconoces','Reconocerá'],'Respond to the objection and specify how the proposed review addresses it.','Marta: «¿Y si no funciona?»','Revisaremos el resultado y podremos ajustar la propuesta.',['Seguro que nada fallará nunca.','Las objeciones no importan.'],'Reconoce el coste y propone revisar la participación tras dos semanas.','Reconozco el coste; propongo revisar la participación después de dos semanas.')],[
scene('Un horario difícil','El curso del barrio tiene una lista de espera, pero pocas personas asisten los viernes. Luis propone bajar el precio. Marta señala que varias personas trabajan a esa hora y que el problema no es solo económico. Ana recoge información de dos semanas y pregunta a quienes faltaron. Las respuestas muestran motivos distintos: trabajo, cuidado de familiares y poca claridad en los avisos. El grupo compara una sesión el sábado con una opción en línea. La primera requiere otra sala; la segunda exige ayuda técnica. Diego propone una prueba corta en sábado y una inscripción clara. Luis reconoce que eso atiende motivos que su propuesta inicial no cubría. Antes de anunciarlo confirman los recursos. La decisión incluye una revisión después de un mes. No afirman haber resuelto todo: tienen una respuesta a varios factores y una forma de observar sus consecuencias.',[['el cuidado','care'],['una lista de espera','a waiting list'],['los avisos','notices']],['¿Qué limitación tiene bajar el precio?','No resuelve todos los motivos de ausencia.','No influye nunca en nada.','Elimina el trabajo del viernes.'],['¿Por qué preguntan a quienes faltaron?','Para conocer motivos reales.','To learn actual reasons.'],['¿Qué exige la opción en línea?','Ayuda técnica.','Una sala necesariamente mayor.','Ningún recurso.'],['¿Qué reconoce Luis?','Su idea inicial no cubría todos los motivos.','His initial idea did not address every reason.'],['¿Qué propuesta combina acción y evaluación?','Probemos el sábado y revisemos la participación tras un mes.','Ya sabemos que resolverá todo.','No preguntemos después.'],'Integrated problem-solving connects evidence, trade-offs and review.'),
scene('Una solución demasiado rápida','Diego recibe quejas por la espera en el café. Piensa contratar otra persona inmediatamente. Clara observa que las colas aparecen sobre todo cuando todos piden en una sola mesa. Propone estudiar el proceso antes de asumir que falta personal. Ana anota tiempos en dos mañanas y descubre que una instrucción confusa provoca preguntas repetidas. Diego mejora el cartel y separa recogida y pedido. La espera baja, aunque los días con mucha gente siguen siendo difíciles. No usa la mejora para concluir que nunca necesitará ayuda. Compara los resultados y plantea una persona extra solo en ciertas horas. La solución evoluciona porque distingue la causa observada de una explicación inicial. Escuchar una objeción no frenó la acción; permitió escoger una medida más precisa y comprobar dónde seguía el problema.',[['la cola','queue'],['la recogida','collection'],['el proceso','process']],['¿Qué descubre la observación?','Una instrucción confusa causa preguntas repetidas.','Nunca falta personal.','Todos llegan al mismo tiempo siempre.'],['¿Por qué no contrata inmediatamente?','Quiere entender el proceso.','He wants to understand the process.'],['¿Qué límite mantiene la mejora?','Los días llenos todavía son difíciles.','Todo está resuelto para siempre.','No cambió nada.'],['¿Qué aporta la objeción de Clara?','Una acción más precisa.','A more precise action.'],['¿Qué conclusión respeta el resultado?','La organización ayudó; quizá haga falta apoyo en ciertas horas.','Nunca necesitaremos personal.','Todo se debe a una sola causa.'],'A successful partial change can guide, rather than end, further diagnosis.'),
scene('La sala compartida','Dos grupos quieren usar la misma sala los jueves. Uno hace un taller y otro necesita un lugar tranquilo para estudiar. El primer intento consiste en dividir el espacio, pero el ruido dificulta la concentración. Marta explica el problema sin culpar al taller por existir. Luis propone alternar semanas; Elena recuerda que algunas tareas de estudio tienen fechas fijas. Ana pregunta por otra sala disponible durante una hora. Encuentran una opción limitada y organizan horarios diferentes para las partes más ruidosas. La propuesta no ofrece espacio perfecto para todos, pero reduce el conflicto principal. Cada grupo acepta revisar cómo funciona y avisar de necesidades nuevas. La solución nace de reconocer que compartir no siempre significa estar juntos al mismo tiempo. Un acuerdo concreto resulta más útil que pedir buena voluntad sin cambiar las condiciones.',[['la concentración','concentration'],['alternar','alternate'],['buena voluntad','goodwill']],['¿Por qué falló dividir el espacio?','El ruido afectaba al estudio.','No había ningún taller.','La sala desapareció.'],['¿Qué límite tiene alternar semanas?','Algunas tareas tienen fechas fijas.','Some study tasks have fixed deadlines.'],['¿Qué cambia la propuesta final?','Espacios y horarios de partes ruidosas.','Solo pide paciencia sin cambios.','Cancela ambos grupos.'],['¿Qué comprenden sobre compartir?','No siempre requiere coincidir en todo momento.','It does not always require being together at once.'],['¿Qué acuerdo puede comprobarse?','Probemos estos horarios y revisemos si reducen el ruido.','Todo será perfecto sin cambiar nada.','La buena voluntad elimina cualquier condición.'],'Practical agreement modifies conditions rather than relying only on intentions.'),
scene('Una propuesta revisada','Clara presenta una ruta cultural para visitantes. Luis piensa que es demasiado larga y Marta pregunta si una persona con movilidad reducida puede seguirla. Clara escucha sin tratar cada pregunta como rechazo. Divide la ruta en un recorrido básico y dos paradas opcionales. Añade información sobre distancias y lugares para descansar. Ana recomienda comprobar la accesibilidad con el centro antes de publicar. Clara explica que no puede garantizar cada condición a partir de una visita propia. Pide datos y revisa el mensaje. El resultado mantiene el interés cultural, pero hace más visibles los límites y las opciones. La propuesta mejora porque responde a una necesidad concreta y no solo defiende su primer diseño. Después de la primera salida recogerán comentarios para ajustar aquello que la información previa no mostró.',[['movilidad reducida','reduced mobility'],['accesibilidad','accessibility'],['el diseño','design']],['¿Qué modifica Clara?','Ruta básica y paradas opcionales.','Elimina toda información.','Obliga a seguir todo.'],['¿Por qué pide datos de accesibilidad?','Su experiencia no garantiza todas las condiciones.','Her experience cannot guarantee every condition.'],['¿Qué conserva la propuesta?','El interés cultural con opciones más claras.','Un recorrido único sin límites.','Una garantía absoluta.'],['¿Cómo responde a las preguntas?','Las usa para mejorar el diseño.','She uses them to improve the design.'],['¿Qué mensaje es responsable?','Estas son las distancias y opciones; confirmaremos la accesibilidad antes de publicar.','Mi visita demuestra que sirve a todos.','No importa conocer los límites.'],'A defensible solution responds to objections and states verification limits.')],[audio('El problema no es solo el precio. Algunas personas trabajan el viernes y otras no entienden los avisos. Propongo una sesión corta el sábado con inscripción clara y una revisión después de un mes.','¿Qué hace la propuesta?','Responde a varios factores y prevé evaluación.',['Solo cambia el precio.','Garantiza asistencia de todos.'],'The plan integrates different causes and a review point.'),audio_text('La espera bajó tras aclarar el cartel, pero los días llenos siguen siendo difíciles. Quizá necesitemos ayuda solo en ciertas horas.','¿Qué sigue siendo difícil?','Los días con mucha gente.',['Busy days.'],'The partial improvement has an explicit limit.')],prod('problem',['Une: no solo el precio; también el horario.','Expand the stated problem.','El problema no es solo el precio, sino también el horario.','Completa una condición imaginada: si probar una sesión; evaluar la demanda.','Use hypothetical condition and result.','Si probáramos una sesión, podríamos evaluar la demanda.'],[('Explica un problema con dos factores y compara dos opciones.','Explain a multifactor problem and compare options.','La asistencia depende del horario y de los avisos, no solo del precio. Una sesión en sábado necesita otra sala; una opción en línea necesita apoyo técnico.'),('Responde a una objeción y mejora tu propuesta con un modo de evaluarla.','Respond to an objection, adapt and evaluate.','Entiendo que el coste preocupa. Podríamos empezar con una sesión pequeña y confirmar recursos antes de anunciarla. Después compararíamos la participación y los comentarios.'),('Escribe una propuesta completa: problema, evidencia, opciones, recomendación, límite y revisión.','Write a complete practical proposal with evidence and evaluation.','Algunas personas faltan por el horario y otras no entienden los avisos. Hemos recogido respuestas de dos semanas. Propongo probar una sesión corta el sábado con inscripción clara. Necesitamos confirmar la sala y no podemos garantizar toda la asistencia. Revisaremos el resultado después de un mes.')],[('Relaciona evidencia y propuesta',['hemos','porque','propongo']),('Incluye límites y revisión',['necesitamos','no podemos','revisaremos'])])))
save('B2.1',b21)
b22=[]
b22.append(unit('Viewpoint and perspective','Qualify a position, acknowledge another perspective and identify evidence limits','Hasta cierto punto; desde mi punto de vista; no necesariamente; certainty and scope',[
core('Hasta cierto punto estoy de acuerdo, aunque faltan datos.','I agree to a certain extent, although data is missing.','Hasta cierto punto',['En ningún punto siempre','Debido a punto'],'The qualifier limits agreement; aunque marks the remaining concern.','Ana: «¿Apoyas toda la propuesta?»','Apoyo el objetivo, aunque faltan datos sobre el coste.',['Sí, apoyo todo sin saber nada.','No hay ningún objetivo.'],'Compartes la idea, pero no sabes si responde a todos.','Hasta cierto punto estoy de acuerdo, pero no sé si responde a todos.'),
core('Desde mi punto de vista, la prioridad es aclarar las condiciones.','From my point of view, the priority is to clarify the conditions.','es',['soy','son'],'The subject la prioridad is singular; viewpoint attribution leaves room for another priority.','Luis: «¿Qué consideras más urgente?»','Aclarar las condiciones antes de decidir.',['Afirmar certeza sin información.','Decidir sin preguntar.'],'Tu prioridad es conocer las necesidades de los participantes.','Desde mi punto de vista, la prioridad es conocer las necesidades de los participantes.'),
core('Una experiencia positiva no implica necesariamente que funcione para todos.','A positive experience does not necessarily mean it works for everyone.','implica',['implico','implican'],'This target needs indicative implica in the stated claim; do not force subjunctive into every uncertain-sounding sentence.','Clara: «¿Tu experiencia demuestra un resultado universal?»','No; puede orientar, pero su alcance es limitado.',['Sí, una persona representa a todos.','Una experiencia nunca aporta nada.'],'Una prueba útil no garantiza resultados en todos los grupos.','Una prueba útil no garantiza resultados en todos los grupos.')],[
scene('Una opinión con alcance','Elena participa en una conversación sobre una actividad en línea. A ella le resultó cómoda porque evitó un viaje largo y pudo preguntar por escrito. Luis tuvo problemas de conexión y prefirió la sesión presencial. Al principio alguien pidió elegir cuál experiencia era la verdadera. Elena explicó que ambas podían serlo: describían condiciones diferentes. Desde su punto de vista, la herramienta amplió posibilidades, pero no necesariamente para todos. Luis reconoció la ventaja del viaje evitado y pidió una alternativa para conexiones débiles. Marta propuso separar satisfacción, acceso y calidad de participación. No podían medir las tres cosas con un solo comentario. El grupo decidió preguntar por cada aspecto en lugar de recoger únicamente una nota general. Elena reformuló su posición: apoya mantener la opción en línea siempre que se hagan visibles sus límites. Luis no necesitó negar su experiencia positiva para defender la suya. Al final la discusión pasó de buscar una única versión a comparar qué condiciones permiten que una opción sea útil. La próxima evaluación incluirá preguntas sobre acceso y sobre la posibilidad real de intervenir.',[['desde mi punto de vista','from my point of view'],['reformuló','rephrased'],['intervenir','contribute']],['¿Qué rechaza Elena?','Que solo una experiencia pueda ser verdadera.','La experiencia de Luis.','La existencia de problemas.'],['¿Por qué le resultó cómoda?','Evitó un viaje y pudo preguntar por escrito.','It avoided travel and allowed written questions.'],['¿Qué mejora separar tres aspectos?','Evita que una nota general oculte diferencias.','Garantiza satisfacción universal.','Impide evaluar.'],['¿Cómo modifica Elena su posición?','Apoya la opción con límites visibles.','She supports the option with visible limits.'],['¿Qué respuesta reconoce perspectivas?','Tu dificultad es real; mi experiencia positiva también tuvo condiciones concretas.','Mi experiencia demuestra que la tuya es falsa.','Una nota resume todo necesariamente.'],'Different experiences can be valid evidence with distinct scope.'),
scene('La palabra «todos»','Diego escribe un anuncio diciendo que todos los clientes prefieren el nuevo horario del café. Ana le pregunta qué información tiene. Diego ha recibido varios comentarios positivos, pero no ha hablado con quienes dejaron de venir. El horario también coincide con un cambio en los turnos del barrio. Diego comprende que su muestra no representa automáticamente a cada persona. Cambia la frase: varios clientes valoran la apertura temprana y quieren mantenerla. No elimina el entusiasmo; evita una afirmación que no puede sostener. Clara propone dejar un espacio para comentarios sobre la tarde, que ahora es más corta. Luis teme que mencionar límites debilite el anuncio. Ana explica que la precisión puede aumentar la confianza porque muestra qué se sabe y qué falta. Diego decide mantener la descripción concreta y preguntar por necesidades distintas. El objetivo ya no es defender la palabra todos, sino encontrar un horario que pueda explicar con honestidad. Después comparará los comentarios sin tratar el silencio de una persona como acuerdo automático.',[['la muestra','sample'],['sostener','support a claim'],['automáticamente','automatically']],['¿Qué no conoce Diego?','La opinión de quienes dejaron de venir.','Los comentarios que recibió.','Su propio horario.'],['¿Por qué cambia todos por varios?','Los datos no representan a cada persona.','The data does not represent every person.'],['¿Qué puede aportar reconocer límites?','Más confianza por precisión.','Una prueba de fracaso.','Una garantía de acuerdo.'],['¿Qué deja de defender Diego?','Una palabra demasiado amplia.','An overly broad word.'],['¿Qué anuncio es fiel?','Varios clientes valoran la apertura temprana; seguimos recogiendo comentarios.','Todos están de acuerdo, incluso quienes no conocemos.','El silencio prueba apoyo.'],'Quantifiers must match evidence; silence does not automatically mean agreement.'),
scene('Mirar desde otro lugar','Marta propone un recorrido cultural que incluye escaleras. Para ella es corto y fácil porque conoce el barrio y camina deprisa. Clara le pide considerar a alguien que llega por primera vez o necesita un ritmo diferente. Marta no había pensado en esas condiciones. No abandona toda la ruta: identifica los tramos con dificultades y busca alternativas. Ana le sugiere describir distancia y descansos en lugar de usar solo la palabra fácil. Luis pregunta si ahora el recorrido es accesible a cualquier persona. Marta responde que no puede garantizarlo sin más información. Puede ofrecer datos para que cada visitante decida y consultar los puntos que desconoce. La revisión no transforma una perspectiva personal en la única legítima. La coloca junto a otras necesidades. Al final el anuncio evita una promesa universal e incluye una alternativa sin escaleras para una parte del camino. Marta aprende que matizar no equivale a renunciar al objetivo, sino a explicar mejor para quién y en qué condiciones funciona.',[['los tramos','sections'],['legítima','legitimate'],['matizar','qualify']],['¿Qué cuestiona Clara?','El alcance de fácil desde una sola perspectiva.','El interés cultural.','La existencia del barrio.'],['¿Por qué añade datos concretos?','Permiten decidir con condiciones reales.','They allow decisions based on actual conditions.'],['¿Qué no garantiza Marta?','Accesibilidad universal.','La existencia de escaleras.','Una alternativa parcial.'],['¿Cómo entiende matizar?','Explicar mejor las condiciones.','Explaining conditions more clearly.'],['¿Qué descripción es útil?','Hay escaleras en este tramo y una alternativa parcial; conviene revisar las necesidades.','Es fácil para todos sin excepción.','Si a mí me sirve, debe servir a cualquiera.'],'Perspective-aware description gives actionable details instead of universal labels.'),
scene('Una prioridad discutida','El centro tiene dinero para mejorar una sala o comprar más material. Elena cree que la sala es prioritaria porque dificulta participar a algunas personas. Diego defiende el material porque limita lo que pueden practicar. Los dos aportan casos, pero no comparan todavía cuántas actividades afecta cada problema. Ana propone formular las prioridades como posiciones justificadas, no como hechos indiscutibles. Desde el punto de vista de Elena, el acceso debe atenderse primero. Diego reconoce ese criterio, aunque pide evaluar qué parte de la mejora es posible con el presupuesto. La discusión incorpora una opción parcial para la sala y un préstamo de materiales. No demuestra que una prioridad sea siempre superior. Produce una decisión contextual con razones y límites. Al comunicarla, el grupo explica qué necesidad atiende ahora y cuál sigue pendiente. Esa claridad permite que quien no recibió su opción preferida entienda el proceso sin tener que declarar que su preocupación era irrelevante.',[['el préstamo','loan'],['prioritaria','a priority'],['irrelevante','irrelevant']],['¿Qué faltaba al principio?','Comparar alcance de los dos problemas.','Toda razón para las opciones.','Un presupuesto infinito.'],['¿Por qué Ana cambia la formulación?','Las prioridades son posiciones justificadas.','Priorities are reasoned positions.'],['¿Qué logra la opción parcial?','Atender una necesidad sin ocultar otra pendiente.','Resolver todas las necesidades.','Demostrar una jerarquía universal.'],['¿Qué puede entender quien discrepa?','El proceso aunque no prefiera el resultado.','The process despite not preferring the outcome.'],['¿Qué comunicación es transparente?','Atendemos esta necesidad ahora; la otra sigue pendiente por estos límites.','La opción elegida prueba que la otra nunca importó.','No hace falta explicar razones.'],'A justified priority is contextual and should not erase an unaddressed need.')],[audio('Hasta cierto punto apoyo la actividad en línea: evitó mi viaje y pude preguntar. Luis tuvo problemas de conexión. Ambas experiencias son reales; necesitamos evaluar acceso y participación por separado.','¿Qué rechaza la persona?','Que una experiencia invalide automáticamente la otra.',['Que hubiera ventajas.','Que Luis tuviera conexión débil.'],'The speaker qualifies support without denying another perspective.'),audio_text('Varios clientes valoran abrir temprano, pero no conocemos la opinión de quienes dejaron de venir. No puedo decir que todos prefieren el horario.','¿Qué grupo no está representado?','Quienes dejaron de venir.',['Those who stopped coming.'],'The speaker identifies a sample limitation.')],prod('perspective',['Escribe «I agree to a certain extent».','Translate qualified agreement.','Estoy de acuerdo hasta cierto punto.','Expresa que una prueba no garantiza resultados universales.','State the limit.','Una prueba no garantiza resultados para todos.'],[('Defiende una prioridad y reconoce otra perspectiva.','Defend a priority while acknowledging another view.','Desde mi punto de vista, debemos mejorar el acceso primero. Entiendo que faltan materiales, pero la sala limita quién puede participar. Propongo una mejora parcial y buscar un préstamo de material.'),('Revisa una afirmación demasiado general usando evidencia y límites.','Rewrite an overgeneral claim with evidence and limits.','Varios clientes han valorado el nuevo horario. No conocemos la opinión de quienes dejaron de venir. La experiencia es positiva para ese grupo, pero no demuestra que el cambio sirva a todos.'),('Escribe una posición matizada: apoyo, evidencia, otra perspectiva y una pregunta pendiente.','Write a qualified position with evidence, another perspective and an open question.','Hasta cierto punto apoyo la sesión en línea porque me permitió participar sin viajar. Sin embargo, algunas personas tuvieron problemas de conexión. Sus experiencias no contradicen necesariamente la mía: muestran condiciones distintas. Antes de mantener un único formato, debemos preguntar qué alternativas necesitan.')],[('Califica la afirmación',['hasta cierto punto','desde mi punto de vista','no necesariamente']),('Reconoce otra evidencia',['sin embargo','algunas','no conocemos'])])))
b22.append(unit('Complex narration','Produce an extended account linking earlier events, reactions, consequences and reflection','Pluperfect and tense integration; conditional perfect reflection; chronology versus viewpoint',[
core('Ya habíamos preparado todo cuando cambiaron la fecha.','We had already prepared everything when they changed the date.','habíamos preparado',['prepararemos','hemos preparar'],'Pluperfect places preparation before a later past change.','Ana: «¿El cambio llegó antes de preparar?»','No; ya habíamos preparado todo.',['Sí, prepararemos ayer.','Nada existía nunca.'],'Ya compraste las entradas cuando cancelaron la actividad.','Ya había comprado las entradas cuando cancelaron la actividad.'),
core('Al recordarlo, habría pedido ayuda antes.','Looking back, I would have asked for help earlier.','habría pedido',['habré pedido','había pedir'],'Habría + participle expresses a hindsight alternative, not an action that actually happened.','Luis: «¿Qué cambiarías al mirar atrás?»','Habría explicado el problema antes.',['Lo expliqué antes aunque no ocurrió.','Lo explicaré ayer.'],'Al mirar atrás, habrías comprobado los horarios antes.','Al recordarlo, habría comprobado los horarios antes.'),
core('La reacción inicial cambió después de conocer el contexto.','The initial reaction changed after learning the context.','cambió',['cambiaré','cambiar'],'The account connects a change in interpretation with new information.','Marta: «¿Sigues interpretándolo igual?»','No; ahora conozco lo que ocurrió antes.',['Sí, no necesito escuchar nada.','Nunca hubo información.'],'Tu primera impresión era negativa; luego conociste el motivo.','Mi primera impresión era negativa, pero cambió al conocer el motivo.')],[
scene('Una semana contada después','Elena relata la preparación de una exposición varios meses después. Al principio recuerda una semana difícil porque la fecha cambió cuando ya habían preparado invitaciones. Luis recuerda que el grupo consiguió una sala mejor y que asistieron más personas de lo esperado. Antes del cambio, Elena había pedido a cada compañero una tarea, pero no fijó una forma de confirmar el resultado. Cuando faltó un material, pensó que nadie cumplía los acuerdos. Después descubrió que dos personas recibieron versiones distintas de la lista. Esa información modificó su reacción sin borrar el cansancio que sintió. En el relato distingue lo que sabía entonces de lo que sabe ahora. Dice que habría pedido una confirmación única antes de imprimir. No presenta esa alternativa como un hecho pasado. Ana señala que la exposición salió bien y pregunta si eso vuelve innecesaria la reflexión. Elena responde que un buen resultado puede convivir con un proceso que necesita mejora. Su narración termina con una decisión concreta para futuras actividades y no con una versión ideal donde todo estaba previsto.',[['el cansancio','tiredness'],['convivir','coexist'],['el proceso','process']],['¿Qué ocurrió antes del cambio de fecha?','Ya habían preparado invitaciones.','Se publicó el relato meses después.','La exposición terminó.'],['¿Por qué cambió la reacción de Elena?','Descubrió listas distintas.','She discovered different lists.'],['¿Qué expresa habría pedido?','Una alternativa retrospectiva no realizada.','Una petición realizada con certeza.','Un futuro confirmado.'],['¿Qué distingue en su relato?','Lo que sabía entonces y lo que sabe ahora.','What she knew then and now.'],['¿Qué reflexión respeta el resultado?','Salió bien, pero habría mejorado la confirmación de tareas.','El buen resultado prueba que todo fue perfecto.','La reflexión cambia los hechos pasados.'],'Narrative reflection can preserve success while identifying process limits.'),
scene('El viaje que parecía fallido','Ana guardó una nota del día en que perdió una conexión. En ella decía que el viaje fue un desastre. Un año después la leyó con Luis, que recordó otro detalle: pudieron hablar con una vecina durante la espera y encontrar un camino distinto. Ana no niega que estaba frustrada ni que llegó tarde. Sin embargo, ahora separa el problema inicial del conjunto de la experiencia. Antes de salir había elegido una conexión muy corta. Cuando el tren se retrasó, no tenía margen. Con una comparación más cuidadosa, habría comprado otra combinación, piensa; esa hipótesis no cambia el billete que usó. Para no cargar el relato con una sola valoración, cuenta primero el orden de hechos y después sus dos reacciones, la de entonces y la de ahora. Luis añade su perspectiva sin imponerla. El resultado es una narración más rica: reconoce una dificultad real, un encuentro inesperado y una decisión que puede mejorar otro viaje.',[['el margen','time buffer'],['la combinación','connection combination'],['frustrada','frustrated']],['¿Qué cambia al releer?','La valoración global, no los hechos.','El billete realmente usado.','La hora real de llegada.'],['¿Por qué perdió la conexión?','Tenía poco margen y hubo retraso.','There was little connection time and a delay.'],['¿Qué aporta Luis?','Una perspectiva adicional sin negar la dificultad.','La certeza de que no llegó tarde.','Un cambio del pasado.'],['¿Qué separa Ana?','Secuencia de hechos y reacciones.','Event sequence and reactions.'],['¿Qué resumen es equilibrado?','El viaje tuvo un problema real y también un encuentro valioso.','Nada fue difícil.','La nueva valoración elimina el retraso.'],'Reflection changes interpretation without altering chronology.'),
scene('Una decisión vista desde lejos','Diego dejó un curso porque los turnos del café cambiaron. En aquel momento pensaba que debía elegir entre estudiar o trabajar. Meses después encuentra sus mensajes y ve que no preguntó por otra forma de entregar el proyecto. Eso no demuestra que el centro habría aceptado cualquier opción. Significa que no llegó a conocer todas las condiciones. Elena le pregunta si ahora se culpa por no preverlo. Diego responde que quiere aprender, no inventar una decisión perfecta con la información posterior. Cuenta qué sabía, qué priorizó y qué no comprobó. Antes de dejar el curso había intentado estudiar por la noche, pero estaba agotado. El relato incluye esa presión y no reduce todo a una falta de interés. Ahora prepara una consulta para otro curso con preguntas sobre horarios y entregas. Habría pedido más información antes, dice, y esa reflexión orienta una acción presente. No puede garantizar un resultado distinto en el pasado, pero sí una decisión mejor informada la próxima vez.',[['agotado','exhausted'],['preverlo','foresee it'],['posterior','later']],['¿Qué no comprobó Diego?','Alternativas para entregar el proyecto.','La existencia de sus turnos.','Que estaba cansado.'],['¿Por qué estudiaba con dificultad?','Los turnos cambiaron y estaba agotado.','Shifts changed and he was exhausted.'],['¿Qué evita su reflexión?','Juzgar el pasado como si ya conociera toda la información posterior.','Pedir nuevas condiciones.','Reconocer límites.'],['¿Qué quiere obtener ahora?','Una decisión mejor informada.','A better-informed decision.'],['¿Qué frase es cauta?','Habría preguntado antes, aunque no sé qué habría aceptado el centro.','Seguro que cualquier opción habría funcionado.','Nunca hubo presión de tiempo.'],'Hindsight should inform a new decision, not falsely guarantee a different past outcome.'),
scene('La historia de una puerta abierta','Clara recuerda la primera actividad que organizó para vecinos. Llegó tarde porque estaba ayudando a una participante a encontrar el acceso sin escaleras. Dentro, algunas personas pensaron que olvidó la hora. Antes de salir, Clara había confirmado la ruta en una página antigua y descubrió una obra al llegar. Primero buscó una alternativa y después avisó al grupo. Al contar la experiencia años más tarde, no presenta su retraso como algo sin efecto: varias personas esperaron sin suficiente información. Tampoco acepta que la única explicación fuera desinterés. Relaciona el dato equivocado, la ayuda concreta y la comunicación tardía. Luis destaca que finalmente todos participaron. Clara valora ese resultado, pero dice que habría comprobado el acceso con el centro y avisado antes. El relato permite reconocer una intención útil y una mejora necesaria. La reflexión termina en dos acciones prácticas para la siguiente actividad, no en una defensa absoluta de todo lo que hizo.',[['el acceso','entrance'],['una obra','construction work'],['desinterés','lack of interest']],['¿Qué información previa falló?','La ruta de una página antigua.','La hora nunca acordada.','El nombre de todos.'],['¿Por qué llegó tarde?','Buscó un acceso alternativo con una participante.','She found an alternative entrance with a participant.'],['¿Qué reconoce además de la buena intención?','La espera causada por avisar tarde.','Que no hubo ningún efecto.','Que nadie participó.'],['¿Qué mejoraría Clara?','Comprobar el acceso y avisar antes.','Checking access and informing earlier.'],['¿Qué relato mantiene ambos aspectos?','Quise ayudar, pero habría comprobado la ruta y comunicado antes.','Una buena intención elimina todo efecto.','El resultado bueno impide reflexionar.'],'Extended narration can integrate intention, impact and hindsight.')],[audio('Ya habíamos preparado las invitaciones cuando cambiaron la fecha. Entonces pensé que nadie se organizaba. Después vi que teníamos listas distintas. Al recordarlo, habría pedido una confirmación única.','¿Qué distingue la reflexión final?','Una alternativa que no se realizó.',['Un hecho anterior confirmado.','Una nueva fecha obligatoria.'],'Conditional perfect marks hindsight, not a completed action.'),audio_text('La nota decía que el viaje fue un desastre. Ahora reconozco el retraso y también el encuentro durante la espera. Los hechos no cambiaron; cambió mi valoración.','¿Qué cambió?','La valoración.',['The evaluation.','Su interpretación'],'The chronology stays the same.')],prod('complex narration',['Escribe «We had already prepared everything».','Translate prior completion.','Ya habíamos preparado todo.','Expresa al mirar atrás: pedir ayuda antes.','Use conditional perfect for a hindsight alternative.','Habría pedido ayuda antes.'],[('Relata un cambio de interpretación con antecedente, hecho y reacción.','Narrate a changed interpretation with chronology.','Ya habíamos organizado las tareas cuando faltó un material. Pensé que nadie había cumplido, pero después descubrí que recibimos listas distintas. Mi reacción cambió al conocer el contexto.'),('Cuenta una experiencia desde entonces y desde ahora. Distingue hechos de reflexión.','Write an extended account comparing past and present interpretation.','En aquel momento vi el viaje como un fracaso porque llegué tarde. Ahora reconozco también la conversación durante la espera. Había elegido una conexión corta y no tenía margen. Habría comparado mejor los horarios. Esa reflexión no elimina el retraso, pero ayuda a preparar otro viaje.'),('Escribe un relato conectado con un antecedente, dos perspectivas, consecuencia y reflexión.','Write a connected account with chronology, perspectives and reflection.','Ya había confirmado el acceso cuando descubrí que la información era antigua. Busqué otra entrada con una participante y llegué tarde. Dentro, algunos pensaron que había olvidado la hora; yo estaba intentando ayudar. Entiendo que la espera les afectó. Habría avisado antes y comprobaré el acceso directamente la próxima vez.')],[('Distingue antecedentes',['había','habíamos','cuando']),('Integra perspectivas y reflexión',['pensé','ahora','habría','entiendo'])])))
b22.append(unit('Argument and counterargument','Develop a supported position, engage with an objection and qualify the conclusion','Position, evidence, concession, counterargument and bounded conclusion',[
core('Aunque la propuesta ahorra tiempo, no resuelve el problema de acceso.','Although the proposal saves time, it does not solve the access problem.','Aunque',['Por eso','Debido a'],'Aunque introduces a concession: the advantage is real, but insufficient.','Luis: «Entonces, ¿rechazas cualquier ventaja?»','No; reconozco el ahorro, pero falta resolver el acceso.',['Sí, una ventaja demuestra que todo funciona.','No hay que escuchar las objeciones.'],'Reconoce una ventaja del curso en línea y señala un límite de conexión.','Aunque el curso en línea es cómodo, algunas personas tienen problemas de conexión.'),
core('El ejemplo apoya nuestra idea, pero no basta para generalizar.','The example supports our idea, but is not enough to generalise.','apoya',['apoyan','apoyar'],'One example can support an argument without proving it applies to everyone.','Ana: «¿Un caso prueba que sirve para todos?»','No; necesitamos comparar más experiencias.',['Sí, todos son exactamente iguales.','Los ejemplos nunca aportan nada.'],'Explica que una experiencia favorable no prueba un resultado universal.','La experiencia fue positiva, pero no demuestra que la opción sirva para todos.'),
core('Por estas razones, propongo una prueba antes de decidir definitivamente.','For these reasons, I propose a trial before making a final decision.','propongo',['propones','proponer'],'The conclusion follows the reasons and remains proportionate to the evidence.','Marta: «¿Cómo podemos avanzar sin ignorar el riesgo?»','Podemos hacer una prueba y revisar los resultados.',['Podemos afirmar que no hay riesgos sin comprobar.','Podemos cambiar los datos.'],'Concluye una discusión proponiendo probar y evaluar.','Por estas razones, propongo probar la medida y evaluar sus resultados.')],[
scene('Abrir los domingos','La asociación estudia abrir el local los domingos. Ana defiende una prueba porque algunas personas trabajan el sábado y no pueden asistir. Presenta dos mensajes de vecinos como ejemplo, pero reconoce que no representan a todo el barrio. Luis pregunta quién se encargará de abrir: el grupo de voluntarios ya dedica muchas horas. Ana no responde que esa preocupación sea una excusa. Propone cuatro domingos alternos y un turno voluntario que nadie esté obligado a aceptar. Marta añade otra objeción: si solo vienen quienes escribieron los mensajes, quizá el esfuerzo no compense. El grupo acuerda contar asistentes y preguntar qué otros horarios podrían servir. También registrará las horas de preparación, no solo la asistencia. Al final Ana reformula su conclusión. No afirma que abrir siempre sea la mejor solución; considera razonable una prueba limitada con criterios claros para continuar o detenerla. Luis apoya esa versión porque mantiene la posibilidad de mejorar el acceso sin dar por hecho que el trabajo extra sea gratuito. El desacuerdo ayuda a precisar la propuesta en lugar de impedir cualquier decisión.',[['un turno','a shift'],['compense','be worthwhile'],['detenerla','stop it']],['¿Qué propone Ana al final?','Una prueba limitada con criterios.','Abrir todos los domingos sin evaluación.','Obligar a Luis a abrir.'],['¿Por qué le interesa el domingo?','Algunas personas trabajan el sábado.','Some people work on Saturdays.'],['¿Qué evita medir también la preparación?','Que la asistencia oculte el esfuerzo necesario.','Que alguien pueda asistir.','Que existan otros horarios.'],['¿Cómo influye la objeción de Luis?','Hace que Ana limite y precise la propuesta.','It makes her qualify and specify the proposal.'],['¿Qué conclusión respeta el debate?','Probemos y revisemos acceso y esfuerzo.','Dos mensajes demuestran que todos vendrán.','El trabajo voluntario no cuesta nada.'],'The concession changes the proposal without abandoning its practical purpose.'),
scene('La encuesta del café','Diego quiere reducir el uso de vasos de un solo uso en el café. Una encuesta entre clientes habituales muestra apoyo a los vasos reutilizables. Elena señala que no se preguntó a quienes compran una bebida de paso. Diego acepta el límite y evita presentar el resultado como la opinión de todos. Explica, sin embargo, que los clientes habituales generan una parte importante de los residuos. Luis teme que pedir un depósito complique las compras rápidas. Elena responde con un ejemplo de otro local, pero aclara que allí el sistema funciona con un personal diferente. No lo presenta como garantía. Proponen probar el depósito durante dos semanas, mantener una alternativa y explicar con claridad cómo recuperarlo. Antes de empezar, acuerdan medir devoluciones, tiempo de atención y comentarios de ambos tipos de clientes. Diego termina con una posición más precisa: el sistema merece una prueba, no una aprobación automática. La encuesta sirve como punto de partida y la objeción descubre una pregunta que faltaba. Si la espera aumenta demasiado, revisarán el procedimiento en vez de culpar a los clientes por no adaptarse.',[['un depósito','a refundable deposit'],['los residuos','waste'],['las devoluciones','returns']],['¿Qué limita la encuesta?','Solo recoge clientes habituales.','Incluye a todos los vecinos.','No contiene ninguna respuesta.'],['¿Por qué mantiene Diego su propuesta?','Los clientes habituales generan muchos residuos.','Regular customers generate considerable waste.'],['¿Qué valor tiene el otro local?','Es un ejemplo, no una garantía.','Prueba que no habrá espera.','Sustituye la evaluación.'],['¿Qué cambia tras la objeción?','Se mide también la rapidez y se mantiene una alternativa.','Speed is measured and an alternative retained.'],['¿Qué respuesta integra ambas posiciones?','Probemos, pero midamos también las compras rápidas.','La encuesta elimina todos los riesgos.','Quien tenga prisa no debe comprar.'],'A relevant example supports a proposal while differences between settings limit the inference.'),
scene('Un límite para los móviles','Un profesor propone dejar los móviles fuera de una actividad de conversación. Cree que las notificaciones interrumpen la escucha y cita lo que observó en dos sesiones. Marta coincide con ese problema, pero pregunta por quienes usan el móvil para consultar una palabra o una instrucción accesible. El profesor reconoce que prohibir todos los usos mezclaría distracción y apoyo. Diego añade que una regla difícil de explicar podría causar más interrupciones que las notificaciones. No defienden que cualquier uso sea útil. Juntos distinguen tres momentos: conversación sin notificaciones, consulta breve cuando haga falta y pausa libre. Luis pregunta cómo comprobarán si la nueva norma funciona. Deciden observar interrupciones y preguntar si las consultas ayudan a participar. El profesor mantiene su objetivo, pero cambia el medio. Su conclusión ya no es que el móvil sea siempre un problema, sino que ciertos usos dificultan una actividad concreta. Marta acepta la propuesta revisada porque permite apoyo sin convertir toda la sesión en una consulta continua. El argumento mejora al responder a una objeción relevante, no al repetir con más fuerza la primera afirmación.',[['las notificaciones','notifications'],['apoyo','support'],['el medio','the means']],['¿Qué cambia el profesor?','La regla, no el objetivo de escuchar.','El objetivo de conversar.','Los datos de las sesiones.'],['¿Por qué objeta Marta?','Algunos usos ayudan a participar.','Some uses support participation.'],['¿Qué sería una generalización excesiva?','Decir que todo uso del móvil distrae.','Observar interrupciones.','Separar momentos de consulta.'],['¿Qué acepta Marta?','Una norma que distingue distracción y apoyo.','A rule distinguishing distraction from support.'],['¿Qué conclusión tiene apoyo?','Limitemos las notificaciones y conservemos consultas útiles.','Prohibamos cualquier apoyo.','Toda consulta debe ser permanente.'],'The response addresses the objection by distinguishing functions rather than denying the original concern.'),
scene('La ruta más corta','El grupo prepara un paseo para visitantes. Luis prefiere la ruta corta porque deja tiempo para conversar. Ana defiende una ruta más larga que incluye un mercado interesante. En lugar de discutir qué lugar es mejor en general, comparan sus propuestas con el objetivo del encuentro: conocer el barrio sin terminar agotados. Elena recuerda que algunos participantes caminarán despacio. Luis utiliza ese dato para apoyar su opción, pero Ana pregunta si eliminar el mercado quitaría la oportunidad de hablar con vecinos. El grupo prueba ambos recorridos y registra tiempo, descansos y lugares para sentarse. La ruta larga ofrece más encuentros, aunque requiere una pausa adicional; la corta es cómoda, pero pasa por una calle ruidosa. Ninguna gana en todo. Marta propone empezar por la ruta corta y ofrecer una extensión voluntaria al mercado. Reconoce que dividir el grupo exige organizar un punto de reunión. La conclusión no borra los inconvenientes: los hace visibles y distribuye opciones. Luis y Ana apoyan el plan porque conserva la prioridad de un paseo accesible sin presentar una preferencia personal como solución universal.',[['los recorridos','routes'],['una extensión','an optional extension'],['agotados','exhausted']],['¿Qué criterio organiza la comparación?','Conocer el barrio sin agotar al grupo.','Visitar todos los lugares posibles.','Elegir la preferencia de Luis.'],['¿Por qué no gana una ruta en todo?','Ofrecen ventajas y límites distintos.','They have different advantages and limitations.'],['¿Qué exige la extensión voluntaria?','Un punto de reunión claro.','Eliminar el mercado.','Negar los descansos.'],['¿Cómo cambia la conclusión?','Combina una ruta base con una opción adicional.','It combines a base route and an optional extension.'],['¿Qué respuesta mantiene los límites visibles?','La opción sirve si organizamos bien el reencuentro.','No queda ningún inconveniente.','Todos deben caminar igual.'],'Compare options against an explicit purpose and retain the costs of the proposed compromise.')],[audio('Apoyo abrir el domingo porque mejora el acceso. Reconozco el esfuerzo de los voluntarios; por eso propongo cuatro pruebas, no abrir siempre desde ahora.','¿Qué función tiene reconocer el esfuerzo?','Limita la propuesta inicial.',['Elimina la necesidad de probar.','Niega el problema de acceso.'],'The concession produces a bounded trial.'),audio_text('La encuesta es útil, pero solo incluye a clientes habituales. Antes de decidir, necesitamos escuchar también a quienes compran de paso.','¿Qué información falta?','La opinión de quienes compran de paso.',['Views of passing customers.'],'The limitation is the excluded group.')],prod('argument',['Escribe «This example supports the idea but does not prove it».','Translate a bounded evidence claim.','Este ejemplo apoya la idea, pero no la demuestra.','Responde a una objeción sobre el esfuerzo proponiendo una prueba limitada.','Concede the effort and propose a limited trial.','Reconozco el esfuerzo; por eso propongo una prueba limitada.'],[('Defiende una propuesta con una razón, una objeción y una respuesta.','Build a supported argument and response.','Propongo abrir algunos domingos porque hay personas que trabajan el sábado. Reconozco que aumenta el esfuerzo. Por eso haría una prueba limitada con voluntarios y revisaría la asistencia.'),('Escribe dos párrafos sobre una mejora del barrio. Incluye un ejemplo, una objeción relevante y una conclusión limitada.','Write a qualified argument with counterargument.','Mantendría una opción en línea para las reuniones porque permite participar sin viajar. Una vecina pudo asistir por primera vez gracias a esa opción. Ese ejemplo muestra una posibilidad, pero no prueba que sirva para todos.\n\nReconozco que algunas conexiones fallan. Por eso conservaría también una opción presencial y preguntaría por el acceso antes de decidir. Propongo evaluar ambas posibilidades durante un mes.'),('Escribe una propuesta: posición, razón, ejemplo, objeción, respuesta y conclusión.','Write a connected proposal engaging with an objection.','Propongo una ruta corta porque necesitamos un paseo accesible. En la última salida algunas personas terminaron cansadas. Reconozco que el mercado queda fuera. Podríamos ofrecer una extensión voluntaria y fijar un punto de reunión. Por estas razones, probaría ese plan antes de repetirlo.')],[('Apoya una posición',['propongo','porque','por estas razones']),('Responde a una objeción',['aunque','reconozco','pero'])])))
b22.append(unit('Social and cultural topics','Discuss familiar social choices with evidence, perspectives and practical consequences','Accessible social topics; generalisation, comparison and trade-offs',[
core('El trabajo flexible puede ayudar, siempre que las tareas estén claras.','Flexible work can help, provided the tasks are clear.','estén',['están','estar'],'Siempre que presents a condition for the proposed benefit, using subjunctive here.','Marta: «¿Trabajar en casa resuelve cualquier problema?»','No; también necesitamos acuerdos claros.',['Sí, cualquier trabajo funciona igual.','Las condiciones no importan.'],'Apoya la flexibilidad con una condición sobre la comunicación.','El horario flexible puede ayudar, siempre que mantengamos una comunicación clara.'),
core('La tecnología facilita algunas gestiones, pero no sustituye todas las alternativas.','Technology makes some tasks easier, but does not replace every alternative.','facilita',['facilitan','facilitar'],'Algunas limits the claim; pero identifies a remaining need.','Ana: «¿Podemos cerrar la atención presencial?»','Antes debemos comprobar quién necesita esa alternativa.',['Sí, todos tienen el mismo acceso.','No hace falta preguntar.'],'Explica una ventaja digital y la necesidad de conservar atención presencial.','La opción digital ahorra tiempo, pero algunas personas necesitan atención presencial.'),
core('No se trata de elegir un ganador, sino de comparar necesidades distintas.','It is not about choosing a winner, but comparing different needs.','sino',['pero que','por eso'],'No… sino contrasts the rejected framing with the intended one.','Luis: «¿Qué barrio es mejor para todo el mundo?»','Depende de las necesidades; comparemos aspectos concretos.',['El mío es mejor sin ninguna razón.','Todos los barrios son idénticos.'],'Reformula una comparación absoluta como comparación de necesidades.','No se trata de elegir el mejor barrio, sino de comparar necesidades distintas.')],[
scene('Dos tardes de trabajo','Elena trabaja algunas tardes desde casa y otras en la oficina. Una compañera considera que en casa se concentra mejor; otra necesita separar físicamente trabajo y descanso. Cuando la empresa pide opiniones, Elena evita resumir la discusión como una pelea entre comodidad y compromiso. Explica que las tareas también cambian: redactar requiere concentración, mientras que una reunión con personas nuevas puede beneficiarse del encuentro presencial. Luis pregunta por la coordinación si cada persona elige horarios distintos. Elena reconoce ese límite y propone acordar momentos comunes, sin exigir presencia durante toda la semana. Una compañera añade que su vivienda no tiene un espacio tranquilo. El grupo incluye esa condición en la propuesta y mantiene puestos disponibles. La conclusión no establece una única forma de trabajar bien. Sugiere probar acuerdos según tarea y circunstancias, con una revisión del reparto de trabajo. Elena apoya la flexibilidad, pero no quiere que se convierta en una obligación de trabajar en casa. Las opiniones diferentes ayudan a definir qué recursos necesita cada persona y qué compromisos comparten. La evaluación preguntará por concentración, coordinación y descanso por separado.',[['la coordinación','coordination'],['el compromiso','commitment'],['el reparto','distribution']],['¿Qué distingue Elena?','Tareas y circunstancias diferentes.','Personas comprometidas y personas cómodas.','Una única necesidad universal.'],['¿Por qué conservan puestos en la oficina?','No todos tienen un espacio tranquilo en casa.','Not everyone has a quiet space at home.'],['¿Qué evita la propuesta?','Convertir la flexibilidad en obligación.','Coordinar reuniones.','Comparar necesidades.'],['¿Qué posición mantiene Elena?','Flexibilidad con recursos y acuerdos comunes.','Flexibility with resources and shared agreements.'],['¿Qué pregunta mejora la evaluación?','¿Cómo afecta cada opción a concentración y descanso?','¿Quién es más trabajador por estar aquí?','¿Por qué todos prefieren lo mismo?'],'Different circumstances qualify a general claim about working arrangements.'),
scene('Una gestión que cambió','Ana ayudó a su madre a pedir una cita en línea. El sistema evitó un viaje, pero la confirmación llegó a una carpeta que no conocía. Al contar la experiencia, Ana distingue dos ideas: la gestión fue más rápida y la información posterior no fue clara. Una vecina propone volver siempre al teléfono; Luis responde que a él el formulario le permite pedir citas fuera del horario de atención. Ninguna experiencia basta para eliminar la otra opción. Marta sugiere mejorar el mensaje de confirmación y mantener un canal de ayuda. Preguntan a varias personas qué paso resultó difícil, en lugar de preguntar únicamente si les gusta la tecnología. Algunos problemas se repiten y otros dependen del dispositivo. La oficina prueba un aviso más visible y explica dónde encontrar la confirmación. Ana vuelve a hacer la gestión con su madre; esta vez puede seguirla sin ayuda. Eso no demuestra que cualquier persona podrá hacerlo, pero permite comprobar una mejora concreta. El grupo concluye que simplificar un proceso no consiste solo en trasladarlo a una pantalla. También exige información comprensible y una alternativa cuando el procedimiento no funciona.',[['una carpeta','a folder'],['el canal de ayuda','support channel'],['el procedimiento','procedure']],['¿Qué diferencia hace Ana?','Rapidez de la gestión y claridad posterior.','Tecnología buena y personas malas.','Dos citas canceladas.'],['¿Por qué Luis valora el formulario?','Puede usarlo fuera del horario de atención.','He can use it outside opening hours.'],['¿Qué permite localizar dificultades?','Preguntar por pasos concretos.','Pedir una opinión general solamente.','Cerrar el teléfono.'],['¿Qué prueba la segunda gestión?','Una mejora concreta, no acceso universal.','A specific improvement, not universal access.'],['¿Qué conclusión respeta las experiencias?','Mejoremos el sistema y conservemos ayuda.','Cerremos cualquier alternativa.','Una gestión demuestra que todos pueden.'],'The passage separates usability evidence from a claim about every user.'),
scene('Aprender fuera del aula','El centro propone que un grupo practique español en el mercado. Diego ve una oportunidad para usar preguntas reales; Elena teme que pedir ayuda a comerciantes ocupados moleste. La profesora no descarta ninguna preocupación. Organiza primero una actividad en clase para preparar preguntas breves y después consulta qué puestos quieren participar. Algunos aceptan durante una hora tranquila y otros prefieren no hacerlo. El grupo respeta esa elección. En la visita, las conversaciones varían: una persona explica una receta y otra responde solo a una pregunta sobre precios. Ana cuenta que entendió menos de lo esperado, pero pudo pedir una repetición. Luis valora haber descubierto qué expresiones le faltaban. Al volver, no clasifican la experiencia como éxito total o fracaso. Comparan objetivos, condiciones y aprendizajes distintos. Elena reconoce que preparar el encuentro redujo la molestia posible. Diego admite que salir del aula no enseña automáticamente más. La profesora propone otra visita con preguntas mejor elegidas y agradecimientos claros. La práctica real complementa la preparación, y la reflexión posterior ayuda a convertir una conversación breve en un objetivo de aprendizaje.',[['los puestos','market stalls'],['clasifican','they classify'],['complementa','complements']],['¿Cómo preparan la visita?','Consultan a los puestos y preparan preguntas.','Interrumpen a cualquier persona.','Evitan cualquier pregunta.'],['¿Por qué no participan todos los puestos?','Algunos prefieren no hacerlo.','Some prefer not to take part.'],['¿Qué aprendizaje identifica Ana?','Puede pedir una repetición aunque no entienda todo.','No necesita más práctica.','Todos hablan igual.'],['¿Qué revisa Diego?','La idea de que salir del aula enseña automáticamente más.','The claim that going outside automatically teaches more.'],['¿Qué propuesta respeta el contexto?','Preparemos preguntas útiles y consultemos antes.','Hablemos más tiempo aunque estén ocupados.','Exijamos participar a todos.'],'Preparation and consent make real-world practice more useful without guaranteeing identical outcomes.'),
scene('La plaza sin coches','Durante una tarde, el ayuntamiento limita los coches en una plaza para probar otro uso del espacio. Marta disfruta del ruido menor y de las mesas para conversar. Un comerciante pregunta cómo recibir entregas; una vecina explica que necesita un acceso cercano para acompañar a su padre. Luis reconoce esos problemas, pero rechaza que impidan estudiar cualquier cambio. Propone distinguir tráfico habitual, entregas y necesidades de acceso. El ayuntamiento permite entregas a primera hora y conserva un punto de parada cercano. Durante la prueba cuentan usos distintos de la plaza y preguntan también a quienes encontraron dificultades. La tarde resulta agradable para muchos, aunque no resuelve cómo funcionaría la medida todos los días. Ana señala que el tiempo y la presencia de actividades especiales pudieron influir. El informe describe esas condiciones en vez de presentar una tarde como prueba definitiva. El grupo apoya continuar el estudio con otras fechas y una explicación más clara del acceso. La discusión pasa de coches contra personas a una comparación de necesidades concretas, beneficios posibles y costes que no deben quedar ocultos.',[['las entregas','deliveries'],['el tráfico','traffic'],['los costes','costs']],['¿Qué distingue el grupo?','Tráfico, entregas y necesidades de acceso.','Personas buenas y malas.','Dos plazas idénticas.'],['¿Por qué la tarde no prueba un resultado permanente?','Hubo condiciones especiales.','There were special conditions.'],['¿Qué debe incluir el informe?','Beneficios y dificultades de la prueba.','Solo las opiniones favorables.','Una conclusión sin condiciones.'],['¿Qué posición mantiene Luis?','Estudiar cambios sin ignorar problemas concretos.','Study changes without ignoring specific problems.'],['¿Qué conclusión es proporcionada?','Probemos otras fechas y aclaremos el acceso.','Una tarde resuelve todos los días.','Las dificultades no cuentan.'],'A successful trial supports further investigation without proving a universal outcome.')],[audio('Trabajar en casa me ayuda a concentrarme. Sin embargo, no todo el mundo tiene un espacio tranquilo. Mantendría puestos en la oficina y acordaría momentos comunes.','¿Qué defiende la persona?','Flexibilidad con alternativas y coordinación.',['Cerrar la oficina para todos.','Que todas las tareas son iguales.'],'The alternative accommodates different conditions.'),audio_text('La plaza estuvo más tranquila, pero era una tarde con actividades especiales. Antes de aplicar la medida siempre, conviene probar otros días.','¿Por qué pide más pruebas?','La primera tarde tenía condiciones especiales.',['The first trial had special conditions.'],'The evidence cannot yet be generalised.')],prod('social choices',['Explica que la opción digital ayuda, pero no sustituye todas las alternativas.','State a qualified benefit.','La opción digital ayuda, pero no sustituye todas las alternativas.','Reformula: no elegir ganador; comparar necesidades.','Use no… sino.','No se trata de elegir un ganador, sino de comparar necesidades.'],[('Compara dos formas de trabajar con ventajas, condiciones y una recomendación.','Compare arrangements with qualifications.','Trabajar en casa puede facilitar la concentración, pero no todos tienen espacio. Mantendría la oficina y acordaría horarios comunes según las tareas.'),('Escribe dos párrafos sobre tecnología, educación o vida de barrio. Distingue experiencia, generalización y propuesta.','Discuss a familiar social choice without unsupported generalisation.','Una gestión en línea me evitó un viaje, pero la confirmación no era clara. Esa experiencia permite identificar un problema concreto; no demuestra que cualquier sistema digital funcione mal.\n\nMejoraría las instrucciones y mantendría una forma de pedir ayuda. Antes de cerrar la atención presencial, preguntaría quién la necesita y por qué. Evaluaría pasos concretos, no solo una opinión general sobre tecnología.'),('Redacta una propuesta sobre un espacio compartido con dos necesidades diferentes, una solución y un límite.','Integrate perspectives into a practical recommendation.','Propongo reducir el tráfico habitual para crear un espacio tranquilo. Reconozco que las entregas y algunos accesos deben mantenerse. Podríamos reservar horarios y un punto de parada. Una prueba en varias fechas permitiría comparar beneficios y dificultades antes de decidir.')],[('Distingue perspectivas',['pero','sin embargo','reconozco']),('Propón con condiciones',['podríamos','antes de','según','siempre que'])])))
b22.append(unit('Formal and informal register','Adapt a truthful message to its recipient without losing essential facts','Recipient, greeting, request, degree of formality and closing',[
core('Le agradecería que confirmara la fecha antes del viernes.','I would appreciate it if you confirmed the date before Friday.','confirmara',['confirmaría','confirmó'],'Le agradecería que frames a polite request; confirmara fits that request rather than reporting a completed action.','Recepción: «¿En qué podemos ayudarle?»','Le agradecería que confirmara la fecha antes del viernes.',['Confirma ya o no hablo contigo.','La fecha cambió, pero no necesito respuesta.'],'Solicita formalmente que revisen una factura.','Le agradecería que revisara la factura.'),
core('¿Puedes confirmarme la hora cuando tengas un momento?','Can you confirm the time when you have a moment?','tengas',['tienes','tendrá'],'The message is friendly and the future moment is not fixed, so cuando takes tengas.','Luis: «Estoy en una reunión; te escribo luego».','Perfecto, confírmame la hora cuando puedas.',['Exijo respuesta inmediata.','No necesito saber ninguna hora.'],'Pide a una amiga que te avise cuando sepa la fecha.','Avísame cuando sepas la fecha, por favor.'),
core('El tono cambia, pero la petición y los datos deben mantenerse.','The tone changes, but the request and facts must remain.','deben',['debe','debemos que'],'Plural petición y datos require deben; adapting register does not justify changing the facts.','Ana: «¿Puedo hacer que el problema parezca más grave?»','No; adapta el tono sin exagerar lo ocurrido.',['Sí, inventa un daño mayor.','Quita los datos necesarios.'],'Explica que puedes cambiar el saludo, pero no los hechos.','Puedo cambiar el saludo, pero no los hechos.')],[
scene('La misma petición, dos mensajes','Ana necesita cambiar la hora de una reunión. A Luis le escribe: «¿Podemos quedar un poco más tarde? El tren llega a las seis». Al centro que organiza la actividad envía otro mensaje: explica la fecha, la hora prevista y el retraso del tren, y pregunta si sería posible incorporarse a las seis y media. No inventa una avería ni una urgencia para hacer la petición más convincente. Luis responde con una propuesta breve; el centro necesita consultar quién abrirá la puerta. Ana comprende que la diferencia no depende solo de palabras elegantes. Cada destinatario necesita información distinta para actuar. En el mensaje al centro añade su nombre y el grupo al que pertenece. En el mensaje a Luis esos datos resultarían innecesarios. Cuando recibe la confirmación, agradece a ambos la ayuda sin usar exactamente el mismo cierre. Después revisa los textos con Marta. Las dos comprueban que el motivo y la nueva hora coinciden. El registro cambió, pero la situación no. Una petición clara puede ser cercana o formal sin exagerar ni ocultar los datos que permiten responder.',[['el destinatario','recipient'],['incorporarse','join'],['el cierre','closing']],['¿Qué mantiene Ana en ambos mensajes?','El motivo y la hora que necesita.','El mismo saludo exacto.','Una avería inventada.'],['¿Por qué añade su grupo al centro?','El destinatario necesita identificar la actividad.','The recipient needs to identify the activity.'],['¿Qué hace formal la petición?','Información pertinente y un tono adecuado.','Palabras difíciles sin datos.','Exagerar la gravedad.'],['¿Qué comprueban Ana y Marta?','Que el cambio de tono no cambió la situación.','That changing tone did not change the facts.'],['¿Qué petición al centro encaja?','¿Sería posible incorporarme a las seis y media?','Oye, abre cuando llegue y punto.','El tren nunca llegó, aunque sí llegó.'],'Register adapts the form and relevant detail, not the truth of the message.'),
scene('Una factura discutida','Diego recibe una factura con dos entradas para un taller al que asistió una sola persona. Su primer borrador dice que el centro siempre cobra mal. Marta le pregunta si puede apoyar esa afirmación. Diego reconoce que solo conoce este caso y cambia el mensaje. Indica el número de factura, la fecha y la diferencia que observa. Pide que revisen el importe y adjunta la confirmación de una plaza. Mantiene un tono firme sin atribuir intención al error. Una empleada responde que el registro muestra dos reservas. Diego explica que canceló una antes del plazo y aporta el mensaje correspondiente. No trata la primera respuesta como un rechazo definitivo: añade el dato que faltaba. Al final el centro corrige la factura. Diego agradece la revisión y conserva los mensajes. Cuando cuenta el problema a Luis utiliza un tono más informal, pero mantiene la misma cronología. La reclamación funcionó porque permitió comprobar la discrepancia, no porque sonara más enfadada. Una petición formal puede defender un derecho y seguir siendo precisa, respetuosa y abierta a aclarar la información.',[['el importe','amount'],['la discrepancia','discrepancy'],['el plazo','deadline']],['¿Qué elimina Diego del borrador?','Una generalización sin apoyo.','El número de factura.','La petición de revisión.'],['¿Por qué aporta otro mensaje?','Prueba la cancelación dentro del plazo.','It shows cancellation before the deadline.'],['¿Qué permite resolver la discrepancia?','Datos verificables y una petición concreta.','Afirmar intención sin pruebas.','Cambiar la cronología.'],['¿Cómo caracteriza el tono final?','Firme, preciso y respetuoso.','Firm, precise and respectful.'],['¿Qué formulación sirve?','Le agradecería que revisara el importe adjunto.','Siempre engañáis a todo el mundo.','No quiero que revisen ningún dato.'],'A precise complaint distinguishes the observed error from an unsupported accusation.'),
scene('El correo del equipo','Elena prepara un correo para pedir a su responsable que cambie un turno. A una compañera ya le explicó que necesita acompañar a un familiar. En el correo formal no comparte detalles privados innecesarios. Indica qué turno solicita cambiar, propone una alternativa y pregunta si encaja con las necesidades del equipo. Luis le sugiere una fórmula muy larga llena de disculpas. Elena decide que esa versión oculta la petición principal. Mantiene un saludo adecuado y una explicación breve. La responsable responde que la alternativa dejaría una tarea sin cubrir. Elena propone otro intercambio después de consultar a su compañera. No presenta ese acuerdo como confirmado hasta recibir su permiso. Cuando finalmente lo tiene, envía un mensaje claro con ambas fechas. La responsable acepta y agradece que haya considerado el trabajo pendiente. Elena aprende que ser formal no significa sonar distante ni escribir mucho. Significa ayudar al destinatario a comprender una petición, sus razones y sus consecuencias. La cercanía con la compañera y el respeto a la responsable pueden coexistir sin cambiar los hechos ni revelar información que no hace falta.',[['el turno','shift'],['cubrir','cover'],['el permiso','permission']],['¿Qué evita Elena?','Detalles privados innecesarios.','Explicar el turno.','Proponer alternativas.'],['¿Por qué cambia la primera alternativa?','Dejaría una tarea sin cubrir.','It would leave a task uncovered.'],['¿Qué debe comprobar antes de confirmar?','El acuerdo de su compañera.','La opinión de todas las familias.','Una disculpa más larga.'],['¿Qué entiende por formalidad útil?','Claridad, respeto e información pertinente.','Clarity, respect and relevant information.'],['¿Qué petición es proporcionada?','¿Sería posible cambiar este turno por el del martes?','Ya he cambiado todo sin consultar.','No diré qué fecha necesito.'],'The register supports an actionable request while respecting privacy and unconfirmed arrangements.'),
scene('Una invitación para varios públicos','Marta organiza una presentación del proyecto del barrio. Invita a una amiga, a un colega y a una entidad que podría prestar una sala. La amiga recibe un mensaje cercano con lugar y hora. El colega necesita saber qué parte del proyecto se va a presentar. La entidad recibe una explicación breve del propósito y una petición de disponibilidad. Marta conserva la fecha en las tres versiones y no afirma que la sala esté confirmada. Ana revisa el anuncio y detecta que uno de los textos promete una actividad gratuita, aunque todavía no han decidido si habrá gastos. Marta corrige esa frase en todas las versiones. Después añade una forma de contacto y un plazo razonable para responder. No usa el mismo cierre con cada destinatario, pero tampoco presenta proyectos distintos para obtener apoyo. La entidad pregunta por duración y número de asistentes; Marta responde con una estimación claramente identificada. Cuando termina, el grupo guarda una lista de datos comunes para futuras invitaciones. Adaptar el registro facilita la relación, mientras que comprobar los datos evita que distintas personas organicen expectativas incompatibles.',[['la entidad','organisation'],['la disponibilidad','availability'],['una estimación','an estimate']],['¿Qué dato permanece en las tres versiones?','La fecha.','Un saludo idéntico.','Una sala ya confirmada.'],['¿Por qué corrige la gratuidad?','Todavía no han decidido los gastos.','Costs have not yet been decided.'],['¿Qué evita la lista de datos comunes?','Expectativas incompatibles.','Tonos diferentes.','Pedir información.'],['¿Cómo presenta el número de asistentes?','Como una estimación.','As an estimate.'],['¿Qué mensaje a la entidad es adecuado?','Quisiéramos consultar la disponibilidad de la sala.','La sala ya es nuestra sin confirmación.','Prometemos datos que no conocemos.'],'Tailor information to the recipient while keeping confirmed facts consistent.')],[audio('Al centro le escribiré con la fecha y el número de reserva. A Luis le mandaré un mensaje breve. La petición será la misma: confirmar la nueva hora.','¿Qué cambia entre los mensajes?','El registro y los datos pertinentes.',['La hora solicitada.','Los hechos del retraso.'],'The purpose remains while presentation changes.'),audio_text('La factura muestra dos plazas. Adjuntaré la cancelación y pediré una revisión. No afirmaré que siempre cobran mal; solo conozco este caso.','¿Qué evita la persona?','Una generalización sin pruebas.',['An unsupported generalisation.'],'The complaint focuses on a verifiable case.')],prod('register',['Solicita formalmente revisar una factura. Usa le agradecería.','Make the taught formal request.','Le agradecería que revisara la factura.','Pide informalmente a Luis que confirme la hora cuando pueda.','Use a friendly request about a future moment.','Luis, confírmame la hora cuando puedas.'],[('Escribe una petición formal con dato, motivo, alternativa y cierre.','Write a concise formal request.','Buenos días: tengo una reserva para el viernes a las seis. El tren llega más tarde de lo previsto. ¿Sería posible incorporarme a las seis y media? Les agradecería la confirmación. Muchas gracias.'),('Escribe dos versiones de una petición: una para un amigo y otra para una entidad. Mantén los hechos y adapta el registro.','Adapt the same facts to two recipients.','Hola, Luis. El tren llega a las seis. ¿Podemos quedar a las seis y media? Gracias.\n\nBuenos días: les escribo sobre la actividad del viernes. Mi tren llega a las seis, por lo que no podré estar a la hora prevista. ¿Sería posible incorporarme a las seis y media? Agradecería su confirmación. Un saludo.'),('Redacta una reclamación precisa y respetuosa: dato comprobable, diferencia observada, petición y documentación.','Write a factual complaint with an actionable request.','Buenos días: la factura indica dos plazas, pero cancelé una dentro del plazo. Adjunto la confirmación y el mensaje de cancelación. Le agradecería que revisara el importe. Quedo pendiente de su respuesta. Muchas gracias.')],[('Incluye una petición clara',['sería posible','agradecería','confirmarme']),('Mantén datos verificables',['fecha','viernes','factura','reserva','confirmación'])])))
b22.append(unit('Reported speech and information','Relay claims accurately, attribute perspectives and retain uncertainty','Reporting verbs, source attribution, reference time and qualified paraphrase',[
core('La coordinadora explicó que todavía faltaba confirmar el horario.','The coordinator explained that the timetable still needed confirmation.','faltaba',['faltaría que','faltaban'],'Faltaba reports an unresolved task at that time; it does not turn the timetable into a confirmed fact.','Ana: «¿Entonces ya está confirmado?»','No; explicó que todavía faltaba confirmarlo.',['Sí, una explicación confirma cualquier cosa.','No dijo nada sobre el horario.'],'Transmite que Luis dijo que aún necesitaba comprobar la fecha.','Luis dijo que todavía necesitaba comprobar la fecha.'),
core('Según Elena, la opción sería útil si se mantuviera una alternativa.','According to Elena, the option would be useful if an alternative were retained.','mantuviera',['mantendría','mantiene mañana'],'Preserve Elena’s condition: the usefulness was not claimed without an alternative.','Marta: «¿Eso es tu opinión o la de Elena?»','Es la posición de Elena; yo todavía estoy comparando opciones.',['Es una verdad universal sin condiciones.','Elena no dijo nada.'],'Atribuye a Luis la idea de probar antes de decidir.','Según Luis, convendría hacer una prueba antes de decidir.'),
core('No afirmó que la medida funcionara en todos los casos.','She did not claim that the measure worked in every case.','funcionara',['funcionó','funcionaría'],'The negative reporting frame does not assert the proposition. Funcionara keeps the possible result distinct from a confirmed fact.','Luis: «¿Podemos resumirlo como éxito universal?»','No; solo habló de los casos revisados.',['Sí, elimina los límites del mensaje.','No existen casos revisados.'],'Explica que Marta no afirmó un resultado universal.','Marta no afirmó que la medida funcionara en todos los casos.')],[
scene('El resumen que cambió una condición','Elena presenta una propuesta para ampliar una actividad. Dice que sería útil si se consiguiera apoyo para preparar la sala. Luis toma notas y después escribe al grupo que Elena quiere ampliar la actividad. La frase no es falsa, pero elimina una condición importante. Marta pregunta quién se ocupará de la preparación. Luis revisa sus notas y añade lo que faltaba. Elena agradece la corrección: no propuso ampliar a cualquier coste ni confirmó recursos que aún no tenían. El grupo distingue su posición de la decisión pendiente. Ana explica que ella apoya estudiar la opción, aunque necesita conocer el esfuerzo. Esa opinión tampoco se convierte en acuerdo definitivo. Preparan un resumen con tres apartados: propuesta, condiciones y preguntas abiertas. Antes de enviarlo, lo leen quienes intervinieron. No intentan copiar cada palabra, pero comprueban que la reformulación conserva el alcance de las afirmaciones. El siguiente encuentro empieza con información más clara. Luis entiende que resumir consiste en reducir palabras sin borrar relaciones importantes entre una idea, su autor y las condiciones bajo las que la defiende.',[['desde mi punto de vista','from my point of view'],['la reformulación','rephrasing'],['los recursos','resources']],['¿Qué perdió el primer resumen?','La condición sobre el apoyo.','El nombre de la actividad.','Una decisión ya aprobada.'],['¿Por qué Elena agradece la corrección?','No quería proponer una ampliación sin recursos.','She did not propose expansion without resources.'],['¿Qué separan los tres apartados?','Propuesta, condiciones y preguntas abiertas.','Opiniones verdaderas y falsas por persona.','Tres actividades aprobadas.'],['¿Qué aprende Luis sobre resumir?','Reducir palabras sin borrar condiciones.','Reduce words without removing conditions.'],['¿Qué resumen es fiel?','Elena propone ampliar si se consigue apoyo.','Elena confirma todos los recursos.','Todos aprobaron ampliar sin condiciones.'],'A report can retain the headline yet distort the proposal by omitting its condition.'),
scene('Una noticia todavía provisional','Ana lee que una ruta de autobús podría cambiar el mes siguiente. El artículo atribuye la información a un borrador y aclara que no hay una decisión final. Al compartirlo, Diego escribe que el autobús dejará de pasar por la plaza. Elena pregunta dónde se confirmó. Diego vuelve al texto y ve que convirtió una posibilidad en certeza. Corrige el mensaje y añade la fuente. Luis señala que una vecina oyó una fecha distinta, pero nadie sabe de dónde salió. El grupo conserva esa información como un comentario pendiente de comprobar, no como prueba de otro calendario. Ana consulta el anuncio oficial, que invita a enviar observaciones sobre dos opciones. Resume lo que sí está confirmado: existe una consulta y el plazo termina el viernes. Las rutas definitivas siguen abiertas. Después explica su preferencia por mantener la parada de la plaza y la identifica como opinión propia. El grupo puede discutir consecuencias sin inventar una decisión. La corrección no obliga a dejar de hablar del tema; permite hablar con un grado de certeza que corresponde a la información disponible.',[['el borrador','draft'],['las observaciones','comments'],['el plazo','deadline']],['¿Qué convirtió Diego en certeza?','Un cambio posible.','Un plazo confirmado.','Una opinión propia explícita.'],['¿Por qué corrige el mensaje?','La fuente no anunciaba una decisión final.','The source did not announce a final decision.'],['¿Qué dato pueden afirmar?','El plazo de la consulta termina el viernes.','La nueva ruta está aprobada.','La fecha oída es oficial.'],['¿Cómo presenta Ana su preferencia?','Como opinión propia.','As her own opinion.'],['¿Qué mensaje conserva el grado de certeza?','Hay una consulta; la decisión sigue pendiente.','La parada desaparecerá con seguridad.','Un comentario confirma el calendario.'],'Preserve modal language and distinguish confirmed process from an unconfirmed outcome.'),
scene('Quién dijo que funcionó','Marta prepara un informe sobre un taller. Un participante dijo que le ayudó a hablar con vecinos; otra persona señaló que necesitaba instrucciones más claras. El primer borrador resume que el taller funcionó bien. Ana pregunta para quién y en qué aspecto. Marta añade las voces por separado y aclara que no pidió una evaluación a todos. No afirmó que la actividad funcionara en todos los casos. Luis propone incluir también un comentario de una persona que se fue pronto, pero reconoce que solo lo escuchó de otro participante. En el informe identifica esa información como indirecta y evita presentarla como una declaración comprobada. El grupo distingue observaciones propias, opiniones recibidas y preguntas pendientes. Marta concluye que hay señales positivas y un problema de claridad que merece revisión. No convierte la crítica en rechazo de todo el taller ni el elogio en aprobación universal. Antes de publicar, consulta si puede citar los mensajes y ofrece resumirlos sin nombres. Relatar la experiencia de otros exige cuidar tanto el contenido como el permiso para compartirlo.',[['indirecta','second-hand'],['citar','quote'],['las señales','indications']],['¿Qué limita el informe final?','No recoge la evaluación de todos.','No hubo ningún comentario.','Todos rechazaron el taller.'],['¿Por qué marca un comentario como indirecto?','Marta no lo recibió de la persona original.','It was received second-hand.'],['¿Qué conclusión tiene apoyo?','Hay señales positivas y problemas de claridad.','El éxito fue universal.','La crítica elimina cualquier ventaja.'],['¿Qué cuidado añade Marta?','Pedir permiso para citar.','Request permission to quote.'],['¿Qué resumen respeta las voces?','Una persona valoró la conversación; otra pidió claridad.','Todos estuvieron plenamente satisfechos.','Nadie pidió cambios.'],'Attribution and scope prevent a summary from overstating the evidence.'),
scene('Ayer ya no es hoy','Luis recibe el lunes un mensaje de Elena: «Mañana hablaré con recepción y después os diré qué opciones hay». El martes Ana pregunta si ya conocen las opciones. Luis va a copiar la frase sin indicar cuándo se escribió, pero Marta observa que mañana podría entenderse como miércoles. Luis resume que Elena dijo el lunes que hablaría con recepción el martes. Todavía no sabe si lo hizo. Conserva esa diferencia entre una intención anunciada y una acción confirmada. Más tarde Elena responde que habló con recepción, pero que falta comprobar una sala. El grupo actualiza el resumen sin borrar el mensaje anterior. Ana distingue ahora lo prometido, lo realizado y lo pendiente. Nadie necesita cambiar automáticamente cada tiempo verbal: necesitan mantener la referencia temporal y el sentido del mensaje. Luis añade fechas cuando el contexto podría confundir. Así el grupo evita planificar sobre una palabra relativa que ya no señala el mismo día. La reformulación resulta más larga que una copia, pero permite entender qué información cambió y qué pregunta sigue abierta.',[['la referencia temporal','time reference'],['lo pendiente','what remains unresolved'],['relativa','relative']],['¿Qué problema tiene copiar mañana sin contexto?','Puede señalar otro día.','Confirma una sala.','Borra la recepción.'],['¿Por qué no afirma Luis que Elena ya habló?','El primer mensaje solo anunciaba una intención.','The first message only announced an intention.'],['¿Qué sigue pendiente tras la respuesta?','Comprobar una sala.','La llamada ya realizada.','El día del primer mensaje.'],['¿Qué hace Luis para evitar confusión?','Añade referencias de fecha cuando hace falta.','Adds dates when needed.'],['¿Qué resumen es preciso?','Dijo el lunes que hablaría el martes; falta confirmar la sala.','Mañana siempre significa miércoles.','Anunciar una llamada prueba que ocurrió.'],'Reported information requires a clear time reference and separation of intention from confirmed action.')],[audio('Elena dijo que ampliaría la actividad si hubiera apoyo. El resumen inicial quitó esa condición. Ya lo hemos corregido: la propuesta depende de conseguir ayuda.','¿Qué corrige el resumen?','Recupera una condición omitida.',['Cambia el nombre de Elena.','Confirma ayuda inexistente.'],'The condition is essential to the proposal.'),audio_text('El artículo habla de un cambio posible. Lo confirmado es la consulta y su plazo; la nueva ruta todavía no está decidida.','¿Qué sigue sin decidir?','La nueva ruta.',['The new route.'],'Possibility is not a final decision.')],prod('reporting',['Transmite: Elena dijo que faltaba confirmar el horario.','Report the unresolved information.','Elena dijo que todavía faltaba confirmar el horario.','Atribuye a Luis una propuesta de prueba antes de decidir.','Report a proposal with its source.','Según Luis, convendría hacer una prueba antes de decidir.'],[('Resume dos opiniones, conserva sus condiciones y distingue tu conclusión.','Attribute viewpoints and retain their limits.','Elena propone ampliar si se consigue apoyo. Luis teme aumentar demasiado el esfuerzo. Yo probaría una ampliación limitada y revisaría las tareas antes de decidir.'),('Escribe un resumen de una conversación con dos voces, información confirmada y una pregunta pendiente.','Write a faithful extended summary.','Ana explicó que la consulta termina el viernes. Diego había entendido que la ruta estaba aprobada, pero corrigió su mensaje al volver a la fuente.\n\nEl anuncio solo presenta opciones. Ana prefiere conservar la parada y lo expresa como opinión propia. Todavía necesitamos saber qué propuesta se elegirá. No afirmaría una decisión que no aparece en el documento.'),('Redacta un mensaje que distinga intención anunciada, acción realizada y tarea pendiente, con referencias de fecha claras.','Relay evolving information without changing certainty.','El lunes Elena dijo que hablaría con recepción el martes. Hoy confirmó que ya habló, pero falta comprobar una sala. La reserva no está cerrada. Según ella, tendrá una respuesta el viernes; esa fecha es una previsión, no una confirmación.')],[('Atribuye las voces',['según','dijo','explicó','confirmó']),('Mantén incertidumbre',['todavía','falta','pendiente','no está'])])))
b22.append(unit('Possibility, condition and consequence','Explain real and imagined conditions, distinguish uncertainty and reflect on past alternatives','Real/open conditions; imagined present and past; conditional perfect; limited perfect subjunctive',[
core('Si hubiéramos comprobado el horario, habríamos evitado la espera.','If we had checked the timetable, we would have avoided the wait.','hubiéramos',['habríamos','hemos que'],'Si hubiéramos comprobado describes an unreal past condition; habríamos evitado gives its imagined past consequence.','Luis: «¿Podemos cambiar lo que pasó?»','No, pero podemos aprender de lo que habríamos hecho de otra manera.',['Sí, esa frase borra el pasado.','La condición confirma que comprobamos el horario.'],'Expresa una alternativa pasada: reservar antes; conseguir una mesa.','Si hubiéramos reservado antes, habríamos conseguido una mesa.'),
core('Es posible que hayan cambiado la sala; conviene comprobarlo.','They may have changed the room; it is worth checking.','hayan',['han','habrían que'],'Es posible que presents uncertainty; hayan cambiado refers to a possible completed change without asserting it.','Ana: «¿Eso confirma el cambio?»','No; es una posibilidad que debemos comprobar.',['Sí, cualquier posibilidad es un hecho.','No se puede consultar.'],'Expresa la posibilidad de que hayan cancelado la reunión y pide comprobarla.','Es posible que hayan cancelado la reunión; conviene comprobarlo.'),
core('Si recibimos la confirmación hoy, podremos organizar la visita mañana.','If we receive confirmation today, we will be able to organise the visit tomorrow.','recibimos',['recibiríamos','recibamos'],'An open real condition uses present indicative after si; the result can use future.','Marta: «¿Ya está asegurada la visita?»','No; depende de recibir la confirmación.',['Sí, aunque nadie responda.','La visita ya ocurrió mañana.'],'Relaciona recibir respuesta hoy con reservar mañana.','Si recibimos la respuesta hoy, podremos reservar mañana.')],[
scene('La reserva que faltó','El grupo llegó al restaurante después de una visita y descubrió que no había mesas libres. Luis había pensado que, al ser temprano, podrían entrar sin reservar. Ana recordó que junto al restaurante se celebraba un encuentro que desconocían. Mientras buscaban otra opción, Luis dijo: «Si hubiéramos reservado antes, habríamos conseguido una mesa». Marta precisó que no podían saberlo con seguridad: quizá el local ya estaba lleno cuando planearon la salida. Reformularon la idea como una posibilidad razonable, no como un resultado demostrado. Encontraron otro café y cenaron más tarde. Al contar la experiencia, distinguieron la decisión real, las circunstancias conocidas después y la alternativa imaginada. No usaron el condicional para culparse por información que no tenían. El siguiente plan incluyó consultar disponibilidad y conservar una segunda opción. Ana añadió que reservar no elimina cualquier imprevisto. La reflexión fue útil porque produjo una mejora concreta sin prometer controlar todo. Imaginar un pasado distinto ayudó a revisar el proceso, aunque no permitió comprobar qué habría ocurrido en una situación que nunca llegó a existir.',[['la alternativa imaginada','imagined alternative'],['culparse','blame themselves'],['la disponibilidad','availability']],['¿Qué no pueden comprobar?','El resultado de una alternativa que no ocurrió.','Que llegaron al restaurante.','Que encontraron otro café.'],['¿Por qué Marta limita la afirmación de Luis?','El restaurante quizá ya estaba lleno antes.','The restaurant might already have been full.'],['¿Qué mejora nace de la reflexión?','Consultar y conservar una segunda opción.','Prometer eliminar todo imprevisto.','Cambiar el pasado.'],['¿Cómo usan la alternativa pasada?','Para aprender, no para asegurar un resultado imposible de comprobar.','To learn, not to claim an unverifiable result.'],['¿Qué frase es prudente?','Reservar antes podría haber ayudado; no sabemos el resultado.','Sabemos exactamente lo que habría ocurrido.','No había ninguna otra circunstancia.'],'An unreal past condition describes an alternative rather than evidence of its certain outcome.'),
scene('Una sala que quizá cambió','Elena recibe dos mensajes sobre una reunión. El primero indica la sala cuatro y el segundo menciona una entrada diferente, sin decir si cambió la sala. Luis concluye que la reunión se ha cancelado. Elena distingue los datos de esa interpretación: es posible que hayan cambiado el acceso, pero no hay noticia de cancelación. Consulta a recepción antes de enviar una alarma al grupo. Mientras espera, prepara un mensaje provisional que explica la duda y pide no salir todavía si necesitan acompañamiento. Ana pregunta si pueden mantener la hora. Elena responde que, si reciben la confirmación hoy, podrán organizar el encuentro de mañana. Esa condición sigue abierta. Recepción confirma después que la sala es la misma y que solo cambió la entrada. El grupo actualiza la información y conserva el horario. Luis reconoce que una posibilidad no justificaba afirmar una cancelación. La prudencia no consistió en esperar sin hacer nada, sino en actuar de forma proporcionada: consultar, comunicar lo incierto como incierto y preparar opciones que dependían de la respuesta. La próxima vez compararán los mensajes antes de sacar una conclusión.',[['la cancelación','cancellation'],['provisional','provisional'],['proporcionada','proportionate']],['¿Qué se confirmó finalmente?','Cambió la entrada, no la sala.','Se canceló la reunión.','Cambió el día.'],['¿Por qué Elena consulta?','Los mensajes no aclaran exactamente el cambio.','The messages do not specify the change clearly.'],['¿Qué error comete Luis?','Convierte una interpretación en un hecho.','Compara datos confirmados.','Pide información.'],['¿Cómo actúa Elena ante la incertidumbre?','Consulta y prepara opciones condicionadas.','She checks and prepares conditional options.'],['¿Qué mensaje respeta la información inicial?','Puede que haya cambiado el acceso; lo estamos comprobando.','La reunión está cancelada con seguridad.','La sala nueva ya está confirmada.'],'Distinguish a possible completed change from a confirmed cancellation.'),
scene('El plan y sus condiciones','Marta prepara una salida para el sábado. Si el centro confirma el transporte el jueves, comprarán las entradas el viernes. Si no responde, harán una actividad cercana sin reserva. Diego propone esperar hasta el sábado, pero Ana explica que entonces quizá no queden entradas. El grupo compara consecuencias sin afirmar que una rama del plan ya ocurrió. Elena añade un escenario imaginado: con más presupuesto, contratarían un transporte propio. No lo presenta como una opción disponible ahora. Marta deja esa idea para otra ocasión y mantiene dos alternativas reales. El jueves llega una respuesta parcial: hay vehículo, pero falta confirmar quién conducirá. El grupo no interpreta esa noticia como confirmación completa. Pregunta por el dato pendiente y fija una hora límite para decidir. Cuando termina el plazo sin respuesta, elige la actividad cercana. Algunos sienten decepción, pero entienden la condición que acordaron. Al revisar el plan, no dicen que esperar habría garantizado transporte. Reconocen que podían haber esperado más, a costa de perder la alternativa. La decisión refleja una comparación de riesgos y límites, no una predicción perfecta de lo que habría pasado.',[['una rama del plan','one branch of the plan'],['el presupuesto','budget'],['la hora límite','deadline']],['¿Qué eligen al terminar el plazo?','La actividad cercana.','Un transporte propio contratado.','Entradas ya agotadas.'],['¿Por qué no basta la respuesta parcial?','Falta confirmar quién conducirá.','The driver remains unconfirmed.'],['¿Qué opción no es real ahora?','Contratar transporte con un presupuesto mayor.','Pedir la confirmación.','Hacer una actividad cercana.'],['¿Qué reconoce la revisión?','Esperar más habría tenido costes y riesgos.','Waiting longer would have costs and risks.'],['¿Qué condición pertenece al plan real?','Si confirman el transporte, compraremos entradas.','Si tuviéramos dinero, ya lo tenemos.','Esperar garantiza cualquier respuesta.'],'Real conditions, imagined resources and past alternatives have different roles in planning.'),
scene('Una ayuda que llegó tarde','Ana envió una petición para preparar un taller, pero olvidó indicar qué tarea necesitaba. Recibió respuestas amables sin compromisos concretos. Cuando aclaró el mensaje, Elena pudo ayudar, aunque ya no quedaba tiempo para imprimir unas hojas. Ana reflexionó: si hubiera explicado la tarea antes, quizá habría recibido ayuda más útil. Mantiene quizá porque no sabe quién habría tenido tiempo. Luis señala otra condición: enviar un mensaje claro no obliga a nadie a aceptar. Ana está de acuerdo y no transforma su reflexión en una acusación al grupo. Para el siguiente taller prepara una lista breve con tarea, fecha y forma de responder. Es posible que algunas personas no hayan leído el nuevo mensaje todavía; por eso espera antes de interpretar el silencio. Si mañana recibe dos confirmaciones, repartirá la preparación. Si no, reducirá la actividad para poder hacerla sola. La experiencia conecta una alternativa pasada, una incertidumbre presente y un plan real. El objetivo no es controlar a los demás, sino comunicar mejor y elegir un tamaño de actividad que corresponda a los recursos confirmados.',[['los compromisos','commitments'],['corresponda','match'],['repartirá','will distribute']],['¿Qué faltaba en la primera petición?','Una tarea concreta.','Un saludo amable.','Una respuesta negativa.'],['¿Por qué conserva quizá en la reflexión?','No conoce la disponibilidad que habría habido.','She does not know who would have been available.'],['¿Qué evitaría interpretar ahora?','El silencio como rechazo seguro.','Los compromisos confirmados.','Las fechas conocidas.'],['¿Qué ajuste depende de las respuestas?','El tamaño y reparto de la actividad.','The size and distribution of the activity.'],['¿Qué reflexión es responsable?','Una petición clara habría ayudado, pero no garantizaba aceptación.','Una petición obliga a todo el mundo.','Sabemos que nadie leyó el mensaje.'],'Link an imagined past improvement to a real future plan without treating uncertainty as proof.')],[audio('Si hubiéramos explicado la tarea, quizá habríamos recibido ayuda antes. No podemos comprobarlo. Para la próxima vez, enviaremos una petición con fecha y tarea claras.','¿Qué distingue la persona?','Una alternativa pasada y una mejora futura.',['Un hecho pasado confirmado y otro inventado como cierto.','Una obligación para todos.'],'The alternative remains uncertain while the next action is concrete.'),audio_text('Es posible que hayan cambiado la entrada. La sala no está confirmada. Si recibimos respuesta hoy, podremos avisar mañana.','¿De qué depende avisar mañana?','De recibir respuesta hoy.',['Receiving a response today.'],'The future action is conditional on confirmation.')],prod('conditions',['Expresa: comprobar horario antes habría evitado la espera.','Use the taught past counterfactual.','Si hubiéramos comprobado el horario, habríamos evitado la espera.','Expresa una posibilidad: han cambiado la sala; hay que comprobarlo.','Use es posible que with a possible completed change.','Es posible que hayan cambiado la sala; hay que comprobarlo.'],[('Explica una alternativa pasada y una mejora futura sin asegurar lo que no sabes.','Reflect cautiously on an unreal past alternative.','Si hubiera explicado la tarea antes, quizá habría recibido ayuda útil. No puedo saberlo con certeza. La próxima vez indicaré la fecha y prepararé una alternativa.'),('Escribe dos párrafos que distingan hecho, posibilidad y condición. Incluye una reflexión pasada y un plan real.','Link different degrees of certainty across time.','Llegamos sin reserva y no había mesas. Si hubiéramos llamado antes, quizá habríamos encontrado otra hora, pero no sabemos qué disponibilidad había.\n\nEs posible que el restaurante haya cambiado sus horarios. Los comprobaré antes de organizar otra salida. Si recibimos confirmación el jueves, reservaremos el viernes; si no, elegiremos otra opción.'),('Envía un mensaje con una duda actual, una condición para actuar y una alternativa si no se cumple.','Write a practical conditional plan with uncertainty preserved.','Es posible que hayan cambiado la entrada; estoy consultando a recepción. Si recibimos respuesta hoy, podremos confirmar el encuentro de mañana. Si no, propongo una actividad cercana. Con una confirmación anterior habríamos organizado el transporte, pero ahora debemos usar la información disponible.')],[('Distingue posibilidad',['es posible','quizá','no sabemos']),('Relaciona condición y resultado',['si','habría','habríamos','podremos'])])))
b22.append(unit('The B2 project','Integrate narration, explanation, evidence, perspectives and a practical proposal for real recipients','Integrated extended communication; revision, register and evidence limits',[
core('Tras revisar las experiencias, proponemos una prueba con criterios claros.','After reviewing the experiences, we propose a trial with clear criteria.','proponemos',['proponer','propone'],'The conclusion follows the review and makes the next step testable.','Elena: «¿Habéis decidido aplicarlo siempre?»','No; proponemos una prueba con una evaluación clara.',['Sí, ya no hace falta revisar.','No tenemos ningún objetivo.'],'Concluye una revisión proponiendo una prueba limitada y una fecha para evaluarla.','Tras revisar las experiencias, propongo una prueba limitada y una fecha para evaluarla.'),
core('Reconocemos los límites del informe y explicamos qué sigue pendiente.','We acknowledge the report’s limitations and explain what remains unresolved.','Reconocemos',['Reconoce','Reconocer'],'A report can reach a useful conclusion while stating what the evidence cannot establish.','Luis: «¿Debemos ocultar lo que falta?»','No; señalarlo permite decidir con información proporcionada.',['Sí, una conclusión nunca tiene límites.','Inventemos las respuestas que faltan.'],'Explica que el informe aporta información, pero no responde a todo.','El informe aporta información útil, pero no responde a todas las preguntas.'),
core('Adaptaremos el mensaje al destinatario sin cambiar los hechos.','We will adapt the message to the recipient without changing the facts.','Adaptaremos',['Adaptaríamos ayer','Adaptan yo'],'The planned communication changes register, not the underlying account.','Marta: «¿Qué versión enviaremos a la entidad?»','Una petición formal con propósito, datos y próximos pasos.',['Una versión con hechos distintos.','Un texto sin ninguna petición.'],'Explica que escribirás formalmente al centro y brevemente al grupo manteniendo los datos.','Escribiré formalmente al centro y enviaré un mensaje breve al grupo, sin cambiar los datos.')],[
scene('Un informe después de la prueba','Durante un mes el grupo probó dos formas de organizar reuniones: una presencial y otra con participación en línea. Ana reúne notas de asistencia, comentarios y problemas técnicos. Antes de redactar el informe, descubre que una sesión coincidió con una fiesta y no puede compararla sin mencionar esa circunstancia. Luis quiere destacar que asistieron personas nuevas; Elena recuerda que algunos participantes habituales dejaron de intervenir. El informe conserva ambas observaciones y no calcula una satisfacción que nunca preguntaron. Marta escribe la cronología: qué pretendían, cómo prepararon la prueba, qué cambió y qué resultados observaron. Después distingue esas observaciones de las interpretaciones del grupo. La propuesta final mantiene ambas opciones durante otro periodo, con instrucciones más claras y una pregunta concreta sobre participación. No promete que la tecnología resolverá todos los problemas. Ana revisa los destinatarios: la entidad necesita una petición de espacio y el grupo necesita saber qué pasos seguirá. Preparan dos mensajes con los mismos datos. Antes de enviarlos, comprueban fuentes, condiciones y preguntas pendientes. El proyecto termina con una decisión revisable, no con una victoria de una opción sobre la otra. La información recogida permite actuar y también indica qué deberán comprobar después.',[['las observaciones','observations'],['revisable','open to revision'],['los destinatarios','recipients']],['¿Qué no puede calcular el informe?','Una satisfacción que no preguntaron.','La asistencia registrada.','Las fechas de la prueba.'],['¿Por qué menciona la fiesta?','Afecta a la comparación de una sesión.','It affects comparison of one session.'],['¿Qué distingue antes de concluir?','Observaciones e interpretaciones.','Datos y hechos inventados como iguales.','Amigos buenos y malos.'],['¿Cómo caracteriza la decisión?','Útil y revisable.','Useful and open to revision.'],['¿Qué conclusión corresponde?','Mantengamos opciones y comprobemos mejor la participación.','La tecnología resolvió todos los problemas.','Todos estuvieron satisfechos sin preguntar.'],'The integrated report links chronology, evidence limits, viewpoints and an actionable recommendation.'),
scene('La presentación y la pregunta difícil','Elena presenta el proyecto de un paseo accesible. Cuenta cómo empezó la idea, qué rutas compararon y por qué eligieron una ruta base con extensión voluntaria. Apoya su conclusión con tiempos y comentarios, pero aclara que la prueba tuvo pocos participantes. Una persona pregunta si el plan sirve para cualquiera. Elena no promete acceso universal: explica qué condiciones comprobaron y cuáles faltan. Luis añade que todavía necesitan revisar el punto de reunión con personas que no hicieron la prueba. Otra pregunta señala que dividir el grupo aumenta la organización. Marta reconoce el coste y describe quién se encargará de cada parte si consiguen apoyo. No presenta ese apoyo como confirmado. Al final proponen una segunda prueba y piden dos colaboraciones concretas. Ana escucha la grabación de una explicación anterior y detecta que hablaban demasiado de gustos personales. En la nueva presentación los gustos siguen visibles, pero no sustituyen los criterios. La respuesta a las preguntas no obliga a abandonar el proyecto. Ayuda a reducir su alcance, explicar sus condiciones y convertir una propuesta atractiva en un plan que puede comprobarse. Después envían un resumen fiel para quienes no asistieron.',[['desde mi punto de vista','from my point of view'],['los criterios','criteria'],['las colaboraciones','contributions of help']],['¿Qué límite reconoce Elena?','La prueba tuvo pocos participantes.','No probaron ninguna ruta.','El paseo ya sirve para cualquiera.'],['¿Por qué piden colaboración?','Dividir el grupo requiere organización.','Splitting the group needs coordination.'],['¿Qué cambia en la presentación?','Los criterios dejan de confundirse con gustos.','Los datos desaparecen.','El apoyo se inventa como confirmado.'],['¿Qué efecto tienen las preguntas?','Precisan condiciones y alcance.','They clarify conditions and scope.'],['¿Qué respuesta es responsable?','Hemos comprobado estas condiciones; otras siguen pendientes.','Cualquiera podrá hacerlo sin revisar.','Preguntar demuestra que el proyecto no sirve.'],'An integrated explanation responds to objections without overstating evidence or losing its practical goal.'),
scene('Dos textos para una decisión','Marta debe explicar al grupo por qué la exposición abrirá una semana más tarde. La sala había sido confirmada, pero una reparación obligó a cambiar el acceso. En el mensaje informal cuenta la secuencia, reconoce la decepción y propone usar el tiempo para revisar los textos. En el correo a la entidad añade número de reserva, fechas y una petición de confirmación del nuevo acceso. Mantiene en ambos que la sala está disponible y que la entrada sigue pendiente. No convierte la reparación en cancelación. Elena revisa el borrador formal y observa que una frase culpa al personal sin pruebas. Marta la cambia por una descripción de lo comunicado y pregunta cuándo podrán comprobar el acceso. Luis sugiere añadir una alternativa para quienes no puedan acudir en la nueva fecha. El grupo acuerda compartir fotos y comentarios después de la exposición, aclarando que no equivalen a vivirla en persona. La comunicación final integra hechos, reacción, petición y opciones. La revisión no consiste solo en corregir formas verbales: también comprueba el significado, el destinatario y las consecuencias de cada afirmación. Los dos textos permiten organizar el mismo proyecto sin crear versiones incompatibles de lo sucedido.',[['la reparación','repair'],['el borrador','draft'],['incompatibles','incompatible']],['¿Qué permanece pendiente?','Confirmar el nuevo acceso.','La disponibilidad de la sala.','El número de reserva.'],['¿Por qué cambia la frase sobre el personal?','Atribuía culpa sin pruebas.','It assigned blame without evidence.'],['¿Qué limitan sobre las fotos?','No equivalen a asistir personalmente.','Sustituyen cualquier experiencia.','Prueban que la entrada está lista.'],['¿Qué incluye revisar el texto?','Forma, significado, destinatario y consecuencias.','Form, meaning, recipient and consequences.'],['¿Qué mensaje conserva los hechos?','La sala está disponible; falta confirmar el acceso.','La exposición está cancelada definitivamente.','El personal causó todo a propósito.'],'Revision checks truthful communication and recipient needs as well as language form.'),
scene('El cierre que dejó una pregunta','Al terminar el proyecto, Ana pide al grupo escribir qué aprendió y qué haría de otra forma. Luis cuenta que había confundido una propuesta con una decisión porque el resumen no indicaba condiciones. Elena recuerda que una experiencia positiva no demuestra un resultado universal. Marta explica que una petición concreta permitió recibir ayuda, aunque no garantizó respuestas. Los textos no coinciden en todo, y el grupo no intenta eliminar esas diferencias. Organizan una síntesis con la cronología compartida, las perspectivas y las preguntas que siguen abiertas. Después preparan una recomendación breve para el centro y una reflexión más extensa para el grupo. Ana revisa su propia escritura: encuentra una conclusión demasiado absoluta y la limita a las condiciones observadas. No espera que una herramienta confirme automáticamente toda la calidad del relato. Compara el texto con el propósito, comprueba los datos y pide comentarios cuando hace falta. La reunión termina con una propuesta revisable y una fecha para volver a escuchar experiencias. Haber completado el curso no significa dominar cualquier situación ni obtener una certificación oficial. El siguiente paso es usar, revisar y ampliar lo aprendido mediante conversaciones reales y práctica continuada.',[['la síntesis','synthesis'],['revisable','open to revision'],['continuada','ongoing']],['¿Qué conserva la síntesis?','Cronología, perspectivas y preguntas abiertas.','Una sola opinión obligatoria.','Resultados universales inventados.'],['¿Por qué limita Ana su conclusión?','Solo tiene evidencia de ciertas condiciones.','She has evidence only for certain conditions.'],['¿Qué no puede asegurar una herramienta?','Toda la calidad de un relato abierto.','La fecha escrita.','La existencia de un modelo.'],['¿Qué considera el siguiente paso?','Usar, revisar y ampliar lo aprendido.','Use, revise and extend what was learned.'],['¿Qué afirmación final es correcta?','Completar el curso es un hito, no una certificación oficial.','Completarlo prueba dominio de cualquier situación.','Ya no hace falta practicar.'],'The final project makes a realistic learning milestone and continued revision explicit.')],[audio('La asistencia aumentó, pero no preguntamos por satisfacción. Proponemos mantener ambas opciones y evaluar la participación. Enviaremos los mismos datos con un registro adecuado a cada destinatario.','¿Qué evita el informe?','Afirmar una satisfacción no medida.',['Reconocer mayor asistencia.','Proponer una revisión.'],'A useful conclusion must not invent evidence.'),audio_text('La sala sigue disponible. Lo pendiente es confirmar la entrada tras la reparación. Cambiaremos la fecha y ofreceremos una alternativa a quienes no puedan venir.','¿Qué problema queda por resolver?','Confirmar la entrada.',['Confirming the entrance.'],'The change concerns access, not cancellation of the room.')],prod('integrated project',['Resume el límite: el informe ayuda, pero no responde a todas las preguntas.','State the report’s evidence limit.','El informe ayuda, pero no responde a todas las preguntas.','Propón una prueba con criterios claros después de revisar experiencias.','Write a bounded integrated conclusion.','Tras revisar las experiencias, propongo una prueba con criterios claros.'],[('Escribe un informe breve: propósito, cronología, resultado, dos perspectivas, límite y propuesta.','Integrate evidence and viewpoints into a practical report.','Probamos dos formatos para mejorar la participación. Primero preparamos las instrucciones y después celebramos cuatro reuniones. Asistieron personas nuevas, aunque otras intervinieron menos. Ana valora el acceso; Luis pide apoyo técnico. No preguntamos por satisfacción, así que no podemos afirmarla. Propongo mantener ambas opciones y evaluar la participación con preguntas claras.'),('Escribe dos o tres párrafos sobre un proyecto o experiencia. Incluye hechos, perspectivas, una objeción, respuesta y próximo paso. Revisa qué puedes afirmar con certeza.','Produce an extended integrated account and qualified recommendation.','Organizamos un paseo para conocer el barrio. Habíamos preparado una ruta larga, pero la primera prueba mostró que algunas personas terminaban cansadas. Comparamos tiempos, descansos y posibilidades de conversar.\n\nAna defendía visitar el mercado; Luis daba prioridad a un recorrido accesible. Reconocimos ambas necesidades y probamos una ruta base con una extensión voluntaria. La objeción principal era el esfuerzo de reunir al grupo después. Respondimos con un punto de encuentro y una persona responsable.\n\nLa prueba resultó útil, aunque participaron pocas personas. No afirmaría que el plan sirve para cualquiera. Propongo revisar el acceso con otros participantes antes de repetirlo. También pediría comentarios a quienes no pudieron asistir. Si conseguimos apoyo, organizaremos otra prueba el próximo mes.'),('Redacta un mensaje formal sobre el proyecto: propósito, hechos confirmados, límite, propuesta, petición y cierre. Después añade una versión breve para el grupo sin cambiar los datos.','Adapt an integrated project recommendation to two recipients.','Buenos días: probamos dos formatos de reunión para mejorar la participación. La asistencia aumentó, pero no recogimos una evaluación de satisfacción. Proponemos mantener ambas opciones durante otro mes y hacer preguntas más concretas. Le agradecería que confirmara la disponibilidad de la sala. Muchas gracias.\n\nHola a todos: queremos probar ambos formatos otro mes. Vinieron más personas, pero todavía no sabemos cómo valoraron la experiencia. Estamos esperando la confirmación de la sala; os avisaremos cuando llegue.')],[('Integra hechos y perspectivas',['primero','después','ana','luis','resultado']),('Limita y propone',['aunque','pero','no sabemos','propongo','proponemos'])])))
save('B2.2',b22)
